-- depends: 0009_trace_index_terminal_freeze

-- Durable authority foundation.  This is intentionally dual-mode: legacy
-- queue/outcome rows remain version 0 while 0011 wires the authorized
-- producers and consumers.  Do not treat this migration alone as a cutover.

-- Legacy foundation DDL below predates the explicit ``public.`` convention.
-- Keep the application schema first for this whole migration: a dedicated
-- superuser must never create Tracebed functions/tables in ``pg_catalog``.
-- Security-definer helpers set their own catalog-only path.
SET LOCAL search_path = public, pg_catalog;

-- The group roles may have been created by bootstrap.  A standalone owner-run
-- migration is safe too: create missing groups, but never silently repair an
-- existing unsafe role or a parent membership that can be reached via SET ROLE.
DO $$
DECLARE
    role_name text;
    role_state record;
    missing_roles text[] := ARRAY[]::text[];
BEGIN
    FOREACH role_name IN ARRAY ARRAY[
        'tracebed_api_group', 'tracebed_worker_group', 'tracebed_erasure_group'
    ]
    LOOP
        IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = role_name) THEN
            missing_roles := array_append(missing_roles, role_name);
            CONTINUE;
        END IF;
        SELECT rolcanlogin, rolsuper, rolcreatedb, rolcreaterole, rolinherit,
               rolbypassrls, rolreplication, rolconnlimit
          INTO role_state
          FROM pg_roles
         WHERE rolname = role_name;
        IF role_state.rolcanlogin OR role_state.rolsuper OR role_state.rolcreatedb
           OR role_state.rolcreaterole OR role_state.rolinherit
           OR role_state.rolbypassrls OR role_state.rolreplication
           OR role_state.rolconnlimit <> -1 THEN
            RAISE EXCEPTION 'unsafe tracebed authority group role'
                USING ERRCODE = '55000';
        END IF;
        IF EXISTS (
            SELECT 1
              FROM pg_auth_members AS membership
              JOIN pg_roles AS group_role
                ON group_role.oid = membership.member OR group_role.oid = membership.roleid
             WHERE group_role.rolname = role_name
        ) THEN
            RAISE EXCEPTION 'tracebed authority group retains a role membership'
                USING ERRCODE = '55000';
        END IF;
        IF EXISTS (
            SELECT 1
              FROM (
                  SELECT datdba AS owner_oid FROM pg_database
                  UNION ALL SELECT spcowner FROM pg_tablespace
                  UNION ALL SELECT nspowner FROM pg_namespace
                  UNION ALL SELECT relowner FROM pg_class
                  UNION ALL SELECT proowner FROM pg_proc
                  UNION ALL SELECT typowner FROM pg_type
                  UNION ALL SELECT extowner FROM pg_extension
                  UNION ALL SELECT lanowner FROM pg_language
                  UNION ALL SELECT collowner FROM pg_collation
                  UNION ALL SELECT conowner FROM pg_conversion
                  UNION ALL SELECT oprowner FROM pg_operator
                  UNION ALL SELECT opcowner FROM pg_opclass
                  UNION ALL SELECT opfowner FROM pg_opfamily
                  UNION ALL SELECT cfgowner FROM pg_ts_config
                  UNION ALL SELECT dictowner FROM pg_ts_dict
                  UNION ALL SELECT fdwowner FROM pg_foreign_data_wrapper
                  UNION ALL SELECT srvowner FROM pg_foreign_server
                  UNION ALL SELECT evtowner FROM pg_event_trigger
                  UNION ALL SELECT pubowner FROM pg_publication
                  UNION ALL SELECT subowner FROM pg_subscription
                  UNION ALL SELECT lomowner FROM pg_largeobject_metadata
                  UNION ALL SELECT stxowner FROM pg_statistic_ext
                  UNION ALL SELECT defaclrole FROM pg_default_acl
              ) AS ownership
              JOIN pg_roles AS owner ON owner.oid = ownership.owner_oid
             WHERE owner.rolname = role_name
        ) THEN
            RAISE EXCEPTION 'tracebed authority group owns database objects'
                USING ERRCODE = '55000';
        END IF;
        -- Do not let the temporary allowlist subtraction below hide a GRANT
        -- OPTION or a grant issued by somebody other than the object owner.
        -- Both are delegation authority, including on otherwise expected
        -- database/schema/table/function privileges.
        IF EXISTS (
            SELECT 1
              FROM (
                  SELECT database.datdba AS owner_oid, privilege.grantee,
                         privilege.grantor, privilege.is_grantable
                    FROM pg_database AS database
                    CROSS JOIN LATERAL aclexplode(
                        COALESCE(database.datacl, acldefault('d', database.datdba))
                    ) AS privilege
                  UNION ALL
                  SELECT tablespace.spcowner, privilege.grantee, privilege.grantor,
                         privilege.is_grantable
                    FROM pg_tablespace AS tablespace
                    CROSS JOIN LATERAL aclexplode(
                        COALESCE(tablespace.spcacl, acldefault('t', tablespace.spcowner))
                    ) AS privilege
                  UNION ALL
                  SELECT namespace.nspowner, privilege.grantee, privilege.grantor,
                         privilege.is_grantable
                    FROM pg_namespace AS namespace
                    CROSS JOIN LATERAL aclexplode(
                        COALESCE(namespace.nspacl, acldefault('n', namespace.nspowner))
                    ) AS privilege
                  UNION ALL
                  SELECT relation.relowner, privilege.grantee, privilege.grantor,
                         privilege.is_grantable
                    FROM pg_class AS relation
                    CROSS JOIN LATERAL aclexplode(
                        COALESCE(relation.relacl, acldefault('r', relation.relowner))
                    ) AS privilege
                  UNION ALL
                  SELECT routine.proowner, privilege.grantee, privilege.grantor,
                         privilege.is_grantable
                    FROM pg_proc AS routine
                    CROSS JOIN LATERAL aclexplode(
                        COALESCE(routine.proacl, acldefault('f', routine.proowner))
                    ) AS privilege
                  UNION ALL
                  SELECT type.typowner, privilege.grantee, privilege.grantor,
                         privilege.is_grantable
                    FROM pg_type AS type
                    CROSS JOIN LATERAL aclexplode(
                        COALESCE(type.typacl, acldefault('T', type.typowner))
                    ) AS privilege
                  UNION ALL
                  SELECT language.lanowner, privilege.grantee, privilege.grantor,
                         privilege.is_grantable
                    FROM pg_language AS language
                    CROSS JOIN LATERAL aclexplode(
                        COALESCE(language.lanacl, acldefault('l', language.lanowner))
                    ) AS privilege
                  UNION ALL
                  SELECT wrapper.fdwowner, privilege.grantee, privilege.grantor,
                         privilege.is_grantable
                    FROM pg_foreign_data_wrapper AS wrapper
                    CROSS JOIN LATERAL aclexplode(
                        COALESCE(wrapper.fdwacl, acldefault('F', wrapper.fdwowner))
                    ) AS privilege
                  UNION ALL
                  SELECT server.srvowner, privilege.grantee, privilege.grantor,
                         privilege.is_grantable
                    FROM pg_foreign_server AS server
                    CROSS JOIN LATERAL aclexplode(
                        COALESCE(server.srvacl, acldefault('S', server.srvowner))
                    ) AS privilege
                  UNION ALL
                  SELECT metadata.lomowner, privilege.grantee, privilege.grantor,
                         privilege.is_grantable
                    FROM pg_largeobject_metadata AS metadata
                    CROSS JOIN LATERAL aclexplode(
                        COALESCE(metadata.lomacl, acldefault('L', metadata.lomowner))
                    ) AS privilege
                  UNION ALL
                  SELECT default_acl.defaclrole, privilege.grantee,
                         privilege.grantor, privilege.is_grantable
                    FROM pg_default_acl AS default_acl
                    CROSS JOIN LATERAL aclexplode(default_acl.defaclacl) AS privilege
              ) AS acl_entry
              JOIN pg_roles AS grantee ON grantee.oid = acl_entry.grantee
             WHERE grantee.rolname = role_name
               AND (acl_entry.is_grantable
                    OR acl_entry.grantor IS DISTINCT FROM acl_entry.owner_oid)
        ) THEN
            RAISE EXCEPTION 'tracebed authority group retains unsafe grant delegation'
                USING ERRCODE = '55000';
        END IF;
        -- Bootstrap's only pre-0010 group grants are CONNECT and public
        -- schema USAGE. Remove exactly those inside this migration transaction
        -- before checking pg_shdepend; a failure rolls them back, while
        -- CREATE/TEMP or any other ACL dependency remains visible and fatal.
        EXECUTE format('REVOKE CONNECT ON DATABASE %I FROM %I', current_database(), role_name);
        EXECUTE format('REVOKE USAGE ON SCHEMA public FROM %I', role_name);
        IF EXISTS (
            SELECT 1
              FROM pg_shdepend AS dependency
              JOIN pg_roles AS dependent_role ON dependent_role.oid = dependency.refobjid
             WHERE dependent_role.rolname = role_name
               AND dependency.refclassid = 'pg_authid'::regclass
               AND dependency.deptype IN ('a', 'i', 'r', 't', 'o')
        ) THEN
            RAISE EXCEPTION 'tracebed authority group retains unsafe access dependencies'
                USING ERRCODE = '55000';
        END IF;
    END LOOP;
    FOREACH role_name IN ARRAY missing_roles
    LOOP
        EXECUTE format(
            'CREATE ROLE %I NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE '
            || 'NOINHERIT NOBYPASSRLS NOREPLICATION CONNECTION LIMIT -1',
            role_name
        );
    END LOOP;
END
$$;

/* Version-two receipts bind both the normalized ACL surface and the protected
-- schema surface.  They are installed after all 0010 objects exist so epoch
-- zero is a truthful genuine-0010 snapshot, not a partial-migration claim.
CREATE FUNCTION public.authority_acl_profile_actual_tuples(
    profile public.authority_acl_profile
) RETURNS SETOF bytea
LANGUAGE sql STABLE STRICT SECURITY INVOKER
SET search_path = pg_catalog, pg_temp
AS $$
WITH protected AS (
    SELECT oid, rolname
      FROM pg_catalog.pg_roles
     WHERE rolname IN (
         'tracebed_app', 'tracebed_api', 'tracebed_worker',
         'tracebed_api_group', 'tracebed_worker_group', 'tracebed_erasure_group'
     )
), partition_family(parent_name) AS (
    VALUES
        ('memory_item'), ('memory_link'), ('derived_state'), ('trace_index'),
        ('trace_subject'), ('subject_key'), ('outcome_event'), ('injection_log'),
        ('retrieval_event'), ('blackboard_entry'), ('invalidation_event'), ('spend_ledger'),
        ('review_queue'), ('memory_status_log'), ('memory_q_update'),
        ('trace_learning_job'), ('run_owner')
    UNION ALL
    SELECT parent_name
      FROM (VALUES ('subject_fence'), ('run_fence'), ('erase_run_set'), ('erase_mem_set'),
                   ('run_memory_binding'))
           AS erasure_parent(parent_name)
     WHERE profile = 'cutover_0012'::public.authority_acl_profile
), partition_index_spec(parent_name, suffix) AS (
    VALUES
        ('memory_item', 'hnsw'), ('memory_item', 'lex'), ('memory_item', 'bm25'),
        ('memory_item', 'status'), ('memory_item', 'subject'), ('memory_item', 'verdict'),
        ('trace_index', 'submitter'), ('trace_index', 'outstatus'),
        ('outcome_event', 'run'), ('injection_log', 'mem'), ('review_queue', 'mem'),
        ('trace_subject', 'subject'), ('memory_status_log', 'mem'),
        ('memory_q_update', 'scored'), ('trace_learning_job', 'ready'),
        ('trace_learning_job', 'lease'), ('run_owner', 'owner')
), partition_health AS (
    SELECT family.parent_name,
           COALESCE(
               bool_and(
                   leaf.oid IS NULL OR (
                       leaf_namespace.nspname = 'public'
                       AND leaf.relrowsecurity
                       AND leaf.relforcerowsecurity
                       AND leaf.relpartbound IS NOT NULL
                       -- Every concrete project leaf must retain precisely
                       -- the canonical cloned isolation policy.  Keep this
                       -- as a boolean family health check rather than a
                       -- per-project digest entry: creating a valid project
                       -- must not invalidate the append-only authority epoch.
                       AND (
                           SELECT count(*)
                             FROM pg_catalog.pg_policy AS child_policy
                            WHERE child_policy.polrelid = leaf.oid
                       ) = 1
                       AND EXISTS (
                           SELECT 1
                             FROM pg_catalog.pg_policy AS child_policy
                             JOIN pg_catalog.pg_policy AS parent_policy
                               ON parent_policy.polrelid = parent.oid
                            WHERE child_policy.polrelid = leaf.oid
                              AND child_policy.polname = leaf.relname || '_isolation'
                              AND parent_policy.polname = parent.relname || '_isolation'
                              AND child_policy.polcmd = parent_policy.polcmd
                              AND child_policy.polpermissive = parent_policy.polpermissive
                              AND child_policy.polroles IS NOT DISTINCT FROM parent_policy.polroles
                              AND child_policy.polroles IS NOT DISTINCT FROM parent_policy.polroles
                              AND COALESCE(
                                  pg_catalog.pg_get_expr(child_policy.polqual, child_policy.polrelid), ''
                              ) = COALESCE(
                                  pg_catalog.pg_get_expr(parent_policy.polqual, parent_policy.polrelid), ''
                              )
                              AND COALESCE(
                                  pg_catalog.pg_get_expr(child_policy.polwithcheck, child_policy.polrelid), ''
                              ) = COALESCE(
                                  pg_catalog.pg_get_expr(parent_policy.polwithcheck, parent_policy.polrelid), ''
                              )
                       )
                       -- Partition trigger clones are security-relevant for
                       -- terminal trace/job and immutable run-owner rows.
                       -- Require an exact bidirectional parent clone match;
                       -- an extra or disabled/replaced child trigger is
                       -- authority drift, not something provisioning repairs.
                       AND NOT EXISTS (
                           SELECT 1
                             FROM pg_catalog.pg_trigger AS parent_trigger
                            WHERE parent_trigger.tgrelid = parent.oid
                              AND NOT parent_trigger.tgisinternal
                              AND NOT EXISTS (
                                  SELECT 1
                                    FROM pg_catalog.pg_trigger AS child_trigger
                                   WHERE child_trigger.tgrelid = leaf.oid
                                     AND NOT child_trigger.tgisinternal
                                     AND child_trigger.tgparentid = parent_trigger.oid
                                     AND child_trigger.tgfoid = parent_trigger.tgfoid
                                     AND child_trigger.tgtype = parent_trigger.tgtype
                                     AND child_trigger.tgenabled = parent_trigger.tgenabled
                                     AND child_trigger.tgargs = parent_trigger.tgargs
                                     AND child_trigger.tgqual IS NOT DISTINCT FROM parent_trigger.tgqual
                                     AND child_trigger.tgoldtable IS NOT DISTINCT FROM parent_trigger.tgoldtable
                                     AND child_trigger.tgnewtable IS NOT DISTINCT FROM parent_trigger.tgnewtable
                                     AND child_trigger.tgconstraint IS NOT DISTINCT FROM parent_trigger.tgconstraint
                                     AND child_trigger.tgdeferrable IS NOT DISTINCT FROM parent_trigger.tgdeferrable
                                     AND child_trigger.tginitdeferred IS NOT DISTINCT FROM parent_trigger.tginitdeferred
                                     AND child_trigger.tgqual IS NOT DISTINCT FROM parent_trigger.tgqual
                                     AND child_trigger.tgoldtable IS NOT DISTINCT FROM parent_trigger.tgoldtable
                                     AND child_trigger.tgnewtable IS NOT DISTINCT FROM parent_trigger.tgnewtable
                                     AND child_trigger.tgconstraint IS NOT DISTINCT FROM parent_trigger.tgconstraint
                                     AND child_trigger.tgdeferrable IS NOT DISTINCT FROM parent_trigger.tgdeferrable
                                     AND child_trigger.tginitdeferred IS NOT DISTINCT FROM parent_trigger.tginitdeferred
                              )
                       )
                       AND NOT EXISTS (
                           SELECT 1
                             FROM pg_catalog.pg_trigger AS child_trigger
                            WHERE child_trigger.tgrelid = leaf.oid
                              AND NOT child_trigger.tgisinternal
                              AND NOT EXISTS (
                                  SELECT 1
                                    FROM pg_catalog.pg_trigger AS parent_trigger
                                   WHERE parent_trigger.tgrelid = parent.oid
                                     AND NOT parent_trigger.tgisinternal
                                     AND child_trigger.tgparentid = parent_trigger.oid
                                     AND child_trigger.tgfoid = parent_trigger.tgfoid
                                     AND child_trigger.tgtype = parent_trigger.tgtype
                                     AND child_trigger.tgenabled = parent_trigger.tgenabled
                                     AND child_trigger.tgargs = parent_trigger.tgargs
                                     AND child_trigger.tgqual IS NOT DISTINCT FROM parent_trigger.tgqual
                                     AND child_trigger.tgoldtable IS NOT DISTINCT FROM parent_trigger.tgoldtable
                                     AND child_trigger.tgnewtable IS NOT DISTINCT FROM parent_trigger.tgnewtable
                                     AND child_trigger.tgconstraint IS NOT DISTINCT FROM parent_trigger.tgconstraint
                                     AND child_trigger.tgdeferrable IS NOT DISTINCT FROM parent_trigger.tgdeferrable
                                     AND child_trigger.tginitdeferred IS NOT DISTINCT FROM parent_trigger.tginitdeferred
                                     AND child_trigger.tgqual IS NOT DISTINCT FROM parent_trigger.tgqual
                                     AND child_trigger.tgoldtable IS NOT DISTINCT FROM parent_trigger.tgoldtable
                                     AND child_trigger.tgnewtable IS NOT DISTINCT FROM parent_trigger.tgnewtable
                                     AND child_trigger.tgconstraint IS NOT DISTINCT FROM parent_trigger.tgconstraint
                                     AND child_trigger.tgdeferrable IS NOT DISTINCT FROM parent_trigger.tgdeferrable
                                     AND child_trigger.tginitdeferred IS NOT DISTINCT FROM parent_trigger.tginitdeferred
                              )
                       )
                       -- The only non-internal trigger on a project leaf is
                       -- an exact clone of an authority parent trigger.
                       -- Parent tables with no trigger consequently permit
                       -- none on their leaves.
                       AND NOT EXISTS (
                           SELECT 1
                             FROM pg_catalog.pg_trigger AS parent_trigger
                            WHERE parent_trigger.tgrelid = parent.oid
                              AND NOT parent_trigger.tgisinternal
                              AND NOT EXISTS (
                                  SELECT 1
                                    FROM pg_catalog.pg_trigger AS child_trigger
                                   WHERE child_trigger.tgrelid = leaf.oid
                                     AND NOT child_trigger.tgisinternal
                                     AND child_trigger.tgparentid = parent_trigger.oid
                                     AND child_trigger.tgfoid = parent_trigger.tgfoid
                                     AND child_trigger.tgtype = parent_trigger.tgtype
                                     AND child_trigger.tgenabled = parent_trigger.tgenabled
                                     AND child_trigger.tgargs = parent_trigger.tgargs
                              )
                       )
                       AND NOT EXISTS (
                           SELECT 1
                             FROM pg_catalog.pg_trigger AS child_trigger
                            WHERE child_trigger.tgrelid = leaf.oid
                              AND NOT child_trigger.tgisinternal
                              AND NOT EXISTS (
                                  SELECT 1
                                    FROM pg_catalog.pg_trigger AS parent_trigger
                                   WHERE parent_trigger.tgrelid = parent.oid
                                     AND NOT parent_trigger.tgisinternal
                                     AND child_trigger.tgparentid = parent_trigger.oid
                                     AND child_trigger.tgfoid = parent_trigger.tgfoid
                                     AND child_trigger.tgtype = parent_trigger.tgtype
                                     AND child_trigger.tgenabled = parent_trigger.tgenabled
                                     AND child_trigger.tgargs = parent_trigger.tgargs
                              )
                       )
                       -- Partition constraints must be the parent clones
                       -- (or identical inherited named constraints); neither
                       -- an omitted constraint nor a local extra check is a
                       -- harmless tenant variation.
                       AND NOT EXISTS (
                           SELECT 1
                             FROM pg_catalog.pg_constraint AS child_constraint
                            WHERE child_constraint.conrelid = leaf.oid
                              AND NOT EXISTS (
                                  SELECT 1
                                    FROM pg_catalog.pg_constraint AS parent_constraint
                                   WHERE parent_constraint.conrelid = parent.oid
                                     AND (
                                         child_constraint.conparentid = parent_constraint.oid
                                         OR (
                                             child_constraint.conparentid = 0
                                             AND child_constraint.conname = parent_constraint.conname
                                             AND child_constraint.contype = parent_constraint.contype
                                             AND child_constraint.condeferrable = parent_constraint.condeferrable
                                             AND child_constraint.condeferred = parent_constraint.condeferred
                                             AND pg_catalog.pg_get_constraintdef(child_constraint.oid, true)
                                                 = pg_catalog.pg_get_constraintdef(parent_constraint.oid, true)
                                         )
                                     )
                              )
                       )
                       AND NOT EXISTS (
                           SELECT 1
                             FROM pg_catalog.pg_constraint AS parent_constraint
                            WHERE parent_constraint.conrelid = parent.oid
                              AND NOT EXISTS (
                                  SELECT 1
                                    FROM pg_catalog.pg_constraint AS child_constraint
                                   WHERE child_constraint.conrelid = leaf.oid
                                     AND (
                                         child_constraint.conparentid = parent_constraint.oid
                                         OR (
                                             child_constraint.conparentid = 0
                                             AND child_constraint.conname = parent_constraint.conname
                                             AND child_constraint.contype = parent_constraint.contype
                                             AND child_constraint.condeferrable = parent_constraint.condeferrable
                                             AND child_constraint.condeferred = parent_constraint.condeferred
                                             AND pg_catalog.pg_get_constraintdef(child_constraint.oid, true)
                                                 = pg_catalog.pg_get_constraintdef(parent_constraint.oid, true)
                                         )
                                     )
                              )
                       )
                       -- Column clones are not trusted merely because the
                       -- partition is attached: typmod, collation, generated
                       -- and identity semantics are part of the authority
                       -- shape and must be bidirectionally identical.
                       AND NOT EXISTS (
                           SELECT 1
                             FROM pg_catalog.pg_attribute AS child_attribute
                            WHERE child_attribute.attrelid = leaf.oid
                              AND child_attribute.attnum > 0
                              AND NOT child_attribute.attisdropped
                              AND NOT EXISTS (
                                  SELECT 1
                                    FROM pg_catalog.pg_attribute AS parent_attribute
                                   WHERE parent_attribute.attrelid = parent.oid
                                     AND parent_attribute.attname = child_attribute.attname
                                     AND parent_attribute.attnum > 0
                                     AND NOT parent_attribute.attisdropped
                                     AND parent_attribute.atttypid = child_attribute.atttypid
                                     AND parent_attribute.atttypmod = child_attribute.atttypmod
                                     AND parent_attribute.attcollation = child_attribute.attcollation
                                     AND parent_attribute.attnotnull = child_attribute.attnotnull
                                     AND parent_attribute.attgenerated = child_attribute.attgenerated
                                     AND parent_attribute.attidentity = child_attribute.attidentity
                              )
                       )
                       AND NOT EXISTS (
                           SELECT 1
                             FROM pg_catalog.pg_attribute AS parent_attribute
                            WHERE parent_attribute.attrelid = parent.oid
                              AND parent_attribute.attnum > 0
                              AND NOT parent_attribute.attisdropped
                              AND NOT EXISTS (
                                  SELECT 1
                                    FROM pg_catalog.pg_attribute AS child_attribute
                                   WHERE child_attribute.attrelid = leaf.oid
                                     AND child_attribute.attname = parent_attribute.attname
                                     AND child_attribute.attnum > 0
                                     AND NOT child_attribute.attisdropped
                                     AND child_attribute.atttypid = parent_attribute.atttypid
                                     AND child_attribute.atttypmod = parent_attribute.atttypmod
                                     AND child_attribute.attcollation = parent_attribute.attcollation
                                     AND child_attribute.attnotnull = parent_attribute.attnotnull
                                     AND child_attribute.attgenerated = parent_attribute.attgenerated
                                     AND child_attribute.attidentity = parent_attribute.attidentity
                              )
                       )
                   )
               ),
               true
           )
           AND NOT EXISTS (
               SELECT 1
                 FROM public.project AS required_project
                WHERE required_project.status IN ('active', 'suspended')
                  AND required_project.deleted_at IS NULL
                  AND NOT EXISTS (
                      SELECT 1
                        FROM pg_catalog.pg_inherits AS expected_inheritance
                        JOIN pg_catalog.pg_class AS expected_leaf
                          ON expected_leaf.oid = expected_inheritance.inhrelid
                        JOIN pg_catalog.pg_namespace AS expected_namespace
                          ON expected_namespace.oid = expected_leaf.relnamespace
                       WHERE expected_inheritance.inhparent = parent.oid
                         AND expected_namespace.nspname = 'public'
                         AND pg_catalog.pg_get_expr(expected_leaf.relpartbound, expected_leaf.oid)
                             = pg_catalog.format('FOR VALUES IN (%L)', required_project.project_id)
                  )
           ) AS healthy
      FROM partition_family AS family
      LEFT JOIN pg_catalog.pg_class AS parent
        ON parent.relname = family.parent_name
       AND parent.relnamespace = 'public'::regnamespace
      LEFT JOIN pg_catalog.pg_inherits AS inheritance ON inheritance.inhparent = parent.oid
      LEFT JOIN pg_catalog.pg_class AS leaf ON leaf.oid = inheritance.inhrelid
      LEFT JOIN pg_catalog.pg_namespace AS leaf_namespace ON leaf_namespace.oid = leaf.relnamespace
     GROUP BY family.parent_name, parent.oid
), raw_entry AS (
    SELECT 'profile'::text AS class_name, profile::text AS object_name,
           ''::text AS grantee_name, ''::text AS privilege_name,
           ''::text AS grantor_name, false AS grantable
    UNION ALL
    SELECT 'database', database.datname, COALESCE(grantee.rolname, 'PUBLIC'),
           privilege.privilege_type, grantor.rolname, privilege.is_grantable
      FROM pg_catalog.pg_database AS database
      CROSS JOIN LATERAL pg_catalog.aclexplode(
          COALESCE(database.datacl, pg_catalog.acldefault('d', database.datdba))
      ) AS privilege
      LEFT JOIN protected AS grantee ON grantee.oid = privilege.grantee
      JOIN pg_catalog.pg_roles AS grantor ON grantor.oid = privilege.grantor
     -- The cutover's dedicated-cluster contract covers all four databases,
     -- not merely the database in which yoyo happens to be connected.  A
     -- PUBLIC CONNECT/TEMP grant on postgres/template0/template1 is runtime
     -- authority just as much as one on the Tracebed database.
     WHERE database.datname IN (
         pg_catalog.current_database(), 'postgres', 'template0', 'template1'
     )
       AND (privilege.grantee = 0 OR grantee.oid IS NOT NULL)
    UNION ALL
    SELECT 'schema', namespace.nspname, COALESCE(grantee.rolname, 'PUBLIC'),
           privilege.privilege_type, grantor.rolname, privilege.is_grantable
      FROM pg_catalog.pg_namespace AS namespace
      CROSS JOIN LATERAL pg_catalog.aclexplode(
          COALESCE(namespace.nspacl, pg_catalog.acldefault('n', namespace.nspowner))
      ) AS privilege
      LEFT JOIN protected AS grantee ON grantee.oid = privilege.grantee
      JOIN pg_catalog.pg_roles AS grantor ON grantor.oid = privilege.grantor
     WHERE privilege.grantee = 0 OR grantee.oid IS NOT NULL
    UNION ALL
    SELECT 'relation', namespace.nspname || '.' || relation.relname,
           COALESCE(grantee.rolname, 'PUBLIC'), privilege.privilege_type,
           grantor.rolname, privilege.is_grantable
      FROM pg_catalog.pg_class AS relation
      JOIN pg_catalog.pg_namespace AS namespace ON namespace.oid = relation.relnamespace
      CROSS JOIN LATERAL pg_catalog.aclexplode(
          COALESCE(relation.relacl, pg_catalog.acldefault('r', relation.relowner))
      ) AS privilege
      LEFT JOIN protected AS grantee ON grantee.oid = privilege.grantee
      JOIN pg_catalog.pg_roles AS grantor ON grantor.oid = privilege.grantor
     WHERE namespace.nspname IN ('public', 'tokenizer_catalog', 'bm25_catalog')
       AND relation.relkind IN ('r', 'p', 'S')
       AND (privilege.grantee = 0 OR grantee.oid IS NOT NULL)
    UNION ALL
    SELECT 'routine', namespace.nspname || '.' || routine.proname || '('
                         || pg_catalog.pg_get_function_identity_arguments(routine.oid) || ')',
           COALESCE(grantee.rolname, 'PUBLIC'), privilege.privilege_type,
           grantor.rolname, privilege.is_grantable
      FROM pg_catalog.pg_proc AS routine
      JOIN pg_catalog.pg_namespace AS namespace ON namespace.oid = routine.pronamespace
      CROSS JOIN LATERAL pg_catalog.aclexplode(
          COALESCE(routine.proacl, pg_catalog.acldefault('f', routine.proowner))
      ) AS privilege
      LEFT JOIN protected AS grantee ON grantee.oid = privilege.grantee
      JOIN pg_catalog.pg_roles AS grantor ON grantor.oid = privilege.grantor
     WHERE namespace.nspname IN ('public', 'tokenizer_catalog', 'bm25_catalog')
       AND (privilege.grantee = 0 OR grantee.oid IS NOT NULL)
    UNION ALL
    SELECT 'type', namespace.nspname || '.' || type.typname,
           COALESCE(grantee.rolname, 'PUBLIC'), privilege.privilege_type,
           grantor.rolname, privilege.is_grantable
      FROM pg_catalog.pg_type AS type
      JOIN pg_catalog.pg_namespace AS namespace ON namespace.oid = type.typnamespace
      CROSS JOIN LATERAL pg_catalog.aclexplode(
          COALESCE(type.typacl, pg_catalog.acldefault('T', type.typowner))
      ) AS privilege
      LEFT JOIN protected AS grantee ON grantee.oid = privilege.grantee
      JOIN pg_catalog.pg_roles AS grantor ON grantor.oid = privilege.grantor
     WHERE namespace.nspname IN ('public', 'tokenizer_catalog', 'bm25_catalog')
       AND (privilege.grantee = 0 OR grantee.oid IS NOT NULL)
)
SELECT public.authority_acl_set_digest(
    COALESCE(
        array_agg(
            pg_catalog.sha256(pg_catalog.convert_to(
                'tracebed.authority-acl-tuple/v1' || chr(0)
                || class_name || chr(0) || object_name || chr(0)
                || grantee_name || chr(0) || upper(privilege_name) || chr(0)
                || grantor_name || chr(0) || CASE WHEN grantable THEN '1' ELSE '0' END,
                'UTF8'
            ))
            ORDER BY class_name, object_name, grantee_name, privilege_name, grantor_name, grantable
        ), ARRAY[]::bytea[]
    )
)
  FROM entry
$$;

CREATE FUNCTION public.authority_schema_security_assert(
    profile public.authority_acl_profile
) RETURNS bytea
LANGUAGE sql STABLE STRICT SECURITY INVOKER
SET search_path = pg_catalog, pg_temp
AS $$
WITH profiled_namespace AS (
    -- Namespace inventory is fail-closed outside PostgreSQL's documented
    -- catalog, information-schema, toast, and per-backend temporary names.
    SELECT namespace.*
      FROM pg_catalog.pg_namespace AS namespace
     WHERE namespace.nspname NOT IN ('pg_catalog', 'information_schema', 'pg_toast')
       AND namespace.nspname !~ '^pg_temp_[0-9]+$'
       AND namespace.nspname !~ '^pg_toast_[0-9]+$'
       AND namespace.nspname !~ '^pg_toast_temp_[0-9]+$'
), relation_set AS (
    SELECT relation.oid, namespace.nspname, relation.relname,
           relation.relkind, relation.relrowsecurity, relation.relforcerowsecurity,
           parent_namespace.nspname AS parent_schema, parent.relname AS parent_name,
           pg_catalog.pg_get_expr(relation.relpartbound, relation.oid) AS partition_bound
      FROM pg_catalog.pg_class AS relation
      JOIN profiled_namespace AS namespace ON namespace.oid = relation.relnamespace
      LEFT JOIN pg_catalog.pg_inherits AS inheritance ON inheritance.inhrelid = relation.oid
      LEFT JOIN pg_catalog.pg_class AS parent ON parent.oid = inheritance.inhparent
      LEFT JOIN pg_catalog.pg_namespace AS parent_namespace ON parent_namespace.oid = parent.relnamespace
     WHERE namespace.nspname = 'public'
       AND (
           relation.relname IN (
               'project', 'principal', 'agent_type', 'agent_registration', 'principal_grant',
               'work_queue', 'dead_letter', 'outcome_event', 'trace_index',
               'trace_learning_job', 'run_owner', 'authority_acl_epoch', 'authority_cutover_state'
           )
           OR parent.relname IN (
               'memory_item', 'memory_link', 'derived_state', 'trace_index', 'trace_subject',
               'subject_key', 'outcome_event', 'injection_log', 'retrieval_event',
               'blackboard_entry', 'invalidation_event', 'spend_ledger', 'review_queue',
               'memory_status_log', 'memory_q_update', 'trace_learning_job', 'run_owner'
           )
       )
), raw_entry AS (
    SELECT 'profile'::text AS class_name, profile::text AS object_name, ''::text AS definition
    UNION ALL
    SELECT 'relation', nspname || '.' || relname,
           relkind || ':' || relrowsecurity || ':' || relforcerowsecurity || ':'
           || COALESCE(parent_schema || '.' || parent_name || ':' || partition_bound, '')
      FROM relation_set
     WHERE NOT is_partition
    UNION ALL
    SELECT 'policy', relation.nspname || '.' || relation.relname || '.' || policy.polname,
           policy.polcmd || ':' || policy.polpermissive || ':'
           || COALESCE(pg_catalog.pg_get_expr(policy.polqual, policy.polrelid), '') || ':'
           || COALESCE(pg_catalog.pg_get_expr(policy.polwithcheck, policy.polrelid), '')
      FROM pg_catalog.pg_policy AS policy
      JOIN relation_set AS relation ON relation.oid = policy.polrelid
    UNION ALL
    SELECT 'constraint', relation.nspname || '.' || relation.relname || '.' || constraint.conname,
           constraint.contype || ':' || constraint.condeferrable || ':' || constraint.condeferred
           || ':' || pg_catalog.pg_get_constraintdef(constraint.oid, true)
      FROM pg_catalog.pg_constraint AS constraint
      JOIN relation_set AS relation ON relation.oid = constraint.conrelid
    UNION ALL
    SELECT 'trigger', relation.nspname || '.' || relation.relname || '.' || trigger.tgname,
           trigger.tgtype::text || ':' || trigger.tgenabled || ':'
           || pg_catalog.pg_get_triggerdef(trigger.oid, true)
      FROM pg_catalog.pg_trigger AS trigger
      JOIN relation_set AS relation ON relation.oid = trigger.tgrelid
     WHERE NOT trigger.tgisinternal
    UNION ALL
    SELECT 'index', relation.nspname || '.' || relation.relname || '.' || index_class.relname,
           pg_catalog.pg_get_indexdef(index_class.oid) || ':' || index_data.indisvalid || ':'
           || index_data.indisready || ':' || index_data.indislive || ':' || index_data.indisunique
      FROM pg_catalog.pg_index AS index_data
      JOIN pg_catalog.pg_class AS index_class ON index_class.oid = index_data.indexrelid
      JOIN relation_set AS relation ON relation.oid = index_data.indrelid
    UNION ALL
    SELECT 'column', relation.nspname || '.' || relation.relname || '.' || attribute.attname,
           attribute.atttypid::regtype::text || ':' || attribute.attnotnull || ':'
           || COALESCE(pg_catalog.pg_get_expr(default_value.adbin, default_value.adrelid), '')
      FROM pg_catalog.pg_attribute AS attribute
      JOIN relation_set AS relation ON relation.oid = attribute.attrelid
      LEFT JOIN pg_catalog.pg_attrdef AS default_value
        ON default_value.adrelid = attribute.attrelid AND default_value.adnum = attribute.attnum
     WHERE attribute.attnum > 0 AND NOT attribute.attisdropped
    UNION ALL
    SELECT 'function', namespace.nspname || '.' || routine.proname || '('
                            || pg_catalog.pg_get_function_identity_arguments(routine.oid) || ')',
           pg_catalog.pg_get_functiondef(routine.oid)
      FROM pg_catalog.pg_proc AS routine
      JOIN pg_catalog.pg_namespace AS namespace ON namespace.oid = routine.pronamespace
     WHERE namespace.nspname = 'public'
       AND routine.proname IN (
           'project_enforce_lifecycle', 'principal_enforce_immutability',
           'agent_type_enforce_immutability', 'agent_registration_enforce_immutability',
           'principal_grant_enforce_immutability', 'run_owner_enforce_immutability',
           'authority_acl_epoch_append_guard', 'trace_index_enforce_terminal',
           'trace_learning_job_enforce_transition', 'subject_digests_are_valid',
           'authority_acl_security_assert', 'authority_schema_security_assert'
       )
)
SELECT public.authority_acl_set_digest(
    COALESCE(
        array_agg(
            pg_catalog.sha256(pg_catalog.convert_to(
                'tracebed.authority-schema-tuple/v1' || chr(0)
                || class_name || chr(0) || object_name || chr(0) || definition,
                'UTF8'
            )) ORDER BY class_name, object_name, definition
        ), ARRAY[]::bytea[]
    )
)
  FROM entry
$$;

REVOKE ALL PRIVILEGES ON FUNCTION public.authority_acl_security_assert(public.authority_acl_profile)
    FROM PUBLIC, tracebed_app, tracebed_api_group, tracebed_worker_group, tracebed_erasure_group;
REVOKE ALL PRIVILEGES ON FUNCTION public.authority_schema_security_assert(public.authority_acl_profile)
    FROM PUBLIC, tracebed_app, tracebed_api_group, tracebed_worker_group, tracebed_erasure_group;

-- yoyo 9.0.0's lock relation is the sole migration-control artifact carried
-- through the authority boundary.  Authenticate its complete topology before
-- epoch zero: a name-only table (or an inherited/RLS/rule-bearing lookalike)
-- is not a valid baseline and must never be signed as genuine_0010.
DO $$
DECLARE
    yoyo_oid oid;
BEGIN
    IF to_regclass('public._yoyo_lock') IS NOT NULL THEN
        RAISE EXCEPTION 'authority foundation refuses an unexpected underscored yoyo lock relation'
            USING ERRCODE = '55000';
    END IF;
    SELECT relation.oid INTO yoyo_oid
      FROM pg_class AS relation
      JOIN pg_namespace AS namespace ON namespace.oid = relation.relnamespace
     WHERE namespace.nspname = 'public' AND relation.relname = 'yoyo_lock';
    IF NOT FOUND
       OR NOT (
           SELECT relation.relkind = 'r'
              AND relation.relpersistence = 'p'
              AND NOT relation.relispartition
              AND relation.relowner = (SELECT oid FROM pg_roles WHERE rolname = current_user)
              AND NOT relation.relrowsecurity
              AND NOT relation.relforcerowsecurity
              AND relation.reloptions IS NULL
             FROM pg_class AS relation WHERE relation.oid = yoyo_oid
       )
       OR EXISTS (
           SELECT 1 FROM pg_inherits
            WHERE inhrelid = yoyo_oid OR inhparent = yoyo_oid
       )
       OR EXISTS (SELECT 1 FROM pg_policy WHERE polrelid = yoyo_oid)
       OR EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid = yoyo_oid AND NOT tgisinternal)
       OR EXISTS (SELECT 1 FROM pg_rewrite WHERE ev_class = yoyo_oid AND rulename <> '_RETURN')
       OR (
           SELECT array_agg(
               attribute.attname || '|' || format_type(attribute.atttypid, attribute.atttypmod)
               || '|' || attribute.attnotnull::text || '|' || attribute.attstorage::text || '|'
               || attribute.attcompression::text || '|'
               || COALESCE(pg_get_expr(default_value.adbin, default_value.adrelid), '')
               ORDER BY attribute.attnum
           )
             FROM pg_attribute AS attribute
             LEFT JOIN pg_attrdef AS default_value
               ON default_value.adrelid = attribute.attrelid AND default_value.adnum = attribute.attnum
            WHERE attribute.attrelid = yoyo_oid
              AND attribute.attnum > 0 AND NOT attribute.attisdropped
       ) IS DISTINCT FROM ARRAY[
           'locked|integer|true|p||1',
           'ctime|timestamp without time zone|false|p||',
           'pid|integer|true|p||'
       ]
       OR NOT (
           SELECT count(*) = 1
              AND bool_and(constraint_row.contype = 'p' AND constraint_row.conkey = ARRAY[1]::smallint[]
                           AND constraint_row.convalidated AND NOT constraint_row.condeferrable
                           AND NOT constraint_row.condeferred)
             FROM pg_constraint AS constraint_row WHERE constraint_row.conrelid = yoyo_oid
       )
       OR NOT (
           SELECT count(*) = 1
              AND bool_and(index_data.indisprimary AND index_data.indisvalid AND index_data.indisready
                           AND index_data.indislive AND index_data.indisunique
                           AND NOT index_data.indisexclusion AND NOT index_data.indisclustered
                           AND NOT index_data.indisreplident AND NOT index_data.indnullsnotdistinct
                           AND index_data.indimmediate AND index_data.indnkeyatts = 1
                           AND index_data.indnatts = 1 AND index_data.indkey = '1'::int2vector
                           AND index_data.indoption = '0'::int2vector
                           AND index_class.reloptions IS NULL)
             FROM pg_index AS index_data
             JOIN pg_class AS index_class ON index_class.oid = index_data.indexrelid
            WHERE index_data.indrelid = yoyo_oid
       )
       OR EXISTS (
           SELECT 1
             FROM aclexplode((SELECT relacl FROM pg_class WHERE oid = yoyo_oid)) AS privilege
             LEFT JOIN pg_roles AS grantee ON grantee.oid = privilege.grantee
             JOIN pg_roles AS grantor ON grantor.oid = privilege.grantor
            WHERE grantee.rolname IS DISTINCT FROM current_user
              AND NOT (
                  grantee.rolname = 'tracebed_app'
                  AND privilege.privilege_type IN ('SELECT', 'INSERT', 'UPDATE', 'DELETE')
                  AND grantor.rolname = current_user
                  AND NOT privilege.is_grantable
              )
       )
       OR (
           SELECT array_agg(privilege.privilege_type ORDER BY privilege.privilege_type)
             FROM aclexplode((SELECT relacl FROM pg_class WHERE oid = yoyo_oid)) AS privilege
             JOIN pg_roles AS grantee ON grantee.oid = privilege.grantee
             JOIN pg_roles AS grantor ON grantor.oid = privilege.grantor
            WHERE grantee.rolname = 'tracebed_app'
              AND grantor.rolname = current_user
              AND NOT privilege.is_grantable
       ) IS DISTINCT FROM ARRAY['DELETE', 'INSERT', 'SELECT', 'UPDATE']
    THEN
        RAISE EXCEPTION 'authority foundation refuses a noncanonical yoyo lock topology'
            USING ERRCODE = '55000';
    END IF;
END
$$;

    epoch, profile, profile_version, source_acl_digest, result_acl_digest,
    source_schema_digest, result_schema_digest, yoyo_lock_repair
) VALUES (
    0, 'genuine_0010', 2,
    public.authority_acl_security_assert('genuine_0010'),
    public.authority_acl_security_assert('genuine_0010'),
    public.authority_schema_security_assert('genuine_0010'),
    public.authority_schema_security_assert('genuine_0010'),
    'not_required'
);

*/
/* Deferred until the end of 0010, after the authority tables and receipt
 * primitives exist.  Kept here as design commentary for the bootstrap
 * sequence; the executable validators are installed at the end. */
/* The receipt is a semantic, OID-independent fence around the protected
-- authority surface.  It deliberately records only PUBLIC and Tracebed
-- identities: owner-implied privileges are not a grant surface and would
-- make the digest vary with the deployment's owner-role spelling.  Each
-- tuple is length-framed by ``authority_acl_set_digest`` before hashing.
CREATE FUNCTION public.authority_acl_security_assert(
    profile public.authority_acl_profile
) RETURNS bytea
LANGUAGE sql STABLE STRICT SECURITY INVOKER
SET search_path = pg_catalog, pg_temp
AS $$
WITH protected_roles AS (
    SELECT oid, rolname
      FROM pg_catalog.pg_roles
     WHERE rolname IN (
         'tracebed_app', 'tracebed_api', 'tracebed_worker',
         'tracebed_api_group', 'tracebed_worker_group', 'tracebed_erasure_group'
     )
), acl_tuple AS (
    SELECT 'profile'::text AS object_class,
           profile::text AS object_identity,
           ''::text AS grantee, ''::text AS privilege_type,
           ''::text AS grantor, false AS is_grantable
    UNION ALL
    SELECT 'database', database.datname,
           COALESCE(grantee.rolname, 'PUBLIC'), privilege.privilege_type,
           grantor.rolname, privilege.is_grantable
      FROM pg_catalog.pg_database AS database
      CROSS JOIN LATERAL pg_catalog.aclexplode(
          COALESCE(database.datacl, pg_catalog.acldefault('d', database.datdba))
      ) AS privilege
      LEFT JOIN protected_roles AS grantee ON grantee.oid = privilege.grantee
      JOIN pg_catalog.pg_roles AS grantor ON grantor.oid = privilege.grantor
     WHERE database.datname = pg_catalog.current_database()
       AND (privilege.grantee = 0 OR grantee.oid IS NOT NULL)
    UNION ALL
    SELECT 'schema', namespace.nspname,
           COALESCE(grantee.rolname, 'PUBLIC'), privilege.privilege_type,
           grantor.rolname, privilege.is_grantable
      FROM pg_catalog.pg_namespace AS namespace
      CROSS JOIN LATERAL pg_catalog.aclexplode(
          COALESCE(namespace.nspacl, pg_catalog.acldefault('n', namespace.nspowner))
      ) AS privilege
      LEFT JOIN protected_roles AS grantee ON grantee.oid = privilege.grantee
      JOIN pg_catalog.pg_roles AS grantor ON grantor.oid = privilege.grantor
     WHERE namespace.nspname IN ('public', 'tokenizer_catalog', 'bm25_catalog')
       AND (privilege.grantee = 0 OR grantee.oid IS NOT NULL)
    UNION ALL
    SELECT 'relation', namespace.nspname || '.' || relation.relname,
           COALESCE(grantee.rolname, 'PUBLIC'), privilege.privilege_type,
           grantor.rolname, privilege.is_grantable
      FROM pg_catalog.pg_class AS relation
      JOIN pg_catalog.pg_namespace AS namespace ON namespace.oid = relation.relnamespace
      CROSS JOIN LATERAL pg_catalog.aclexplode(
          COALESCE(relation.relacl, pg_catalog.acldefault('r', relation.relowner))
      ) AS privilege
      LEFT JOIN protected_roles AS grantee ON grantee.oid = privilege.grantee
      JOIN pg_catalog.pg_roles AS grantor ON grantor.oid = privilege.grantor
     WHERE namespace.nspname IN ('public', 'tokenizer_catalog', 'bm25_catalog')
       AND relation.relkind IN ('r', 'p', 'S')
       AND (privilege.grantee = 0 OR grantee.oid IS NOT NULL)
    UNION ALL
    SELECT 'routine', namespace.nspname || '.' || routine.proname || '('
                         || pg_catalog.pg_get_function_identity_arguments(routine.oid) || ')',
           COALESCE(grantee.rolname, 'PUBLIC'), privilege.privilege_type,
           grantor.rolname, privilege.is_grantable
      FROM pg_catalog.pg_proc AS routine
      JOIN pg_catalog.pg_namespace AS namespace ON namespace.oid = routine.pronamespace
      CROSS JOIN LATERAL pg_catalog.aclexplode(
          COALESCE(routine.proacl, pg_catalog.acldefault('f', routine.proowner))
      ) AS privilege
      LEFT JOIN protected_roles AS grantee ON grantee.oid = privilege.grantee
      JOIN pg_catalog.pg_roles AS grantor ON grantor.oid = privilege.grantor
     WHERE namespace.nspname IN ('public', 'tokenizer_catalog', 'bm25_catalog')
       AND (privilege.grantee = 0 OR grantee.oid IS NOT NULL)
    UNION ALL
    SELECT 'type', namespace.nspname || '.' || type.typname,
           COALESCE(grantee.rolname, 'PUBLIC'), privilege.privilege_type,
           grantor.rolname, privilege.is_grantable
      FROM pg_catalog.pg_type AS type
      JOIN pg_catalog.pg_namespace AS namespace ON namespace.oid = type.typnamespace
      CROSS JOIN LATERAL pg_catalog.aclexplode(
          COALESCE(type.typacl, pg_catalog.acldefault('T', type.typowner))
      ) AS privilege
      LEFT JOIN protected_roles AS grantee ON grantee.oid = privilege.grantee
      JOIN pg_catalog.pg_roles AS grantor ON grantor.oid = privilege.grantor
     WHERE namespace.nspname IN ('public', 'tokenizer_catalog', 'bm25_catalog')
       AND (privilege.grantee = 0 OR grantee.oid IS NOT NULL)
)
SELECT public.authority_acl_set_digest(
    COALESCE(
        array_agg(
            pg_catalog.sha256(
                pg_catalog.convert_to(
                    'tracebed.authority-acl-tuple/v1' || chr(0)
                    || object_class || chr(0) || object_identity || chr(0)
                    || grantee || chr(0) || upper(privilege_type) || chr(0)
                    || grantor || chr(0) || CASE WHEN is_grantable THEN '1' ELSE '0' END,
                    'UTF8'
                )
            )
            ORDER BY object_class, object_identity, grantee, privilege_type, grantor, is_grantable
        ),
        ARRAY[]::bytea[]
    )
)
  FROM acl_tuple
$$;

-- This includes the authority-bearing relations, their partition topology,
-- RLS/policies, constraints, triggers and security indexes.  The stable
-- identity is schema/name plus the parent/bound expression, never a catalog
-- OID.  A subsequent transition compares this digest to the append-only
-- ledger before it is allowed to publish credentials or rewrite ACLs.
CREATE FUNCTION public.authority_schema_security_assert(
    profile public.authority_acl_profile
) RETURNS bytea
LANGUAGE sql STABLE STRICT SECURITY INVOKER
SET search_path = pg_catalog, pg_temp
AS $$
WITH authority_relations AS (
    SELECT relation.oid, namespace.nspname, relation.relname,
           relation.relkind, relation.relrowsecurity, relation.relforcerowsecurity,
           parent_namespace.nspname AS parent_schema, parent.relname AS parent_name,
           pg_catalog.pg_get_expr(relation.relpartbound, relation.oid) AS partition_bound
      FROM pg_catalog.pg_class AS relation
      JOIN pg_catalog.pg_namespace AS namespace ON namespace.oid = relation.relnamespace
      LEFT JOIN pg_catalog.pg_inherits AS inheritance ON inheritance.inhrelid = relation.oid
      LEFT JOIN pg_catalog.pg_class AS parent ON parent.oid = inheritance.inhparent
      LEFT JOIN pg_catalog.pg_namespace AS parent_namespace ON parent_namespace.oid = parent.relnamespace
     WHERE namespace.nspname = 'public'
       AND (
           relation.relname IN (
               'project', 'principal', 'agent_type', 'agent_registration', 'principal_grant',
               'run_owner', 'work_queue', 'dead_letter', 'outcome_event', 'trace_index',
               'trace_learning_job', 'authority_acl_epoch', 'authority_cutover_state'
           )
           OR parent.relname IN (
               'memory_item', 'memory_link', 'derived_state', 'trace_index', 'trace_subject',
               'subject_key', 'outcome_event', 'injection_log', 'retrieval_event',
               'blackboard_entry', 'invalidation_event', 'spend_ledger', 'review_queue',
               'memory_status_log', 'memory_q_update', 'trace_learning_job', 'run_owner'
           )
       )
), schema_tuple AS (
    SELECT 'profile'::text AS object_class, profile::text AS object_identity, ''::text AS definition
    UNION ALL
    SELECT 'relation', nspname || '.' || relname,
           relkind || ':' || relrowsecurity || ':' || relforcerowsecurity || ':'
           || COALESCE(parent_schema || '.' || parent_name || ':' || partition_bound, '')
      FROM authority_relations
    UNION ALL
    SELECT 'policy', relation.nspname || '.' || relation.relname || '.' || policy.polname,
           policy.polcmd || ':' || policy.polpermissive || ':'
           || COALESCE(pg_catalog.pg_get_expr(policy.polqual, policy.polrelid), '') || ':'
           || COALESCE(pg_catalog.pg_get_expr(policy.polwithcheck, policy.polrelid), '')
      FROM pg_catalog.pg_policy AS policy
      JOIN authority_relations AS relation ON relation.oid = policy.polrelid
    UNION ALL
    SELECT 'constraint', relation.nspname || '.' || relation.relname || '.' || constraint.conname,
           constraint.contype || ':' || constraint.condeferrable || ':' || constraint.condeferred
           || ':' || pg_catalog.pg_get_constraintdef(constraint.oid, true)
      FROM pg_catalog.pg_constraint AS constraint
      JOIN authority_relations AS relation ON relation.oid = constraint.conrelid
    UNION ALL
    SELECT 'trigger', relation.nspname || '.' || relation.relname || '.' || trigger.tgname,
           trigger.tgtype::text || ':' || trigger.tgenabled || ':'
           || COALESCE(parent_trigger.tgname, '') || ':' || pg_catalog.pg_get_triggerdef(trigger.oid, true)
      FROM pg_catalog.pg_trigger AS trigger
      JOIN authority_relations AS relation ON relation.oid = trigger.tgrelid
      LEFT JOIN pg_catalog.pg_trigger AS parent_trigger ON parent_trigger.oid = trigger.tgparentid
     WHERE NOT trigger.tgisinternal
    UNION ALL
    SELECT 'index', relation.nspname || '.' || relation.relname || '.' || index_class.relname,
           pg_catalog.pg_get_indexdef(index_class.oid) || ':'
           || index_data.indisvalid || ':' || index_data.indisready || ':' || index_data.indislive
      FROM pg_catalog.pg_index AS index_data
      JOIN pg_catalog.pg_class AS index_class ON index_class.oid = index_data.indexrelid
      JOIN authority_relations AS relation ON relation.oid = index_data.indrelid
    UNION ALL
    SELECT 'column', relation.nspname || '.' || relation.relname || '.' || attribute.attname,
           attribute.atttypid::regtype::text || ':' || attribute.attnotnull || ':'
           || COALESCE(pg_catalog.pg_get_expr(default_value.adbin, default_value.adrelid), '')
      FROM pg_catalog.pg_attribute AS attribute
      JOIN authority_relations AS relation ON relation.oid = attribute.attrelid
      LEFT JOIN pg_catalog.pg_attrdef AS default_value
        ON default_value.adrelid = attribute.attrelid AND default_value.adnum = attribute.attnum
     WHERE attribute.attnum > 0 AND NOT attribute.attisdropped
    UNION ALL
    SELECT 'function', namespace.nspname || '.' || routine.proname || '('
                            || pg_catalog.pg_get_function_identity_arguments(routine.oid) || ')',
           pg_catalog.pg_get_functiondef(routine.oid)
      FROM pg_catalog.pg_proc AS routine
      JOIN pg_catalog.pg_namespace AS namespace ON namespace.oid = routine.pronamespace
     WHERE namespace.nspname = 'public'
       AND routine.proname IN (
           'project_enforce_lifecycle', 'principal_enforce_immutability',
           'agent_type_enforce_immutability', 'agent_registration_enforce_immutability',
           'principal_grant_enforce_immutability', 'run_owner_enforce_immutability',
           'authority_acl_epoch_append_guard', 'trace_index_enforce_terminal',
           'trace_learning_job_enforce_transition', 'subject_digests_are_valid',
           'authority_acl_security_assert', 'authority_schema_security_assert'
       )
)
SELECT public.authority_acl_set_digest(
    COALESCE(
        array_agg(
            pg_catalog.sha256(
                pg_catalog.convert_to(
                    'tracebed.authority-schema-tuple/v1' || chr(0)
                    || object_class || chr(0) || object_identity || chr(0) || definition,
                    'UTF8'
                )
            )
            ORDER BY object_class, object_identity, definition
        ),
        ARRAY[]::bytea[]
    )
)
  FROM schema_tuple
$$;

REVOKE ALL PRIVILEGES ON FUNCTION public.authority_acl_security_assert(public.authority_acl_profile)
    FROM PUBLIC, tracebed_app, tracebed_api, tracebed_worker,
         tracebed_api_group, tracebed_worker_group, tracebed_erasure_group;
REVOKE ALL PRIVILEGES ON FUNCTION public.authority_schema_security_assert(public.authority_acl_profile)
    FROM PUBLIC, tracebed_app, tracebed_api, tracebed_worker,
         tracebed_api_group, tracebed_worker_group, tracebed_erasure_group;

-- Epoch zero is written only after every 0010 authority relation, trigger,
-- partition and grant has been installed.  Its source/result match because
-- the foundation creates the genuine profile in one transaction.
    epoch, profile, profile_version, source_acl_digest, result_acl_digest,
    source_schema_digest, result_schema_digest, yoyo_lock_repair
) VALUES (
    0, 'genuine_0010', 2,
    public.authority_acl_security_assert('genuine_0010'),
    public.authority_acl_security_assert('genuine_0010'),
    public.authority_schema_security_assert('genuine_0010'),
    public.authority_schema_security_assert('genuine_0010'),
    'not_required'
);
*/

-- The authority ACL receipt is deliberately introduced with the foundation,
-- rather than 0011: a rollback leaves an auditable hardened-0010 state and a
-- later cutover appends to the same append-only chain.  No application or
-- runtime role receives table or function privileges.
CREATE TYPE public.authority_acl_profile AS ENUM (
    'genuine_0010', 'cutover_0011', 'cutover_0012', 'hardened_0010'
);
CREATE TYPE public.authority_yoyo_lock_repair AS ENUM (
    'not_required', 'revoked'
);

CREATE TABLE public.authority_acl_epoch (
    epoch bigint PRIMARY KEY CHECK (epoch >= 0),
    profile public.authority_acl_profile NOT NULL,
    profile_version integer NOT NULL CHECK (profile_version = 2),
    profile_contract_digest bytea NOT NULL CHECK (octet_length(profile_contract_digest) = 32),
    source_acl_digest bytea NOT NULL CHECK (octet_length(source_acl_digest) = 32),
    result_acl_digest bytea NOT NULL CHECK (octet_length(result_acl_digest) = 32),
    source_schema_digest bytea NOT NULL CHECK (octet_length(source_schema_digest) = 32),
    result_schema_digest bytea NOT NULL CHECK (octet_length(result_schema_digest) = 32),
    previous_receipt_digest bytea NOT NULL CHECK (octet_length(previous_receipt_digest) = 32),
    receipt_digest bytea NOT NULL UNIQUE CHECK (octet_length(receipt_digest) = 32),
    yoyo_lock_repair public.authority_yoyo_lock_repair NOT NULL,
    actor_session_user name NOT NULL,
    actor_current_user name NOT NULL,
    transitioned_at timestamptz NOT NULL
);
REVOKE ALL PRIVILEGES ON TABLE public.authority_acl_epoch
    FROM PUBLIC, tracebed_app, tracebed_api_group, tracebed_worker_group, tracebed_erasure_group;

-- The epoch stores only the compact root.  This owner-only normalized tuple
-- manifest is checked-in canonical contract data generated from the pinned
-- clean PG18 image.  It is deliberately *not* populated from the catalog at
-- migration time: assertions compare the complete current tuple set to this
-- immutable fixture in both directions before returning that root.
CREATE TABLE public.authority_acl_profile_tuple (
    profile public.authority_acl_profile NOT NULL,
    tuple_class text NOT NULL CHECK (tuple_class IN ('acl', 'schema')),
    tuple_digest bytea NOT NULL CHECK (octet_length(tuple_digest) = 32),
    PRIMARY KEY (profile, tuple_class, tuple_digest)
);
REVOKE ALL PRIVILEGES ON TABLE public.authority_acl_profile_tuple
    FROM PUBLIC, tracebed_app, tracebed_api_group, tracebed_worker_group, tracebed_erasure_group;

-- GENERATED_AUTHORITY_ACL_PROFILE_TUPLES_BEGIN
-- Fixture format: tracebed.authority-acl-profile-manifest/v1. Regenerate
-- only from a clean dedicated PG18 reference and review every tuple.
-- Generated from the pinned clean PG18 authority baseline by
-- scripts/generate_authority_acl_profile_manifest.py. These are contract
-- values, not a runtime catalog capture.
-- GENERATED_AUTHORITY_ACL_PROFILE_TUPLES_END

CREATE FUNCTION public.authority_acl_profile_tuple_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER
SET search_path = pg_catalog, pg_temp
AS $$
BEGIN
    RAISE EXCEPTION 'authority ACL canonical profile is immutable'
        USING ERRCODE = '55000';
END;
$$;
CREATE TRIGGER authority_acl_profile_tuple_immutable
    BEFORE INSERT OR UPDATE OR DELETE ON public.authority_acl_profile_tuple
    FOR EACH ROW EXECUTE FUNCTION public.authority_acl_profile_tuple_guard();
REVOKE ALL PRIVILEGES ON FUNCTION public.authority_acl_profile_tuple_guard()
    FROM PUBLIC, tracebed_app, tracebed_api_group, tracebed_worker_group, tracebed_erasure_group;

CREATE FUNCTION public.authority_acl_frame(value bytea) RETURNS bytea
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
SET search_path = pg_catalog
AS $$ SELECT int4send(octet_length(value)) || value $$;

CREATE FUNCTION public.authority_acl_set_digest(tuples bytea[]) RETURNS bytea
LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
SET search_path = pg_catalog, public
AS $$
DECLARE
    assembled bytea;
    tuple_value bytea;
    tuple_count bigint;
BEGIN
    IF COALESCE(array_ndims(tuples), 1) <> 1 THEN
        RAISE EXCEPTION 'authority ACL tuple set must be one-dimensional' USING ERRCODE = '22023';
    END IF;
    SELECT count(*), string_agg(public.authority_acl_frame(value), ''::bytea ORDER BY value)
      INTO tuple_count, assembled
      FROM unnest(tuples) AS item(value);
    RETURN pg_catalog.sha256(
        public.authority_acl_frame(convert_to('tracebed.authority-acl-set/v1', 'UTF8'))
        || int8send(tuple_count) || COALESCE(assembled, ''::bytea)
    );
END;
$$;

CREATE FUNCTION public.authority_acl_epoch_receipt(
    epoch_value bigint,
    profile_value public.authority_acl_profile,
    profile_version_value integer,
    contract_value bytea,
    source_value bytea,
    result_value bytea,
    source_schema_value bytea,
    result_schema_value bytea,
    repair_value public.authority_yoyo_lock_repair,
    previous_value bytea,
    session_actor name,
    current_actor name,
    transitioned_value timestamptz
) RETURNS bytea
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
SET search_path = pg_catalog, public
AS $$
    SELECT pg_catalog.sha256(
        public.authority_acl_frame(convert_to('tracebed.authority-acl-receipt/v2', 'UTF8'))
        || int8send(epoch_value)
        || public.authority_acl_frame(convert_to(profile_value::text, 'UTF8'))
        || int4send(profile_version_value)
        || public.authority_acl_frame(contract_value)
        || public.authority_acl_frame(source_value)
        || public.authority_acl_frame(result_value)
        || public.authority_acl_frame(source_schema_value)
        || public.authority_acl_frame(result_schema_value)
        || public.authority_acl_frame(convert_to(repair_value::text, 'UTF8'))
        || public.authority_acl_frame(previous_value)
        || public.authority_acl_frame(convert_to(session_actor::text, 'UTF8'))
        || public.authority_acl_frame(convert_to(current_actor::text, 'UTF8'))
        || int8send((extract(epoch FROM transitioned_value AT TIME ZONE 'UTC') * 1000000)::bigint)
    )
$$;

CREATE FUNCTION public.authority_acl_epoch_append_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER
SET search_path = pg_catalog, public
AS $$
DECLARE
    predecessor public.authority_acl_epoch%ROWTYPE;
    expected_profile public.authority_acl_profile;
    expected_epoch bigint;
    expected_contract bytea;
BEGIN
    IF TG_OP <> 'INSERT' THEN
        RAISE EXCEPTION 'authority ACL epoch is append-only' USING ERRCODE = '55000';
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended('tracebed.authority-acl-epoch/v1', 0));
    SELECT * INTO predecessor FROM public.authority_acl_epoch ORDER BY epoch DESC LIMIT 1 FOR UPDATE;
    IF NOT FOUND THEN
        expected_epoch := 0;
        expected_profile := 'genuine_0010';
    ELSE
        expected_epoch := predecessor.epoch + 1;
        expected_profile := CASE predecessor.profile
            WHEN 'genuine_0010' THEN 'cutover_0011'::public.authority_acl_profile
            WHEN 'hardened_0010' THEN 'cutover_0011'::public.authority_acl_profile
            WHEN 'cutover_0011' THEN NULL
            WHEN 'cutover_0012' THEN 'cutover_0011'::public.authority_acl_profile
        END;
    END IF;
    IF NEW.epoch <> expected_epoch
       OR (predecessor.profile = 'cutover_0011'::public.authority_acl_profile
           AND NEW.profile NOT IN ('hardened_0010'::public.authority_acl_profile,
                                   'cutover_0012'::public.authority_acl_profile))
       OR (predecessor.profile IS DISTINCT FROM 'cutover_0011'::public.authority_acl_profile
           AND NEW.profile <> expected_profile)
       OR NEW.profile_version <> 2
       OR NEW.source_acl_digest IS NULL OR octet_length(NEW.source_acl_digest) <> 32
       OR NEW.result_acl_digest IS NULL OR octet_length(NEW.result_acl_digest) <> 32
       OR NEW.source_schema_digest IS NULL OR octet_length(NEW.source_schema_digest) <> 32
       OR NEW.result_schema_digest IS NULL OR octet_length(NEW.result_schema_digest) <> 32
       OR NEW.previous_receipt_digest IS NOT NULL OR NEW.receipt_digest IS NOT NULL
       OR NEW.actor_session_user IS NOT NULL OR NEW.actor_current_user IS NOT NULL
       OR NEW.transitioned_at IS NOT NULL THEN
        RAISE EXCEPTION 'authority ACL epoch append is invalid' USING ERRCODE = '55000';
    END IF;
    -- Epoch zero is a self-authenticated baseline.  Every later transition
    -- must begin at exactly the prior authenticated result; accepting an
    -- arbitrary source digest would turn the append-only chain into a set of
    -- unrelated receipts.
    IF predecessor.epoch IS NULL THEN
        IF NEW.source_acl_digest IS DISTINCT FROM NEW.result_acl_digest
           OR NEW.source_schema_digest IS DISTINCT FROM NEW.result_schema_digest THEN
            RAISE EXCEPTION 'authority ACL epoch zero source must equal result'
                USING ERRCODE = '55000';
        END IF;
    ELSIF NEW.source_acl_digest IS DISTINCT FROM predecessor.result_acl_digest
       OR NEW.source_schema_digest IS DISTINCT FROM predecessor.result_schema_digest THEN
        RAISE EXCEPTION 'authority ACL epoch transition source does not match predecessor'
            USING ERRCODE = '55000';
    END IF;
    expected_contract := CASE NEW.profile
        WHEN 'genuine_0010' THEN decode('8420a2ef2badd4d5c2494ddc57c87a6e6b9460100f5bcd64a24cf18989d21668', 'hex')
        WHEN 'cutover_0011' THEN decode('119d169d86072837b6ccbab013fbd3b808bf9e1da2b09daab4794597f94dbb65', 'hex')
        WHEN 'cutover_0012' THEN decode('19d1b45aa71030489e9c077f47b03f3c9340e9aa90ccd8cbb1aea57e30d82c16', 'hex')
        WHEN 'hardened_0010' THEN decode('f809427341baeb07779d40801bd068597abba50910f6f8107fcdf8f9e722027c', 'hex')
    END;
    NEW.profile_contract_digest := expected_contract;
    NEW.previous_receipt_digest := COALESCE(predecessor.receipt_digest, decode(repeat('00', 32), 'hex'));
    NEW.actor_session_user := session_user;
    NEW.actor_current_user := current_user;
    NEW.transitioned_at := statement_timestamp();
    NEW.receipt_digest := public.authority_acl_epoch_receipt(
        NEW.epoch, NEW.profile, NEW.profile_version, NEW.profile_contract_digest,
        NEW.source_acl_digest, NEW.result_acl_digest,
        NEW.source_schema_digest, NEW.result_schema_digest, NEW.yoyo_lock_repair,
        NEW.previous_receipt_digest, NEW.actor_session_user, NEW.actor_current_user,
        NEW.transitioned_at
    );
    RETURN NEW;
END;
$$;

CREATE TRIGGER authority_acl_epoch_append_guard
    BEFORE INSERT OR UPDATE OR DELETE ON public.authority_acl_epoch
    FOR EACH ROW EXECUTE FUNCTION public.authority_acl_epoch_append_guard();
REVOKE ALL PRIVILEGES ON FUNCTION public.authority_acl_frame(bytea) FROM PUBLIC;
REVOKE ALL PRIVILEGES ON FUNCTION public.authority_acl_set_digest(bytea[]) FROM PUBLIC;
REVOKE ALL PRIVILEGES ON FUNCTION public.authority_acl_epoch_receipt(
    bigint, public.authority_acl_profile, integer, bytea, bytea, bytea,
    bytea, bytea, public.authority_yoyo_lock_repair, bytea, name, name, timestamptz
) FROM PUBLIC;
REVOKE ALL PRIVILEGES ON FUNCTION public.authority_acl_epoch_append_guard() FROM PUBLIC;

LOCK TABLE project, principal, agent_type, agent_registration, work_queue,
           dead_letter, trace_index, trace_learning_job, outcome_event
    IN ACCESS EXCLUSIVE MODE;

-- Refuse a partial/incompatible upgrade before adding any authority shape.
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM work_queue) THEN
        RAISE EXCEPTION 'authority foundation requires an empty work queue'
            USING ERRCODE = '55000';
    END IF;
    -- The migration owner can be a non-superuser under FORCE RLS. Inspect
    -- every attached/default/orphan child under the already-held parent lock,
    -- instead of assuming the project registry enumerates every partition.
    ALTER TABLE trace_learning_job NO FORCE ROW LEVEL SECURITY;
    ALTER TABLE trace_learning_job DISABLE ROW LEVEL SECURITY;
    IF EXISTS (SELECT 1 FROM trace_learning_job WHERE state = 'running') THEN
        RAISE EXCEPTION 'authority foundation requires no running trace learning lease'
            USING ERRCODE = '55000';
    END IF;
    ALTER TABLE trace_learning_job ENABLE ROW LEVEL SECURITY;
    ALTER TABLE trace_learning_job FORCE ROW LEVEL SECURITY;

    -- A trace row without a live registry project would be skipped by the
    -- run-owner backfill below. Detect it globally before introducing a
    -- migration that makes the omission look durable and legitimate.
    ALTER TABLE trace_index NO FORCE ROW LEVEL SECURITY;
    ALTER TABLE trace_index DISABLE ROW LEVEL SECURITY;
    IF EXISTS (
        SELECT 1
          FROM trace_index AS trace
          LEFT JOIN project
            ON project.project_id = trace.project_id
           AND project.status IN ('active', 'suspended')
           AND project.deleted_at IS NULL
         WHERE project.project_id IS NULL
    ) THEN
        RAISE EXCEPTION 'authority foundation requires trace rows to have live projects'
            USING ERRCODE = '55000';
    END IF;
    ALTER TABLE trace_index ENABLE ROW LEVEL SECURITY;
    ALTER TABLE trace_index FORCE ROW LEVEL SECURITY;

    IF EXISTS (
        SELECT 1
          FROM project
         WHERE status NOT IN ('active', 'suspended', 'deleted')
            OR (status = 'deleted') IS DISTINCT FROM (deleted_at IS NOT NULL)
    ) THEN
        RAISE EXCEPTION 'project lifecycle shape is incompatible with authority foundation'
            USING ERRCODE = '55000';
    END IF;
    IF EXISTS (
        SELECT 1
          FROM agent_registration AS registration
          JOIN agent_type AS agent ON agent.agent_type_id = registration.agent_type_id
         WHERE agent.project_id <> registration.project_id
    ) THEN
        RAISE EXCEPTION 'registration agent type belongs to a different project'
            USING ERRCODE = '55000';
    END IF;
    IF EXISTS (SELECT 1 FROM principal WHERE revoked_at IS NOT NULL AND revoked_at < created_at) THEN
        RAISE EXCEPTION 'principal revocation timestamp precedes creation'
            USING ERRCODE = '55000';
    END IF;
    -- Epoch zero is a fixed 0009→0010 transition, not a schema snapshot.
    -- Pin the registry control relation before later constraints/triggers are
    -- added so an injected column or rewritten type cannot be folded into a
    -- supposedly genuine source profile.
    IF (
        SELECT array_agg(
            attribute.attname || ':' || pg_catalog.format_type(attribute.atttypid, attribute.atttypmod)
            || ':' || attribute.attnotnull::text
            ORDER BY attribute.attnum
        )
          FROM pg_catalog.pg_attribute AS attribute
         WHERE attribute.attrelid = 'public.project'::regclass
           AND attribute.attnum > 0
           AND NOT attribute.attisdropped
    ) IS DISTINCT FROM ARRAY[
        'project_id:uuid:true',
        'name:text:true',
        'status:text:true',
        'retention_policy:jsonb:false',
        'created_at:timestamp with time zone:true',
        'deleted_at:timestamp with time zone:false',
        'provisioning_key_hash:text:false',
        'provisioning_request_hash:text:false'
    ] THEN
        RAISE EXCEPTION 'authority foundation refuses a noncanonical pre-0010 schema baseline'
            USING ERRCODE = '55000';
    END IF;
    IF (
        SELECT array_agg(
            attribute.attname || ':' || pg_catalog.format_type(attribute.atttypid, attribute.atttypmod)
            || ':' || attribute.attnotnull::text
            ORDER BY attribute.attnum
        )
          FROM pg_catalog.pg_attribute AS attribute
         WHERE attribute.attrelid = 'public.principal'::regclass
           AND attribute.attnum > 0
           AND NOT attribute.attisdropped
    ) IS DISTINCT FROM ARRAY[
        'principal_id:uuid:true',
        'kind:text:true',
        'external_ref:text:true',
        'key_hash:text:false',
        'created_at:timestamp with time zone:true',
        'revoked_at:timestamp with time zone:false'
    ] THEN
        RAISE EXCEPTION 'authority foundation refuses a noncanonical pre-0010 schema baseline'
            USING ERRCODE = '55000';
    END IF;
    IF (SELECT count(*) FROM pg_catalog.pg_extension) <> 4
       OR EXISTS (
           SELECT 1
             FROM (VALUES
                ('plpgsql', '1.0', 'pg_catalog'),
                ('vector', '0.8.2', 'public'),
                ('pg_tokenizer', '0.1.1', 'tokenizer_catalog'),
                ('vchord_bm25', '0.3.0', 'bm25_catalog')
             ) AS expected(extname, extversion, nspname)
             LEFT JOIN pg_catalog.pg_extension AS extension ON extension.extname = expected.extname
             LEFT JOIN pg_catalog.pg_namespace AS namespace ON namespace.oid = extension.extnamespace
            WHERE extension.extversion IS DISTINCT FROM expected.extversion
               OR namespace.nspname IS DISTINCT FROM expected.nspname
       ) THEN
        RAISE EXCEPTION 'authority foundation refuses a noncanonical pre-0010 schema baseline'
            USING ERRCODE = '55000';
    END IF;
    IF EXISTS (
        SELECT 1
          FROM pg_catalog.pg_class AS relation
          JOIN pg_catalog.pg_namespace AS namespace ON namespace.oid = relation.relnamespace
         WHERE namespace.nspname = 'public'
           AND relation.relkind IN ('r', 'p', 'S')
           AND relation.relname NOT IN (
               'project', 'principal', 'agent_type', 'agent_registration',
               'project_config', 'agent_type_config', 'killswitch_state', 'embedding_model',
               'scoring_epoch', 'scoring_epoch_epoch_id_seq', 'work_queue', 'work_queue_id_seq',
               'dead_letter', 'principal_grant', 'run_owner', 'authority_acl_epoch',
               'authority_acl_profile_tuple', 'memory_item', 'memory_link', 'derived_state', 'trace_index',
               'trace_subject', 'subject_key', 'outcome_event', 'injection_log',
               'retrieval_event', 'blackboard_entry', 'invalidation_event', 'spend_ledger',
               'review_queue', 'memory_status_log', 'memory_q_update', 'trace_learning_job',
               'yoyo_lock', '_yoyo_migration', '_yoyo_log', '_yoyo_version'
           )
    ) THEN
        RAISE EXCEPTION 'authority foundation refuses a noncanonical pre-0010 schema baseline'
            USING ERRCODE = '55000';
    END IF;
    -- Epoch zero is a canonical foundation receipt, never a snapshot of
    -- whatever an operator happened to grant before the migration.  The
    -- pre-0010 surface may contain only its legacy app identity, the trusted
    -- migration owner, or PUBLIC defaults.  Any other concrete grantee is a
    -- poisoned baseline and aborts the whole transaction before an epoch row
    -- can authenticate it.
    IF EXISTS (
        SELECT 1
          FROM (
              SELECT privilege.grantee
                FROM pg_database AS database
                CROSS JOIN LATERAL aclexplode(COALESCE(database.datacl, acldefault('d', database.datdba))) AS privilege
               WHERE database.datname = current_database()
              UNION ALL
              SELECT privilege.grantee
                FROM pg_namespace AS namespace
                CROSS JOIN LATERAL aclexplode(COALESCE(namespace.nspacl, acldefault('n', namespace.nspowner))) AS privilege
               WHERE namespace.nspname IN ('public', 'tokenizer_catalog', 'bm25_catalog')
              UNION ALL
              SELECT privilege.grantee
                FROM pg_class AS relation
                JOIN pg_namespace AS namespace ON namespace.oid = relation.relnamespace
                CROSS JOIN LATERAL aclexplode(COALESCE(relation.relacl, acldefault('r', relation.relowner))) AS privilege
               WHERE namespace.nspname IN ('public', 'tokenizer_catalog', 'bm25_catalog')
              UNION ALL
              SELECT privilege.grantee
                FROM pg_proc AS routine
                JOIN pg_namespace AS namespace ON namespace.oid = routine.pronamespace
                CROSS JOIN LATERAL aclexplode(COALESCE(routine.proacl, acldefault('f', routine.proowner))) AS privilege
               WHERE namespace.nspname IN ('public', 'tokenizer_catalog', 'bm25_catalog')
              UNION ALL
              SELECT privilege.grantee
                FROM pg_type AS type
                JOIN pg_namespace AS namespace ON namespace.oid = type.typnamespace
                CROSS JOIN LATERAL aclexplode(COALESCE(type.typacl, acldefault('T', type.typowner))) AS privilege
               WHERE namespace.nspname IN ('public', 'tokenizer_catalog', 'bm25_catalog')
              UNION ALL
              SELECT privilege.grantee
                FROM pg_parameter_acl AS parameter_acl
                CROSS JOIN LATERAL aclexplode(parameter_acl.paracl) AS privilege
          ) AS preexisting_acl
          JOIN pg_roles AS grantee ON grantee.oid = preexisting_acl.grantee
         -- PostgreSQL 15+ installs the database-local pseudo-role as the
         -- public schema owner/grantee.  It is not an independently granted
         -- runtime identity, and the canonical source topology legitimately
         -- contains it.  All other concrete grantees are evidence of an
         -- operator mutation and must stop before epoch zero is written.
         WHERE grantee.rolname NOT IN ('tracebed_app', current_user, 'pg_database_owner')
    ) THEN
        RAISE EXCEPTION 'authority foundation refuses a noncanonical pre-0010 ACL baseline'
            USING ERRCODE = '55000';
    END IF;
    -- This source matrix is deliberately equality, not an "unknown role"
    -- filter.  Before 0010, tracebed_app has arwd on every application
    -- relation except the two terminal-frozen parents (arw), and PUBLIC has
    -- no table privileges at all.  A missing expected privilege is just as
    -- incompatible as an added one: later GRANT/REVOKE statements must never
    -- launder either form of baseline drift into epoch zero.
    IF EXISTS (
        SELECT 1
          FROM pg_catalog.pg_class AS relation
          JOIN pg_catalog.pg_namespace AS namespace ON namespace.oid = relation.relnamespace
          CROSS JOIN unnest(ARRAY['SELECT', 'INSERT', 'UPDATE', 'DELETE']) AS expected(privilege_type)
         WHERE namespace.nspname = 'public'
           AND relation.relkind IN ('r', 'p')
           AND relation.relname IN (
               'agent_registration', 'agent_type', 'agent_type_config', 'blackboard_entry',
               'dead_letter', 'derived_state', 'embedding_model', 'injection_log',
               'invalidation_event', 'killswitch_state', 'memory_item', 'memory_link',
               'memory_q_update', 'memory_status_log', 'outcome_event', 'principal',
               'project', 'project_config', 'retrieval_event', 'review_queue', 'scoring_epoch',
               'spend_ledger', 'subject_key', 'trace_index', 'trace_learning_job',
               'trace_subject', 'work_queue', 'yoyo_lock'
           )
           AND pg_catalog.has_table_privilege('tracebed_app', relation.oid, expected.privilege_type)
               IS DISTINCT FROM (
                   expected.privilege_type <> 'DELETE'
                   OR relation.relname NOT IN ('trace_index', 'trace_learning_job')
               )
    ) OR EXISTS (
        SELECT 1
          FROM pg_catalog.pg_class AS relation
          JOIN pg_catalog.pg_namespace AS namespace ON namespace.oid = relation.relnamespace
          CROSS JOIN LATERAL pg_catalog.aclexplode(
              COALESCE(
                  relation.relacl,
                  pg_catalog.acldefault(
                      CASE WHEN relation.relkind = 'S' THEN 's'::"char" ELSE 'r'::"char" END,
                      relation.relowner
                  )
              )
          ) AS privilege
         WHERE namespace.nspname = 'public'
           AND relation.relkind IN ('r', 'p', 'S', 'v', 'm', 'f')
           AND privilege.grantee = 0
    ) THEN
        RAISE EXCEPTION 'authority foundation refuses a noncanonical pre-0010 ACL baseline'
            USING ERRCODE = '55000';
    END IF;
    -- Parameter ACLs have no legacy Tracebed allowance at all.  Keeping them
    -- out of the initial source profile prevents an owner-granted SET/ALTER
    -- capability from being hidden behind the legacy application's name.
    IF EXISTS (SELECT 1 FROM pg_catalog.pg_parameter_acl) THEN
        RAISE EXCEPTION 'authority foundation refuses a noncanonical pre-0010 ACL baseline'
            USING ERRCODE = '55000';
    END IF;
    IF EXISTS (
        WITH deleted_projects AS (
            SELECT project_id FROM project WHERE deleted_at IS NOT NULL
        ), expected_children AS (
            SELECT parent_name || '_p_' || replace(project_id::text, '-', '') AS relname
              FROM deleted_projects
              CROSS JOIN unnest(ARRAY[
                  'memory_item', 'memory_link', 'derived_state', 'trace_index',
                  'trace_subject', 'subject_key', 'outcome_event', 'injection_log',
                  'retrieval_event', 'blackboard_entry', 'invalidation_event',
                  'spend_ledger', 'review_queue', 'memory_status_log',
                  'memory_q_update', 'trace_learning_job'
              ]) AS parent_name
        )
        SELECT 1
          FROM expected_children
          JOIN pg_class AS relation ON relation.relname = expected_children.relname
          JOIN pg_namespace AS namespace ON namespace.oid = relation.relnamespace
         WHERE namespace.nspname = 'public' AND relation.relkind IN ('r', 'p')
    ) THEN
        RAISE EXCEPTION 'deleted project retains a learning partition'
            USING ERRCODE = '55000';
    END IF;
END
$$;

ALTER TABLE project DROP CONSTRAINT project_status_check;
ALTER TABLE project
    ADD CONSTRAINT project_status_check
    CHECK (status IN ('active', 'suspended', 'deleting', 'deleted'));
ALTER TABLE project
    ADD CONSTRAINT project_deleted_at_shape_ck
    CHECK (
        (status IN ('active', 'suspended', 'deleting') AND deleted_at IS NULL)
        OR (status = 'deleted' AND deleted_at IS NOT NULL)
    );

CREATE FUNCTION project_enforce_lifecycle() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'projects cannot be physically deleted' USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'INSERT' THEN
        IF NEW.status <> 'active' OR NEW.deleted_at IS NOT NULL THEN
            RAISE EXCEPTION 'new projects must be active and not deleted' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.project_id IS DISTINCT FROM OLD.project_id
       OR NEW.created_at IS DISTINCT FROM OLD.created_at
       OR NEW.provisioning_key_hash IS DISTINCT FROM OLD.provisioning_key_hash
       OR NEW.provisioning_request_hash IS DISTINCT FROM OLD.provisioning_request_hash THEN
        RAISE EXCEPTION 'project identity and provisioning hashes are immutable' USING ERRCODE = '23514';
    END IF;
    IF OLD.status = 'deleted' THEN
        IF NEW IS DISTINCT FROM OLD THEN
            RAISE EXCEPTION 'deleted projects are immutable' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;
    IF (NEW.name IS DISTINCT FROM OLD.name OR NEW.retention_policy IS DISTINCT FROM OLD.retention_policy)
       AND NOT (OLD.status IN ('active', 'suspended') AND NEW.status IN ('active', 'suspended')) THEN
        RAISE EXCEPTION 'project metadata may only change while active or suspended'
            USING ERRCODE = '23514';
    END IF;
    IF NEW.status = OLD.status THEN
        IF NEW.deleted_at IS DISTINCT FROM OLD.deleted_at THEN
            RAISE EXCEPTION 'project deletion timestamp is lifecycle managed' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;
    IF OLD.status IN ('active', 'suspended') AND NEW.status IN ('active', 'suspended') THEN
        IF NEW.deleted_at IS DISTINCT FROM OLD.deleted_at THEN
            RAISE EXCEPTION 'project deletion timestamp is lifecycle managed' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;
    IF OLD.status IN ('active', 'suspended') AND NEW.status = 'deleting' THEN
        IF NEW.deleted_at IS NOT NULL THEN
            RAISE EXCEPTION 'deleting projects cannot set deleted_at' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;
    IF OLD.status = 'deleting' AND NEW.status = 'deleted' THEN
        NEW.deleted_at := statement_timestamp();
        RETURN NEW;
    END IF;
    RAISE EXCEPTION 'illegal project lifecycle transition' USING ERRCODE = '23514';
END;
$$;

CREATE TRIGGER project_lifecycle_guard
    BEFORE INSERT OR UPDATE OR DELETE ON project
    FOR EACH ROW EXECUTE FUNCTION project_enforce_lifecycle();

ALTER TABLE principal
    ADD CONSTRAINT principal_revocation_time_ck
    CHECK (revoked_at IS NULL OR revoked_at >= created_at);

CREATE FUNCTION principal_enforce_immutability() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'principals cannot be deleted' USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'INSERT' THEN
        IF NEW.revoked_at IS NOT NULL THEN
            RAISE EXCEPTION 'new principals cannot be pre-revoked' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.principal_id IS DISTINCT FROM OLD.principal_id
       OR NEW.kind IS DISTINCT FROM OLD.kind
       OR NEW.external_ref IS DISTINCT FROM OLD.external_ref
       OR NEW.key_hash IS DISTINCT FROM OLD.key_hash
       OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
        RAISE EXCEPTION 'principal identity is immutable' USING ERRCODE = '23514';
    END IF;
    IF NEW.revoked_at IS NOT DISTINCT FROM OLD.revoked_at THEN
        RETURN NEW;
    END IF;
    IF OLD.revoked_at IS NOT NULL OR NEW.revoked_at IS NULL THEN
        RAISE EXCEPTION 'principal revocation is one-way' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER principal_immutability_guard
    BEFORE INSERT OR UPDATE OR DELETE ON principal
    FOR EACH ROW EXECUTE FUNCTION principal_enforce_immutability();

ALTER TABLE agent_type
    ADD CONSTRAINT agent_type_project_identity_uq UNIQUE (project_id, agent_type_id);

CREATE FUNCTION agent_type_enforce_immutability() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'agent types cannot be deleted' USING ERRCODE = '23514';
    END IF;
    IF NEW.agent_type_id IS DISTINCT FROM OLD.agent_type_id
       OR NEW.project_id IS DISTINCT FROM OLD.project_id
       OR NEW.name IS DISTINCT FROM OLD.name
       OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
        RAISE EXCEPTION 'agent type identity is immutable' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER agent_type_immutability_guard
    BEFORE UPDATE OR DELETE ON agent_type
    FOR EACH ROW EXECUTE FUNCTION agent_type_enforce_immutability();

ALTER TABLE agent_registration
    ADD COLUMN revoked_at timestamptz,
    ADD CONSTRAINT agent_registration_principal_project_uq UNIQUE (principal_id, project_id),
    ADD CONSTRAINT agent_registration_agent_type_project_fk
        FOREIGN KEY (project_id, agent_type_id)
        REFERENCES agent_type (project_id, agent_type_id),
    ADD CONSTRAINT agent_registration_revocation_time_ck
        CHECK (revoked_at IS NULL OR revoked_at >= registered_at);

CREATE FUNCTION agent_registration_enforce_immutability() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'agent registrations cannot be deleted' USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'INSERT' THEN
        IF NEW.revoked_at IS NOT NULL THEN
            RAISE EXCEPTION 'new registrations cannot be pre-revoked' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.principal_id IS DISTINCT FROM OLD.principal_id
       OR NEW.project_id IS DISTINCT FROM OLD.project_id
       OR NEW.agent_type_id IS DISTINCT FROM OLD.agent_type_id
       OR NEW.registered_at IS DISTINCT FROM OLD.registered_at THEN
        RAISE EXCEPTION 'agent registration identity is immutable' USING ERRCODE = '23514';
    END IF;
    IF NEW.revoked_at IS NOT DISTINCT FROM OLD.revoked_at THEN
        RETURN NEW;
    END IF;
    IF OLD.revoked_at IS NOT NULL OR NEW.revoked_at IS NULL THEN
        RAISE EXCEPTION 'agent registration revocation is one-way' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER agent_registration_immutability_guard
    BEFORE INSERT OR UPDATE OR DELETE ON agent_registration
    FOR EACH ROW EXECUTE FUNCTION agent_registration_enforce_immutability();

CREATE TABLE principal_grant (
    grant_id        uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    principal_id    uuid NOT NULL,
    project_id      uuid NOT NULL,
    role            text NOT NULL,
    feedback_source text CHECK (feedback_source IN ('verdict', 'correction_adapter', 'downstream')),
    granted_by      uuid,
    granted_at      timestamptz NOT NULL DEFAULT statement_timestamp(),
    revoked_at      timestamptz,
    CONSTRAINT principal_grant_role_ck CHECK (role IN ('admin', 'data', 'export', 'feedback')),
    CONSTRAINT principal_grant_feedback_shape_ck CHECK (
        (role = 'feedback' AND feedback_source IS NOT NULL)
        OR (role <> 'feedback' AND feedback_source IS NULL)
    ),
    CONSTRAINT principal_grant_registration_fk
        FOREIGN KEY (principal_id, project_id)
        REFERENCES agent_registration (principal_id, project_id),
    CONSTRAINT principal_grant_grantor_registration_fk
        FOREIGN KEY (granted_by, project_id)
        REFERENCES agent_registration (principal_id, project_id),
    CONSTRAINT principal_grant_revocation_time_ck
        CHECK (revoked_at IS NULL OR revoked_at >= granted_at)
);

CREATE UNIQUE INDEX principal_grant_one_active_role_uq
    ON principal_grant (project_id, principal_id, role)
    WHERE revoked_at IS NULL;

CREATE FUNCTION principal_grant_enforce_immutability() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'principal grants cannot be deleted' USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'INSERT' THEN
        IF NEW.revoked_at IS NOT NULL THEN
            RAISE EXCEPTION 'new principal grants cannot be pre-revoked' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.grant_id IS DISTINCT FROM OLD.grant_id
       OR NEW.principal_id IS DISTINCT FROM OLD.principal_id
       OR NEW.project_id IS DISTINCT FROM OLD.project_id
       OR NEW.role IS DISTINCT FROM OLD.role
       OR NEW.feedback_source IS DISTINCT FROM OLD.feedback_source
       OR NEW.granted_by IS DISTINCT FROM OLD.granted_by
       OR NEW.granted_at IS DISTINCT FROM OLD.granted_at THEN
        RAISE EXCEPTION 'principal grant identity is immutable' USING ERRCODE = '23514';
    END IF;
    IF NEW.revoked_at IS NOT DISTINCT FROM OLD.revoked_at THEN
        RETURN NEW;
    END IF;
    IF OLD.revoked_at IS NOT NULL OR NEW.revoked_at IS NULL THEN
        RAISE EXCEPTION 'principal grant revocation is one-way' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER principal_grant_immutability_guard
    BEFORE INSERT OR UPDATE OR DELETE ON principal_grant
    FOR EACH ROW EXECUTE FUNCTION principal_grant_enforce_immutability();

-- Existing registrations retain the narrow DATA capability only.  No future
-- registration trigger exists: the later authority workflow must grant roles
-- explicitly.
SELECT registration.principal_id, registration.project_id, 'data', NULL
  FROM agent_registration AS registration
  JOIN project ON project.project_id = registration.project_id
  JOIN principal ON principal.principal_id = registration.principal_id
 WHERE project.status IN ('active', 'suspended')
   AND project.deleted_at IS NULL
   AND registration.revoked_at IS NULL
   AND principal.revoked_at IS NULL;

