    USING (project_id = NULLIF(current_setting('tracebed.project_id', true), '')::uuid);

CREATE FUNCTION run_owner_enforce_immutability() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'run owners cannot be deleted' USING ERRCODE = '23514';
    END IF;
    RAISE EXCEPTION 'run owners are immutable' USING ERRCODE = '23514';
END;
$$;

CREATE TRIGGER run_owner_immutability_guard
    BEFORE UPDATE OR DELETE ON run_owner
    FOR EACH ROW EXECUTE FUNCTION run_owner_enforce_immutability();

-- Add the versioned authority envelope without changing legacy v0 behaviour.
CREATE FUNCTION subject_digests_are_valid(digests bytea[]) RETURNS boolean
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    ordered bytea[];
    count_values integer;
    distinct_values integer;
BEGIN
    IF digests IS NULL THEN
        RETURN false;
    END IF;
    IF cardinality(digests) = 0 THEN
        RETURN true;
    END IF;
    IF array_ndims(digests) IS DISTINCT FROM 1 OR cardinality(digests) > 64
       OR array_position(digests, NULL::bytea) IS NOT NULL THEN
        RETURN false;
    END IF;
    IF EXISTS (SELECT 1 FROM unnest(digests) AS digest WHERE octet_length(digest) <> 32) THEN
        RETURN false;
    END IF;
    SELECT array_agg(digest ORDER BY digest), count(*), count(DISTINCT digest)
      INTO ordered, count_values, distinct_values
      FROM unnest(digests) AS digest;
    RETURN ordered = digests AND count_values = distinct_values;
END;
$$;

ALTER TABLE work_queue
    ADD COLUMN authority_version smallint NOT NULL DEFAULT 0,
    ADD COLUMN run_id uuid,
    ADD COLUMN source_principal_id uuid,
    ADD COLUMN source_agent_type_id uuid,
    ADD COLUMN source_grant_id uuid,
    ADD COLUMN required_role text,
    ADD COLUMN feedback_source text,
    ADD COLUMN run_owner_principal_id uuid,
    ADD COLUMN run_owner_agent_type_id uuid,
    ADD COLUMN subject_digests bytea[] NOT NULL DEFAULT '{}'::bytea[];

ALTER TABLE work_queue
    ADD CONSTRAINT work_queue_authority_version_ck CHECK (authority_version IN (0, 1)),
    ADD CONSTRAINT work_queue_subject_digests_ck CHECK (subject_digests_are_valid(subject_digests)),
    ADD CONSTRAINT work_queue_authority_v0_v1_ck CHECK (
        (authority_version = 0
         AND run_id IS NULL AND source_principal_id IS NULL AND source_agent_type_id IS NULL
         AND source_grant_id IS NULL AND required_role IS NULL AND feedback_source IS NULL
         AND run_owner_principal_id IS NULL AND run_owner_agent_type_id IS NULL)
        OR
        (authority_version = 1
         AND run_id IS NOT NULL AND source_principal_id IS NOT NULL
         AND source_agent_type_id IS NOT NULL AND source_grant_id IS NOT NULL
         AND required_role IS NOT NULL AND run_owner_principal_id IS NOT NULL
         AND run_owner_agent_type_id IS NOT NULL
         AND (
             (topic IN ('trace_event', 'memory_proposal')
              AND required_role = 'data' AND feedback_source IS NULL
              AND source_principal_id = run_owner_principal_id
              AND source_agent_type_id = run_owner_agent_type_id)
             OR
             (topic = 'outcome_event' AND required_role = 'feedback'
              AND feedback_source IS NOT NULL
              AND feedback_source IN ('verdict', 'correction_adapter', 'downstream'))
         ))
    );

ALTER TABLE dead_letter
    ADD COLUMN authority_version smallint NOT NULL DEFAULT 0,
    ADD COLUMN run_id uuid,
