    ADD COLUMN run_owner_principal_id uuid,
    ADD COLUMN run_owner_agent_type_id uuid,
    ADD COLUMN subject_digests bytea[] NOT NULL DEFAULT '{}'::bytea[];

ALTER TABLE dead_letter
    ADD CONSTRAINT dead_letter_authority_version_ck CHECK (authority_version IN (0, 1)),
    ADD CONSTRAINT dead_letter_subject_digests_ck CHECK (subject_digests_are_valid(subject_digests)),
    ADD CONSTRAINT dead_letter_authority_v0_v1_ck CHECK (
        (authority_version = 0
         AND run_id IS NULL AND source_principal_id IS NULL AND source_agent_type_id IS NULL
         AND source_grant_id IS NULL AND required_role IS NULL AND feedback_source IS NULL
         AND run_owner_principal_id IS NULL AND run_owner_agent_type_id IS NULL)
        OR
        (authority_version = 1
         AND run_id IS NOT NULL AND source_principal_id IS NOT NULL
         AND source_agent_type_id IS NOT NULL AND source_grant_id IS NOT NULL
         AND required_role IS NOT NULL AND run_owner_principal_id IS NOT NULL
         AND run_owner_agent_type_id IS NOT NULL
         AND (
             (topic IN ('trace_event', 'memory_proposal')
              AND required_role = 'data' AND feedback_source IS NULL
              AND source_principal_id = run_owner_principal_id
              AND source_agent_type_id = run_owner_agent_type_id)
             OR
             (topic = 'outcome_event' AND required_role = 'feedback'
              AND feedback_source IS NOT NULL
              AND feedback_source IN ('verdict', 'correction_adapter', 'downstream'))
         ))
    );

CREATE INDEX work_queue_project_id_idx ON work_queue (project_id, id);
CREATE INDEX work_queue_project_run_id_idx ON work_queue (project_id, run_id, id)
    WHERE run_id IS NOT NULL;
CREATE INDEX work_queue_subject_digests_gin_idx ON work_queue USING gin (subject_digests);
