ALTER TABLE outcome_event
    ADD CONSTRAINT outcome_event_authority_version_ck CHECK (authority_version IN (0, 1)),
    ADD CONSTRAINT outcome_event_authority_v0_v1_ck CHECK (
        (authority_version = 0
         AND source_agent_type_id IS NULL AND source_grant_id IS NULL
         AND feedback_source IS NULL AND run_owner_principal_id IS NULL
         AND run_owner_agent_type_id IS NULL)
        OR
        (authority_version = 1
         AND source_agent_type_id IS NOT NULL AND source_grant_id IS NOT NULL
         AND feedback_source IS NOT NULL
         AND feedback_source IN ('verdict', 'correction_adapter', 'downstream')
         AND run_owner_principal_id IS NOT NULL AND run_owner_agent_type_id IS NOT NULL
         AND adapter = feedback_source)
    );

-- New groups start with no accidental old-learning privileges.  Regrant only
-- the authority foundation matrix; tracebed_app's historical object grants
-- remain untouched.
REVOKE ALL PRIVILEGES ON ALL TABLES IN SCHEMA public
    FROM tracebed_api_group, tracebed_worker_group, tracebed_erasure_group;
REVOKE ALL PRIVILEGES ON ALL SEQUENCES IN SCHEMA public
    FROM tracebed_api_group, tracebed_worker_group, tracebed_erasure_group;

DO $$
BEGIN
    EXECUTE format(
        'GRANT CONNECT ON DATABASE %I TO tracebed_api_group, tracebed_worker_group, tracebed_erasure_group',
        current_database()
    );
    GRANT USAGE ON SCHEMA public TO tracebed_api_group, tracebed_worker_group, tracebed_erasure_group;
END
$$;

REVOKE ALL PRIVILEGES ON principal_grant
    FROM PUBLIC, tracebed_app, tracebed_api_group, tracebed_worker_group, tracebed_erasure_group;
GRANT SELECT ON principal_grant TO tracebed_app, tracebed_api_group, tracebed_worker_group;

REVOKE ALL PRIVILEGES ON run_owner
    FROM PUBLIC, tracebed_app, tracebed_api_group, tracebed_worker_group, tracebed_erasure_group;
GRANT SELECT, INSERT ON run_owner TO tracebed_app, tracebed_api_group;
GRANT SELECT ON run_owner TO tracebed_worker_group;

GRANT SELECT ON project, principal, agent_type, agent_registration, principal_grant
    TO tracebed_api_group, tracebed_worker_group;
GRANT SELECT, INSERT ON work_queue TO tracebed_api_group;
GRANT USAGE, SELECT ON SEQUENCE work_queue_id_seq TO tracebed_api_group;
GRANT SELECT, UPDATE, DELETE ON work_queue TO tracebed_worker_group;
GRANT SELECT, INSERT ON dead_letter TO tracebed_worker_group;
REVOKE EXECUTE ON FUNCTION subject_digests_are_valid(bytea[]) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION subject_digests_are_valid(bytea[])
    TO tracebed_app, tracebed_api_group, tracebed_worker_group;

-- Existing active/suspended projects receive their run-owner child before
-- backfill.  The transaction-local RLS scope is deliberately set for every
-- INSERT, even when the migration runner is privileged, so this path remains
-- valid under FORCE RLS in hardened owner deployments.
DO $$
DECLARE
    project_row record;
    child_name text;
    policy_name text;
    index_name text;
BEGIN
    FOR project_row IN
        SELECT project_id
          FROM project
         WHERE status IN ('active', 'suspended') AND deleted_at IS NULL
         ORDER BY project_id
    LOOP
        child_name := 'run_owner_p_' || replace(project_row.project_id::text, '-', '');
        policy_name := child_name || '_isolation';
        index_name := child_name || '_owner';
        EXECUTE format(
            'CREATE TABLE IF NOT EXISTS %I PARTITION OF run_owner FOR VALUES IN (%L)',
            child_name, project_row.project_id
        );
        IF NOT EXISTS (
            SELECT 1
              FROM pg_class AS child
              JOIN pg_inherits AS inheritance ON inheritance.inhrelid = child.oid
             WHERE child.oid = to_regclass(child_name)
               AND child.relkind = 'r'
               AND inheritance.inhparent = 'run_owner'::regclass
               AND pg_get_expr(child.relpartbound, child.oid)
                   = format('FOR VALUES IN (%L)', project_row.project_id)
        ) THEN
            RAISE EXCEPTION 'run-owner partition name is occupied by an unexpected relation'
                USING ERRCODE = '55000';
        END IF;
        EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', child_name);
        EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', child_name);
        EXECUTE format('DROP POLICY IF EXISTS %I ON %I', policy_name, child_name);
        EXECUTE format(
            'CREATE POLICY %I ON %I USING '
            || '(project_id = NULLIF(current_setting(''tracebed.project_id'', true), '''')::uuid)',
            policy_name, child_name
        );
        EXECUTE format('REVOKE ALL PRIVILEGES ON %I FROM PUBLIC', child_name);
        EXECUTE format(
            'REVOKE ALL PRIVILEGES ON %I FROM tracebed_app, tracebed_api_group, '
            || 'tracebed_worker_group, tracebed_erasure_group',
            child_name
        );
        EXECUTE format('GRANT SELECT, INSERT ON %I TO tracebed_app, tracebed_api_group', child_name);
        EXECUTE format('GRANT SELECT ON %I TO tracebed_worker_group', child_name);
        EXECUTE format(
            'CREATE INDEX IF NOT EXISTS %I ON %I (principal_id, agent_type_id, run_id)',
            index_name, child_name
        );
        PERFORM set_config('tracebed.project_id', project_row.project_id::text, true);
        SELECT project_id, run_id, submitter_principal, agent_type_id, 'trace', statement_timestamp()
          FROM trace_index
         WHERE project_id = project_row.project_id
        ON CONFLICT (project_id, run_id) DO NOTHING;
        PERFORM set_config('tracebed.project_id', '', true);
    END LOOP;
END
$$;

-- Append epoch zero only after the entire 0010 authority shape has been
-- installed.  These owner-only assertions intentionally use semantic
-- catalog identities, never OIDs, so a dump/restore retains the receipt.
CREATE FUNCTION public.authority_acl_profile_actual_tuples(
    profile public.authority_acl_profile
) RETURNS SETOF bytea
LANGUAGE sql STABLE STRICT SECURITY INVOKER
SET search_path = pg_catalog, pg_temp
AS $$
WITH protected AS (
    -- This deliberately enumerates every live role.  A grant to an
    -- unrelated login/group is authority drift; filtering to a fixed role
    -- list would make that capability invisible to the authenticated ACL
    -- profile.
    SELECT oid, rolname FROM pg_catalog.pg_roles
), profiled_namespace AS (
    -- The authority receipt is fail-closed for every non-system namespace.
    -- Only PostgreSQL's documented catalog, information-schema, toast, and
    -- backend-temporary namespaces are excluded.  A user-created schema
    -- (including a pg_-prefixed homonym that is not a real numeric toast/temp
    -- namespace) is therefore receipt-visible even before it carries an ACL.
    SELECT namespace.*
      FROM pg_catalog.pg_namespace AS namespace
     WHERE namespace.nspname NOT IN ('pg_catalog', 'information_schema', 'pg_toast')
       AND namespace.nspname !~ '^pg_temp_[0-9]+$'
       AND namespace.nspname !~ '^pg_toast_[0-9]+$'
       AND namespace.nspname !~ '^pg_toast_temp_[0-9]+$'
), partition_family(parent_name) AS (
    VALUES
        ('memory_item'), ('memory_link'), ('derived_state'), ('trace_index'),
        ('trace_subject'), ('subject_key'), ('outcome_event'), ('injection_log'),
        ('retrieval_event'), ('blackboard_entry'), ('invalidation_event'), ('spend_ledger'),
        ('review_queue'), ('memory_status_log'), ('memory_q_update'),
        ('trace_learning_job'), ('run_owner')
    UNION ALL
    SELECT parent_name
      FROM (VALUES ('subject_fence'), ('run_fence'), ('erase_run_set'), ('erase_mem_set'),
                   ('run_memory_binding'))
           AS erasure_parent(parent_name)
     WHERE profile = 'cutover_0012'::public.authority_acl_profile
), canonical_project_partition AS (
    -- Only direct, public LIST leaves for a live project are normalized away.
    -- c12 alone additionally retains one fully scrubbed subject-key leaf for
    -- an authenticated project tombstone.  A generic INHERITS edge, a moved
    -- leaf, a non-LIST bound, a second parent, a different deleted family, or
    -- a partially scrubbed key is authority-visible rather than being
    -- mistaken for a dynamic project partition.
    SELECT child.oid AS child_oid,
           parent.oid AS parent_oid,
           parent_namespace.nspname AS parent_schema,
           parent.relname AS parent_name,
           pg_catalog.pg_get_expr(child.relpartbound, child.oid) AS partition_bound
      FROM pg_catalog.pg_inherits AS inheritance
      JOIN pg_catalog.pg_class AS child ON child.oid = inheritance.inhrelid
      JOIN pg_catalog.pg_namespace AS child_namespace ON child_namespace.oid = child.relnamespace
      JOIN pg_catalog.pg_class AS parent ON parent.oid = inheritance.inhparent
      JOIN pg_catalog.pg_namespace AS parent_namespace ON parent_namespace.oid = parent.relnamespace
      JOIN partition_family AS family ON family.parent_name = parent.relname
      JOIN public.project AS bound_project
        ON pg_catalog.pg_get_expr(child.relpartbound, child.oid)
            = pg_catalog.format('FOR VALUES IN (%L)', bound_project.project_id)
     WHERE child_namespace.nspname = 'public'
       AND parent_namespace.nspname = 'public'
       AND child.relkind = 'r'
       AND parent.relkind = 'p'
       AND (
           (
               bound_project.status IN ('active', 'suspended')
               AND bound_project.deleted_at IS NULL
           )
           OR (
               profile = 'cutover_0012'::public.authority_acl_profile
               AND parent_namespace.nspname = 'public'
               AND parent.relname = 'subject_key'
               AND bound_project.status = 'deleted'
               AND bound_project.deleted_at IS NOT NULL
               AND pg_catalog.isfinite(bound_project.deleted_at)
               AND bound_project.name = 'deleted-project'
               AND bound_project.retention_policy IS NULL
               AND bound_project.provisioning_key_hash IS NULL
               AND bound_project.provisioning_request_hash IS NULL
               AND NOT EXISTS (
                   SELECT 1
                     FROM public.subject_key AS key_row
                     CROSS JOIN LATERAL (
                         SELECT pg_catalog.to_jsonb(key_row) AS value
                     ) AS key_json
                    WHERE key_row.tableoid = child.oid
                      AND key_row.project_id = bound_project.project_id
                      AND (
                          NOT (key_json.value ? 'destroyed_at')
                          OR key_json.value ->> 'destroyed_at' IS NULL
                          OR NOT pg_catalog.isfinite(
                              (key_json.value ->> 'destroyed_at')::timestamp with time zone
                          )
                          OR NOT (key_json.value ? 'created_at')
                          OR key_json.value ->> 'created_at' IS NULL
                          OR NOT pg_catalog.isfinite(
                              (key_json.value ->> 'created_at')::timestamp with time zone
                          )
                          OR (key_json.value ->> 'destroyed_at')::timestamp with time zone
                              < (key_json.value ->> 'created_at')::timestamp with time zone
                          OR NOT (key_json.value ? 'wrapped_kek')
                          OR key_json.value ->> 'wrapped_kek' IS NULL
                          OR (key_json.value ->> 'wrapped_kek')::bytea <> ''::bytea
                          OR key_json.value ->> 'subject_tag' IS NOT NULL
                          OR NOT (key_json.value ? 'subject_digest')
                          OR key_json.value ->> 'subject_digest' IS NULL
                          OR octet_length((key_json.value ->> 'subject_digest')::bytea) <> 32
                          OR NOT (key_json.value ? 'wrap_version')
                          OR key_json.value ->> 'wrap_version' IS NULL
                          OR (key_json.value ->> 'wrap_version')::smallint NOT IN (1, 2)
                      )
               )
           )
       )
       AND child.relname = parent.relname || '_p_' || replace(bound_project.project_id::text, '-', '')
       AND NOT EXISTS (
           SELECT 1
             FROM pg_catalog.pg_inherits AS other
            WHERE other.inhrelid = child.oid
              AND other.inhparent <> parent.oid
       )
), raw_entry AS (
    SELECT 'profile:' || profile::text AS identity
    UNION ALL
    -- E1 deliberately lays only the NOLOGIN erasure foundation.  A published
    -- erasure login is a later deployment epoch, so c12 treats its absence
    -- as an authenticated catalog fact rather than a convention.
    SELECT 'erasure-login-absent:'
           || (NOT EXISTS (
               SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'tracebed_erasure'
           ))::text
     WHERE profile = 'cutover_0012'::public.authority_acl_profile
    UNION ALL
    SELECT 'database:' || database.datname || ':' || COALESCE(grantee.rolname, 'PUBLIC')
           || ':' || privilege.privilege_type || ':' || grantor.rolname || ':' || privilege.is_grantable::text
      FROM pg_catalog.pg_database AS database
      CROSS JOIN LATERAL pg_catalog.aclexplode(COALESCE(database.datacl, pg_catalog.acldefault('d', database.datdba))) AS privilege
      LEFT JOIN protected AS grantee ON grantee.oid = privilege.grantee
      JOIN pg_catalog.pg_roles AS grantor ON grantor.oid = privilege.grantor
     -- The authority receipt covers every database allowed by the dedicated
     -- cluster contract.  Otherwise a PUBLIC CONNECT grant on postgres or a
     -- template database is invisible to the post-cutover profile.
     WHERE database.datname IN (
         pg_catalog.current_database(), 'postgres', 'template0', 'template1'
     )
       AND (privilege.grantee = 0 OR grantee.oid IS NOT NULL)
    UNION ALL
    SELECT 'schema:' || namespace.nspname || ':' || COALESCE(grantee.rolname, 'PUBLIC')
           || ':' || privilege.privilege_type || ':' || grantor.rolname || ':' || privilege.is_grantable::text
      FROM profiled_namespace AS namespace
      CROSS JOIN LATERAL pg_catalog.aclexplode(COALESCE(namespace.nspacl, pg_catalog.acldefault('n', namespace.nspowner))) AS privilege
      LEFT JOIN protected AS grantee ON grantee.oid = privilege.grantee
      JOIN pg_catalog.pg_roles AS grantor ON grantor.oid = privilege.grantor
     WHERE privilege.grantee = 0 OR grantee.oid IS NOT NULL
    UNION ALL
    -- Ordinary parent/control relations are recorded directly.  Project
    -- leaves are checked by ``partition_acl_mismatch`` below: that compares
    -- every attached leaf to its profile-specific expected ACL and records a
    -- parent+LIST-bound sentinel only when it deviates.  A valid newly
    -- provisioned project therefore does not invalidate an append-only epoch.
    SELECT 'relation:' || namespace.nspname || '.' || relation.relname || ':'
           || COALESCE(grantee.rolname, 'PUBLIC') || ':' || privilege.privilege_type
           || ':' || grantor.rolname || ':' || privilege.is_grantable::text
      FROM pg_catalog.pg_class AS relation
      JOIN profiled_namespace AS namespace ON namespace.oid = relation.relnamespace
      LEFT JOIN canonical_project_partition AS canonical ON canonical.child_oid = relation.oid
      CROSS JOIN LATERAL pg_catalog.aclexplode(
          COALESCE(
              relation.relacl,
              pg_catalog.acldefault(
                  CASE WHEN relation.relkind = 'S' THEN 's'::"char" ELSE 'r'::"char" END,
                  relation.relowner
              )
          )
      ) AS privilege
      LEFT JOIN protected AS grantee ON grantee.oid = privilege.grantee
      JOIN pg_catalog.pg_roles AS grantor ON grantor.oid = privilege.grantor
     WHERE canonical.child_oid IS NULL
       -- Views, materialized views, foreign tables, and sequences all carry
       -- independently mutable ACLs.  Do not make a grant invisible merely
       -- because it is not a heap/partition relation.
       AND relation.relkind IN ('r', 'p', 'S', 'v', 'm', 'f')
       AND (privilege.grantee = 0 OR grantee.oid IS NOT NULL)
    UNION ALL
    SELECT 'column:' || namespace.nspname || '.' || relation.relname || '.' || attribute.attname || ':'
           || COALESCE(grantee.rolname, 'PUBLIC') || ':' || privilege.privilege_type
           || ':' || grantor.rolname || ':' || privilege.is_grantable::text
      FROM pg_catalog.pg_attribute AS attribute
      JOIN pg_catalog.pg_class AS relation ON relation.oid = attribute.attrelid
      JOIN profiled_namespace AS namespace ON namespace.oid = relation.relnamespace
      LEFT JOIN canonical_project_partition AS canonical ON canonical.child_oid = relation.oid
      CROSS JOIN LATERAL pg_catalog.aclexplode(attribute.attacl) AS privilege
      LEFT JOIN protected AS grantee ON grantee.oid = privilege.grantee
      JOIN pg_catalog.pg_roles AS grantor ON grantor.oid = privilege.grantor
     WHERE attribute.attnum > 0
       AND NOT attribute.attisdropped
       AND canonical.child_oid IS NULL
       AND (privilege.grantee = 0 OR grantee.oid IS NOT NULL)
    UNION ALL
    SELECT 'default-acl:' || COALESCE(namespace.nspname, '<all-schemas>') || ':'
           || default_acl.defaclobjtype::text || ':' || owner.rolname || ':'
           || COALESCE(grantee.rolname, 'PUBLIC') || ':' || privilege.privilege_type
           || ':' || grantor.rolname || ':' || privilege.is_grantable::text
      FROM pg_catalog.pg_default_acl AS default_acl
      JOIN pg_catalog.pg_roles AS owner ON owner.oid = default_acl.defaclrole
      LEFT JOIN pg_catalog.pg_namespace AS namespace ON namespace.oid = default_acl.defaclnamespace
      CROSS JOIN LATERAL pg_catalog.aclexplode(default_acl.defaclacl) AS privilege
      LEFT JOIN protected AS grantee ON grantee.oid = privilege.grantee
      JOIN pg_catalog.pg_roles AS grantor ON grantor.oid = privilege.grantor
     WHERE privilege.grantee = 0 OR grantee.oid IS NOT NULL
    UNION ALL
    SELECT 'tablespace:' || tablespace.spcname || ':' || COALESCE(grantee.rolname, 'PUBLIC')
           || ':' || privilege.privilege_type || ':' || grantor.rolname || ':' || privilege.is_grantable::text
      FROM pg_catalog.pg_tablespace AS tablespace
      CROSS JOIN LATERAL pg_catalog.aclexplode(COALESCE(tablespace.spcacl, pg_catalog.acldefault('t', tablespace.spcowner))) AS privilege
      LEFT JOIN protected AS grantee ON grantee.oid = privilege.grantee
      JOIN pg_catalog.pg_roles AS grantor ON grantor.oid = privilege.grantor
     WHERE privilege.grantee = 0 OR grantee.oid IS NOT NULL
    UNION ALL
    SELECT 'language:' || language.lanname || ':' || COALESCE(grantee.rolname, 'PUBLIC')
           || ':' || privilege.privilege_type || ':' || grantor.rolname || ':' || privilege.is_grantable::text
      FROM pg_catalog.pg_language AS language
      CROSS JOIN LATERAL pg_catalog.aclexplode(COALESCE(language.lanacl, pg_catalog.acldefault('l', language.lanowner))) AS privilege
      LEFT JOIN protected AS grantee ON grantee.oid = privilege.grantee
      JOIN pg_catalog.pg_roles AS grantor ON grantor.oid = privilege.grantor
     WHERE privilege.grantee = 0 OR grantee.oid IS NOT NULL
    UNION ALL
    SELECT 'foreign-wrapper:' || wrapper.fdwname || ':' || COALESCE(grantee.rolname, 'PUBLIC')
           || ':' || privilege.privilege_type || ':' || grantor.rolname || ':' || privilege.is_grantable::text
      FROM pg_catalog.pg_foreign_data_wrapper AS wrapper
      CROSS JOIN LATERAL pg_catalog.aclexplode(COALESCE(wrapper.fdwacl, pg_catalog.acldefault('F', wrapper.fdwowner))) AS privilege
      LEFT JOIN protected AS grantee ON grantee.oid = privilege.grantee
      JOIN pg_catalog.pg_roles AS grantor ON grantor.oid = privilege.grantor
     WHERE privilege.grantee = 0 OR grantee.oid IS NOT NULL
    UNION ALL
    SELECT 'foreign-server:' || server.srvname || ':' || COALESCE(grantee.rolname, 'PUBLIC')
           || ':' || privilege.privilege_type || ':' || grantor.rolname || ':' || privilege.is_grantable::text
      FROM pg_catalog.pg_foreign_server AS server
      CROSS JOIN LATERAL pg_catalog.aclexplode(COALESCE(server.srvacl, pg_catalog.acldefault('S', server.srvowner))) AS privilege
      LEFT JOIN protected AS grantee ON grantee.oid = privilege.grantee
      JOIN pg_catalog.pg_roles AS grantor ON grantor.oid = privilege.grantor
     WHERE privilege.grantee = 0 OR grantee.oid IS NOT NULL
    UNION ALL
    -- Large objects have no dump/restore-stable public name.  No authority
    -- profile permits one, so bind their count and ACL tuples without using
    -- their volatile OIDs; any object or grantee is still profile-visible.
    SELECT 'large-object:' || count(*)::text || ':' || COALESCE(
               string_agg(
                   COALESCE(grantee.rolname, 'PUBLIC') || ':' || privilege.privilege_type
                   || ':' || grantor.rolname || ':' || privilege.is_grantable::text,
                   ',' ORDER BY COALESCE(grantee.rolname, 'PUBLIC'), privilege.privilege_type,
                   grantor.rolname, privilege.is_grantable
               ), ''
           )
      FROM pg_catalog.pg_largeobject_metadata AS metadata
      LEFT JOIN LATERAL pg_catalog.aclexplode(COALESCE(metadata.lomacl, pg_catalog.acldefault('L', metadata.lomowner))) AS privilege ON true
      LEFT JOIN protected AS grantee ON grantee.oid = privilege.grantee
      LEFT JOIN pg_catalog.pg_roles AS grantor ON grantor.oid = privilege.grantor
    UNION ALL
    -- PostgreSQL 18 exposes parameter ACLs in their own catalog.  They have
    -- no owner/default ACL surface, so every concrete grant is an explicit
    -- canonical tuple and an unexpected grantee cannot hide behind a role
    -- filter.
    SELECT 'parameter:' || parameter_acl.parname || ':' || COALESCE(grantee.rolname, 'PUBLIC')
           || ':' || privilege.privilege_type || ':' || grantor.rolname || ':' || privilege.is_grantable::text
      FROM pg_catalog.pg_parameter_acl AS parameter_acl
      CROSS JOIN LATERAL pg_catalog.aclexplode(parameter_acl.paracl) AS privilege
      LEFT JOIN protected AS grantee ON grantee.oid = privilege.grantee
      JOIN pg_catalog.pg_roles AS grantor ON grantor.oid = privilege.grantor
     WHERE privilege.grantee = 0 OR grantee.oid IS NOT NULL
    UNION ALL
    SELECT 'routine:' || namespace.nspname || '.' || routine.proname || '('
           || pg_catalog.pg_get_function_identity_arguments(routine.oid) || '):'
           || COALESCE(grantee.rolname, 'PUBLIC') || ':' || privilege.privilege_type
           || ':' || grantor.rolname || ':' || privilege.is_grantable::text
      FROM pg_catalog.pg_proc AS routine
      JOIN profiled_namespace AS namespace ON namespace.oid = routine.pronamespace
      CROSS JOIN LATERAL pg_catalog.aclexplode(COALESCE(routine.proacl, pg_catalog.acldefault('f', routine.proowner))) AS privilege
      LEFT JOIN protected AS grantee ON grantee.oid = privilege.grantee
      JOIN pg_catalog.pg_roles AS grantor ON grantor.oid = privilege.grantor
     WHERE privilege.grantee = 0 OR grantee.oid IS NOT NULL
    UNION ALL
    SELECT 'type:' || namespace.nspname || '.' || type.typname || ':'
           || COALESCE(grantee.rolname, 'PUBLIC') || ':' || privilege.privilege_type
           || ':' || grantor.rolname || ':' || privilege.is_grantable::text
      FROM pg_catalog.pg_type AS type
      JOIN profiled_namespace AS namespace ON namespace.oid = type.typnamespace
      LEFT JOIN pg_catalog.pg_class AS type_relation ON type_relation.oid = type.typrelid
      LEFT JOIN pg_catalog.pg_inherits AS type_inheritance
        ON type_inheritance.inhrelid = type_relation.oid
      LEFT JOIN pg_catalog.pg_class AS type_parent ON type_parent.oid = type_inheritance.inhparent
      LEFT JOIN pg_catalog.pg_type AS element_type ON element_type.oid = type.typelem
      LEFT JOIN pg_catalog.pg_class AS element_relation ON element_relation.oid = element_type.typrelid
      LEFT JOIN pg_catalog.pg_inherits AS element_inheritance
        ON element_inheritance.inhrelid = element_relation.oid
      LEFT JOIN pg_catalog.pg_class AS element_parent ON element_parent.oid = element_inheritance.inhparent
      CROSS JOIN LATERAL pg_catalog.aclexplode(COALESCE(type.typacl, pg_catalog.acldefault('T', type.typowner))) AS privilege
      LEFT JOIN protected AS grantee ON grantee.oid = privilege.grantee
      JOIN pg_catalog.pg_roles AS grantor ON grantor.oid = privilege.grantor
     WHERE (type.typrelid = 0 OR type_parent.oid IS NULL)
       AND (element_type.oid IS NULL OR element_type.typrelid = 0 OR element_parent.oid IS NULL)
       AND (privilege.grantee = 0 OR grantee.oid IS NOT NULL)
), partition_acl_actual AS (
    SELECT child.oid, parent.relname AS parent_name,
           pg_catalog.pg_get_expr(child.relpartbound, child.oid) AS partition_bound,
           COALESCE(
               array_agg(
                   COALESCE(grantee.rolname, 'PUBLIC') || ':' || privilege.privilege_type
                   ORDER BY COALESCE(grantee.rolname, 'PUBLIC'), privilege.privilege_type
               ) FILTER (
                   WHERE privilege.privilege_type IS NOT NULL
                     -- Relation ownership is authenticated independently by
                     -- the schema profile.  PostgreSQL materialises the
                     -- owner's implicit full table ACL when a child receives
                     -- any explicit grant, so retaining it here would turn a
                     -- harmless representation detail into a false per-leaf
                     -- mismatch.  Every *other* grantee, including unknown
                     -- roles, remains in the exact matrix below.
                     AND COALESCE(grantee.rolname, 'PUBLIC') <> 'tracebed_owner'
               ),
               ARRAY[]::text[]
           ) AS acl
      FROM pg_catalog.pg_class AS child
      JOIN pg_catalog.pg_inherits AS inheritance ON inheritance.inhrelid = child.oid
      JOIN pg_catalog.pg_class AS parent ON parent.oid = inheritance.inhparent
      JOIN pg_catalog.pg_namespace AS parent_namespace ON parent_namespace.oid = parent.relnamespace
      -- Compare only direct leaf grants.  Implicit owner privileges are
      -- authenticated via the trusted-owner schema tuples and are not a
      -- mutable per-project ACL surface.
      LEFT JOIN LATERAL pg_catalog.aclexplode(child.relacl) AS privilege ON true
      LEFT JOIN protected AS grantee ON grantee.oid = privilege.grantee
     WHERE parent_namespace.nspname = 'public'
       AND parent.relname IN (
           'memory_item','memory_link','derived_state','trace_index','trace_subject','subject_key',
           'outcome_event','injection_log','retrieval_event','blackboard_entry','invalidation_event',
           'spend_ledger','review_queue','memory_status_log','memory_q_update','trace_learning_job','run_owner',
           'subject_fence','run_fence','erase_run_set','erase_mem_set','run_memory_binding'
       )
     GROUP BY child.oid, parent.relname, child.relpartbound
), partition_acl_mismatch AS (
    SELECT 'partition-acl:' || parent_name || ':' || partition_bound AS identity
      FROM partition_acl_actual
     WHERE acl IS DISTINCT FROM CASE
         WHEN profile::text IN ('genuine_0010', 'hardened_0010') THEN
             CASE parent_name
                 WHEN 'run_owner' THEN ARRAY[
                     'tracebed_api_group:INSERT', 'tracebed_api_group:SELECT',
                     'tracebed_app:INSERT', 'tracebed_app:SELECT', 'tracebed_worker_group:SELECT'
                 ]::text[]
                 WHEN 'trace_index' THEN ARRAY[
                     'tracebed_app:INSERT', 'tracebed_app:SELECT', 'tracebed_app:UPDATE'
                 ]::text[]
                 WHEN 'trace_learning_job' THEN ARRAY[
                     'tracebed_app:INSERT', 'tracebed_app:SELECT', 'tracebed_app:UPDATE'
                 ]::text[]
                 ELSE ARRAY[
                     'tracebed_app:DELETE', 'tracebed_app:INSERT', 'tracebed_app:SELECT', 'tracebed_app:UPDATE'
                 ]::text[]
             END
        -- c11's split-runtime leaf matrix.  c12 is intentionally separate:
        -- E2 removes the residual raw API run-owner admission and worker
        -- trace-subject/key writers, replacing them with the profiled SECDEF
        -- entry points.  Collapsing the two profiles would make a valid c12
        -- project leaf look like ACL drift (or, worse, bless an E2 bypass).
        WHEN profile::text = 'cutover_0011' THEN
             CASE parent_name
                 WHEN 'memory_item' THEN ARRAY['tracebed_api_group:SELECT','tracebed_worker_group:INSERT','tracebed_worker_group:SELECT','tracebed_worker_group:UPDATE']::text[]
                 WHEN 'memory_link' THEN ARRAY['tracebed_api_group:SELECT','tracebed_worker_group:SELECT']::text[]
                 WHEN 'derived_state' THEN ARRAY['tracebed_api_group:SELECT','tracebed_worker_group:DELETE','tracebed_worker_group:INSERT','tracebed_worker_group:SELECT']::text[]
                 WHEN 'trace_index' THEN ARRAY['tracebed_api_group:SELECT','tracebed_worker_group:INSERT','tracebed_worker_group:SELECT','tracebed_worker_group:UPDATE']::text[]
                 WHEN 'trace_subject' THEN ARRAY['tracebed_worker_group:INSERT','tracebed_worker_group:SELECT']::text[]
                 WHEN 'subject_key' THEN ARRAY['tracebed_worker_group:INSERT','tracebed_worker_group:SELECT']::text[]
                 WHEN 'outcome_event' THEN ARRAY['tracebed_api_group:SELECT','tracebed_worker_group:INSERT','tracebed_worker_group:SELECT']::text[]
                 WHEN 'injection_log' THEN ARRAY['tracebed_api_group:INSERT','tracebed_api_group:SELECT','tracebed_worker_group:SELECT']::text[]
                 WHEN 'retrieval_event' THEN ARRAY['tracebed_api_group:INSERT','tracebed_api_group:SELECT','tracebed_worker_group:SELECT']::text[]
                 WHEN 'blackboard_entry' THEN ARRAY[]::text[]
                 WHEN 'invalidation_event' THEN ARRAY['tracebed_api_group:INSERT','tracebed_api_group:SELECT','tracebed_worker_group:SELECT']::text[]
                 WHEN 'spend_ledger' THEN ARRAY['tracebed_api_group:SELECT','tracebed_worker_group:INSERT','tracebed_worker_group:SELECT','tracebed_worker_group:UPDATE']::text[]
                 WHEN 'review_queue' THEN ARRAY['tracebed_api_group:SELECT','tracebed_worker_group:INSERT','tracebed_worker_group:SELECT']::text[]
                 WHEN 'memory_status_log' THEN ARRAY['tracebed_worker_group:INSERT','tracebed_worker_group:SELECT']::text[]
                 WHEN 'memory_q_update' THEN ARRAY['tracebed_worker_group:INSERT','tracebed_worker_group:SELECT']::text[]
                 WHEN 'trace_learning_job' THEN ARRAY['tracebed_worker_group:INSERT','tracebed_worker_group:SELECT','tracebed_worker_group:UPDATE']::text[]
                 WHEN 'run_owner' THEN ARRAY['tracebed_api_group:INSERT','tracebed_api_group:SELECT','tracebed_worker_group:SELECT']::text[]
                 WHEN 'subject_fence' THEN ARRAY[]::text[]
                 WHEN 'run_fence' THEN ARRAY[]::text[]
                 WHEN 'erase_run_set' THEN ARRAY[]::text[]
                 WHEN 'erase_mem_set' THEN ARRAY[]::text[]
                 WHEN 'run_memory_binding' THEN ARRAY[]::text[]
                 ELSE NULL
             END
        -- c12 preserves every ordinary c11 grant, but no runtime identity
        -- may directly create a run owner, trace subject, or v2 subject key.
        -- These exact leaf ACLs must be part of the profile comparison too:
        -- a clean reference with no projects cannot observe a leaf, whereas
        -- a provisioned production project can.
        WHEN profile::text = 'cutover_0012' THEN
             CASE parent_name
                 WHEN 'memory_item' THEN ARRAY['tracebed_api_group:SELECT','tracebed_worker_group:INSERT','tracebed_worker_group:SELECT','tracebed_worker_group:UPDATE']::text[]
                 WHEN 'memory_link' THEN ARRAY['tracebed_api_group:SELECT','tracebed_worker_group:SELECT']::text[]
                 WHEN 'derived_state' THEN ARRAY['tracebed_api_group:SELECT','tracebed_worker_group:DELETE','tracebed_worker_group:INSERT','tracebed_worker_group:SELECT']::text[]
                 WHEN 'trace_index' THEN ARRAY['tracebed_api_group:SELECT','tracebed_worker_group:INSERT','tracebed_worker_group:SELECT','tracebed_worker_group:UPDATE']::text[]
                 WHEN 'trace_subject' THEN ARRAY['tracebed_worker_group:SELECT']::text[]
                 WHEN 'subject_key' THEN ARRAY['tracebed_worker_group:SELECT']::text[]
                 WHEN 'outcome_event' THEN ARRAY['tracebed_api_group:SELECT','tracebed_worker_group:INSERT','tracebed_worker_group:SELECT']::text[]
                 WHEN 'injection_log' THEN ARRAY['tracebed_api_group:INSERT','tracebed_api_group:SELECT','tracebed_worker_group:SELECT']::text[]
                 WHEN 'retrieval_event' THEN ARRAY['tracebed_api_group:INSERT','tracebed_api_group:SELECT','tracebed_worker_group:SELECT']::text[]
                 WHEN 'blackboard_entry' THEN ARRAY[]::text[]
                 WHEN 'invalidation_event' THEN ARRAY['tracebed_api_group:SELECT','tracebed_worker_group:SELECT']::text[]
                 WHEN 'spend_ledger' THEN ARRAY['tracebed_api_group:SELECT','tracebed_worker_group:INSERT','tracebed_worker_group:SELECT','tracebed_worker_group:UPDATE']::text[]
                 WHEN 'review_queue' THEN ARRAY['tracebed_api_group:SELECT','tracebed_worker_group:INSERT','tracebed_worker_group:SELECT']::text[]
                 WHEN 'memory_status_log' THEN ARRAY['tracebed_worker_group:INSERT','tracebed_worker_group:SELECT']::text[]
                 WHEN 'memory_q_update' THEN ARRAY['tracebed_worker_group:INSERT','tracebed_worker_group:SELECT']::text[]
                 WHEN 'trace_learning_job' THEN ARRAY['tracebed_worker_group:INSERT','tracebed_worker_group:SELECT','tracebed_worker_group:UPDATE']::text[]
                 WHEN 'run_owner' THEN ARRAY['tracebed_api_group:SELECT','tracebed_worker_group:SELECT']::text[]
                 WHEN 'subject_fence' THEN ARRAY[]::text[]
                 WHEN 'run_fence' THEN ARRAY[]::text[]
                 WHEN 'erase_run_set' THEN ARRAY[]::text[]
                 WHEN 'erase_mem_set' THEN ARRAY[]::text[]
                 WHEN 'run_memory_binding' THEN ARRAY[]::text[]
                 ELSE NULL
             END
         ELSE NULL
     END
), partition_acl_metadata_mismatch AS (
    -- The visible matrix above authenticates every non-owner grantee and
    -- privilege.  This companion records the privilege metadata which would
    -- otherwise be hidden by PostgreSQL's materialised owner ACL: grants must
    -- be owner-issued and never grantable.  Grouping the exceptional leaves
    -- by parent keeps a healthy project-count change digest-invariant while
    -- binding the full offending leaf/bound/ACL tuple once drift appears.
    SELECT 'partition-acl-metadata:' || parent_name || ':' || encode(
        pg_catalog.sha256(pg_catalog.convert_to(
            string_agg(
                partition_bound || chr(31) || COALESCE(grantee_name, 'PUBLIC') || chr(31)
                || privilege_type || chr(31) || grantor_name || chr(31) || is_grantable::text,
                chr(30) ORDER BY partition_bound, COALESCE(grantee_name, 'PUBLIC'),
                privilege_type, grantor_name, is_grantable
            ), 'UTF8'
        )), 'hex'
    ) AS identity
      FROM (
          SELECT parent.relname AS parent_name,
                 pg_catalog.pg_get_expr(child.relpartbound, child.oid) AS partition_bound,
                 grantee.rolname AS grantee_name,
                 privilege.privilege_type,
                 grantor.rolname AS grantor_name,
                 privilege.is_grantable
            FROM pg_catalog.pg_class AS child
            JOIN pg_catalog.pg_inherits AS inheritance ON inheritance.inhrelid = child.oid
            JOIN pg_catalog.pg_class AS parent ON parent.oid = inheritance.inhparent
            JOIN pg_catalog.pg_namespace AS parent_namespace ON parent_namespace.oid = parent.relnamespace
            CROSS JOIN LATERAL pg_catalog.aclexplode(child.relacl) AS privilege
            LEFT JOIN pg_catalog.pg_roles AS grantee ON grantee.oid = privilege.grantee
            JOIN pg_catalog.pg_roles AS grantor ON grantor.oid = privilege.grantor
           WHERE parent_namespace.nspname = 'public'
             AND parent.relname IN (
                 'memory_item','memory_link','derived_state','trace_index','trace_subject','subject_key',
                 'outcome_event','injection_log','retrieval_event','blackboard_entry','invalidation_event',
                 'spend_ledger','review_queue','memory_status_log','memory_q_update','trace_learning_job','run_owner',
                 'subject_fence','run_fence','erase_run_set','erase_mem_set','run_memory_binding'
             )
             AND (
                 grantor.rolname <> 'tracebed_owner'
                 OR privilege.is_grantable
             )
      ) AS anomalous_leaf_acl
     GROUP BY parent_name
), partition_column_acl_mismatch AS (
    -- No profile grants column-level access on a project leaf.  Aggregate all
    -- direct child-column ACL metadata by parent so an ordinary new project
    -- remains digest-invariant while any role/grantor/grant-option drift is
    -- represented by one deterministic exceptional tuple.
    SELECT 'partition-column-acl:' || parent_name || ':' || encode(
        pg_catalog.sha256(pg_catalog.convert_to(
            string_agg(
                partition_bound || chr(31) || attribute_name || chr(31)
                || COALESCE(grantee_name, 'PUBLIC') || chr(31) || privilege_type || chr(31)
                || grantor_name || chr(31) || is_grantable::text,
                chr(30) ORDER BY partition_bound, attribute_name, COALESCE(grantee_name, 'PUBLIC'),
                privilege_type, grantor_name, is_grantable
            ), 'UTF8'
        )), 'hex'
    ) AS identity
      FROM (
          SELECT parent.relname AS parent_name,
                 pg_catalog.pg_get_expr(child.relpartbound, child.oid) AS partition_bound,
                 attribute.attname::text AS attribute_name,
                 grantee.rolname AS grantee_name,
                 privilege.privilege_type,
                 grantor.rolname AS grantor_name,
                 privilege.is_grantable
            FROM pg_catalog.pg_class AS child
            JOIN pg_catalog.pg_inherits AS inheritance ON inheritance.inhrelid = child.oid
            JOIN pg_catalog.pg_class AS parent ON parent.oid = inheritance.inhparent
            JOIN pg_catalog.pg_namespace AS parent_namespace ON parent_namespace.oid = parent.relnamespace
            JOIN pg_catalog.pg_attribute AS attribute
              ON attribute.attrelid = child.oid
             AND attribute.attnum > 0
             AND NOT attribute.attisdropped
            CROSS JOIN LATERAL pg_catalog.aclexplode(attribute.attacl) AS privilege
            LEFT JOIN pg_catalog.pg_roles AS grantee ON grantee.oid = privilege.grantee
            JOIN pg_catalog.pg_roles AS grantor ON grantor.oid = privilege.grantor
           WHERE parent_namespace.nspname = 'public'
             AND parent.relname IN (
                 'memory_item','memory_link','derived_state','trace_index','trace_subject','subject_key',
                 'outcome_event','injection_log','retrieval_event','blackboard_entry','invalidation_event',
                 'spend_ledger','review_queue','memory_status_log','memory_q_update','trace_learning_job','run_owner',
                 'subject_fence','run_fence','erase_run_set','erase_mem_set','run_memory_binding'
             )
      ) AS exceptional_column_acl
     GROUP BY parent_name
), entry AS (
    SELECT identity FROM raw_entry
    UNION ALL
    SELECT identity FROM partition_acl_mismatch
    UNION ALL
    SELECT identity FROM partition_acl_metadata_mismatch
    UNION ALL
    SELECT identity FROM partition_column_acl_mismatch
)
SELECT pg_catalog.sha256(pg_catalog.convert_to(
    'tracebed.authority-acl-tuple/v1' || chr(31) || identity, 'UTF8'
))
  FROM entry
 WHERE identity IS NOT NULL
$$;

CREATE FUNCTION public.authority_acl_security_assert(
    profile public.authority_acl_profile
) RETURNS bytea
LANGUAGE plpgsql VOLATILE STRICT SECURITY INVOKER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    actual_digest bytea;
BEGIN
    -- Acquire the parent relations in the exact DDL creation order before
    -- touching any authenticated catalog collector.  ``ONLY`` is essential:
    -- a profile assertion must serialize with parent DDL, not lock every
    -- tenant leaf while it is reading the catalog.
    LOCK TABLE ONLY public.memory_item IN ACCESS SHARE MODE;
    LOCK TABLE ONLY public.memory_link IN ACCESS SHARE MODE;
    LOCK TABLE ONLY public.derived_state IN ACCESS SHARE MODE;
    LOCK TABLE ONLY public.trace_index IN ACCESS SHARE MODE;
    LOCK TABLE ONLY public.trace_subject IN ACCESS SHARE MODE;
    LOCK TABLE ONLY public.subject_key IN ACCESS SHARE MODE;
    LOCK TABLE ONLY public.outcome_event IN ACCESS SHARE MODE;
    LOCK TABLE ONLY public.injection_log IN ACCESS SHARE MODE;
    LOCK TABLE ONLY public.retrieval_event IN ACCESS SHARE MODE;
    LOCK TABLE ONLY public.blackboard_entry IN ACCESS SHARE MODE;
    LOCK TABLE ONLY public.invalidation_event IN ACCESS SHARE MODE;
    LOCK TABLE ONLY public.spend_ledger IN ACCESS SHARE MODE;
    LOCK TABLE ONLY public.review_queue IN ACCESS SHARE MODE;
    LOCK TABLE ONLY public.memory_status_log IN ACCESS SHARE MODE;
    LOCK TABLE ONLY public.memory_q_update IN ACCESS SHARE MODE;
    LOCK TABLE ONLY public.trace_learning_job IN ACCESS SHARE MODE;
    LOCK TABLE ONLY public.run_owner IN ACCESS SHARE MODE;
    IF profile = 'cutover_0012'::public.authority_acl_profile THEN
        LOCK TABLE ONLY public.subject_fence IN ACCESS SHARE MODE;
        LOCK TABLE ONLY public.run_fence IN ACCESS SHARE MODE;
        LOCK TABLE ONLY public.erase_run_set IN ACCESS SHARE MODE;
        LOCK TABLE ONLY public.erase_mem_set IN ACCESS SHARE MODE;
        LOCK TABLE ONLY public.run_memory_binding IN ACCESS SHARE MODE;
    END IF;
    -- The EXCEPTs deliberately test both missing expected grants and extra
    -- ones.  A digest comparison alone is not an authorization proof: it
    -- would make an epoch-zero snapshot authenticate a poisoned baseline.
    IF EXISTS (
        (SELECT tuple_digest FROM public.authority_acl_profile_actual_tuples(profile) AS actual(tuple_digest)
         EXCEPT
         SELECT tuple_digest FROM public.authority_acl_profile_tuple
          WHERE authority_acl_profile_tuple.profile = authority_acl_security_assert.profile
            AND tuple_class = 'acl')
        UNION ALL
        (SELECT tuple_digest FROM public.authority_acl_profile_tuple
          WHERE authority_acl_profile_tuple.profile = authority_acl_security_assert.profile
            AND tuple_class = 'acl'
         EXCEPT
         SELECT tuple_digest FROM public.authority_acl_profile_actual_tuples(profile) AS actual(tuple_digest))
    ) THEN
        RAISE EXCEPTION 'authority profile drift: ACL does not match its canonical expected tuples'
            USING ERRCODE = '55000';
    END IF;
    SELECT public.authority_acl_set_digest(COALESCE(array_agg(tuple_digest ORDER BY tuple_digest), ARRAY[]::bytea[]))
      INTO actual_digest
      FROM public.authority_acl_profile_actual_tuples(profile) AS actual(tuple_digest);
    RETURN actual_digest;
END;
$$;

CREATE FUNCTION public.authority_schema_profile_actual_tuples(
    profile public.authority_acl_profile
) RETURNS SETOF bytea
LANGUAGE sql STABLE STRICT SECURITY INVOKER
SET search_path = pg_catalog, pg_temp
AS $$
WITH profiled_namespace AS (
    -- Profile every non-system namespace.  Numeric toast/temp namespaces
    -- are PostgreSQL implementation artifacts; a user homonym is not.
    SELECT namespace.*
      FROM pg_catalog.pg_namespace AS namespace
     WHERE namespace.nspname NOT IN ('pg_catalog', 'information_schema', 'pg_toast')
       AND namespace.nspname !~ '^pg_temp_[0-9]+$'
       AND namespace.nspname !~ '^pg_toast_[0-9]+$'
       AND namespace.nspname !~ '^pg_toast_temp_[0-9]+$'
), partition_family(parent_name) AS (
    VALUES
        ('memory_item'), ('memory_link'), ('derived_state'), ('trace_index'),
        ('trace_subject'), ('subject_key'), ('outcome_event'), ('injection_log'),
        ('retrieval_event'), ('blackboard_entry'), ('invalidation_event'), ('spend_ledger'),
        ('review_queue'), ('memory_status_log'), ('memory_q_update'),
        ('trace_learning_job'), ('run_owner')
    UNION ALL
    SELECT parent_name
      FROM (VALUES ('subject_fence'), ('run_fence'), ('erase_run_set'), ('erase_mem_set'),
                   ('run_memory_binding'))
           AS erasure_parent(parent_name)
     WHERE profile = 'cutover_0012'::public.authority_acl_profile
), canonical_project_partition AS (
    -- Dynamic partition leaves are normalized only after their attachment,
    -- namespace, parent family, and singleton live-project bound all match.
    -- c12 alone additionally retains one fully scrubbed subject-key leaf for
    -- an authenticated project tombstone.  Every other inheritance edge,
    -- deleted family, or malformed retained key remains a physical profiled
    -- relation.
    SELECT child.oid AS child_oid,
           parent.oid AS parent_oid,
           parent_namespace.nspname AS parent_schema,
           parent.relname AS parent_name,
           pg_catalog.pg_get_expr(child.relpartbound, child.oid) AS partition_bound
      FROM pg_catalog.pg_inherits AS inheritance
      JOIN pg_catalog.pg_class AS child ON child.oid = inheritance.inhrelid
      JOIN pg_catalog.pg_namespace AS child_namespace ON child_namespace.oid = child.relnamespace
      JOIN pg_catalog.pg_class AS parent ON parent.oid = inheritance.inhparent
      JOIN pg_catalog.pg_namespace AS parent_namespace ON parent_namespace.oid = parent.relnamespace
      JOIN partition_family AS family ON family.parent_name = parent.relname
      JOIN public.project AS bound_project
        ON pg_catalog.pg_get_expr(child.relpartbound, child.oid)
            = pg_catalog.format('FOR VALUES IN (%L)', bound_project.project_id)
     WHERE child_namespace.nspname = 'public'
       AND parent_namespace.nspname = 'public'
       AND child.relkind = 'r'
       AND parent.relkind = 'p'
       AND (
           (
               bound_project.status IN ('active', 'suspended')
               AND bound_project.deleted_at IS NULL
           )
           OR (
               profile = 'cutover_0012'::public.authority_acl_profile
               AND parent_namespace.nspname = 'public'
               AND parent.relname = 'subject_key'
               AND bound_project.status = 'deleted'
               AND bound_project.deleted_at IS NOT NULL
               AND pg_catalog.isfinite(bound_project.deleted_at)
               AND bound_project.name = 'deleted-project'
               AND bound_project.retention_policy IS NULL
               AND bound_project.provisioning_key_hash IS NULL
               AND bound_project.provisioning_request_hash IS NULL
               AND NOT EXISTS (
                   SELECT 1
                     FROM public.subject_key AS key_row
                     CROSS JOIN LATERAL (
                         SELECT pg_catalog.to_jsonb(key_row) AS value
                     ) AS key_json
                    WHERE key_row.tableoid = child.oid
                      AND key_row.project_id = bound_project.project_id
                      AND (
                          NOT (key_json.value ? 'destroyed_at')
                          OR key_json.value ->> 'destroyed_at' IS NULL
                          OR NOT pg_catalog.isfinite(
                              (key_json.value ->> 'destroyed_at')::timestamp with time zone
                          )
                          OR NOT (key_json.value ? 'created_at')
                          OR key_json.value ->> 'created_at' IS NULL
                          OR NOT pg_catalog.isfinite(
                              (key_json.value ->> 'created_at')::timestamp with time zone
                          )
                          OR (key_json.value ->> 'destroyed_at')::timestamp with time zone
                              < (key_json.value ->> 'created_at')::timestamp with time zone
                          OR NOT (key_json.value ? 'wrapped_kek')
                          OR key_json.value ->> 'wrapped_kek' IS NULL
                          OR (key_json.value ->> 'wrapped_kek')::bytea <> ''::bytea
                          OR key_json.value ->> 'subject_tag' IS NOT NULL
                          OR NOT (key_json.value ? 'subject_digest')
                          OR key_json.value ->> 'subject_digest' IS NULL
                          OR octet_length((key_json.value ->> 'subject_digest')::bytea) <> 32
                          OR NOT (key_json.value ? 'wrap_version')
                          OR key_json.value ->> 'wrap_version' IS NULL
                          OR (key_json.value ->> 'wrap_version')::smallint NOT IN (1, 2)
                      )
               )
           )
       )
       AND child.relname = parent.relname || '_p_' || replace(bound_project.project_id::text, '-', '')
       AND NOT EXISTS (
           SELECT 1
             FROM pg_catalog.pg_inherits AS other
            WHERE other.inhrelid = child.oid
              AND other.inhparent <> parent.oid
       )
), relation_set AS (
    SELECT relation.oid, namespace.nspname, relation.relname, relation.relkind,
           owner_role.rolname AS owner_name,
           relation.relrowsecurity, relation.relforcerowsecurity, relation.relpersistence,
           relation.relispartition, relation.relreplident, relation.reloptions,
           COALESCE(relation_access_method.amname, '') AS access_method_name,
           canonical.parent_schema, canonical.parent_name, canonical.partition_bound,
           CASE
               WHEN canonical.child_oid IS NULL THEN namespace.nspname || '.' || relation.relname
               ELSE canonical.parent_schema || '.' || canonical.parent_name || '.<project-partition>'
           END AS stable_identity,
           canonical.child_oid IS NOT NULL AS is_partition
      FROM pg_catalog.pg_class AS relation
      JOIN profiled_namespace AS namespace ON namespace.oid = relation.relnamespace
      JOIN pg_catalog.pg_roles AS owner_role ON owner_role.oid = relation.relowner
      LEFT JOIN pg_catalog.pg_am AS relation_access_method ON relation_access_method.oid = relation.relam
      LEFT JOIN canonical_project_partition AS canonical ON canonical.child_oid = relation.oid
     WHERE relation.relkind IN ('r', 'p', 'S', 'v', 'm', 'f')
), partition_index_spec(
    parent_name, suffix, access_method, key_names, key_options, opclasses, opclass_defaults, predicate
) AS (
    VALUES
        ('memory_item', 'hnsw', 'hnsw', ARRAY['embedding']::text[], ARRAY[0]::smallint[], ARRAY['public.halfvec_cosine_ops']::text[], ARRAY[false], NULL::text),
        ('memory_item', 'lex', 'gin', ARRAY['lexemes']::text[], ARRAY[0]::smallint[], ARRAY[NULL::text], ARRAY[true], NULL::text),
        ('memory_item', 'bm25', 'bm25', ARRAY['content_bm25']::text[], ARRAY[0]::smallint[], ARRAY['bm25_catalog.bm25_ops']::text[], ARRAY[false], NULL::text),
        ('memory_item', 'status', 'btree', ARRAY['status']::text[], ARRAY[0]::smallint[], ARRAY[NULL::text], ARRAY[true], NULL::text),
        ('memory_item', 'subject', 'btree', ARRAY['subject_tag']::text[], ARRAY[0]::smallint[], ARRAY[NULL::text], ARRAY[true], NULL::text),
        ('memory_item', 'verdict', 'btree', ARRAY['scan_verdict_id']::text[], ARRAY[0]::smallint[], ARRAY[NULL::text], ARRAY[true], NULL::text),
        ('trace_index', 'submitter', 'btree', ARRAY['submitter_principal']::text[], ARRAY[0]::smallint[], ARRAY[NULL::text], ARRAY[true], NULL::text),
        ('trace_index', 'outstatus', 'btree', ARRAY['outcome_status']::text[], ARRAY[0]::smallint[], ARRAY[NULL::text], ARRAY[true], NULL::text),
        ('outcome_event', 'run', 'btree', ARRAY['run_id']::text[], ARRAY[0]::smallint[], ARRAY[NULL::text], ARRAY[true], NULL::text),
        ('injection_log', 'mem', 'btree', ARRAY['memory_id']::text[], ARRAY[0]::smallint[], ARRAY[NULL::text], ARRAY[true], NULL::text),
        ('review_queue', 'mem', 'btree', ARRAY['memory_id']::text[], ARRAY[0]::smallint[], ARRAY[NULL::text], ARRAY[true], NULL::text),
        ('trace_subject', 'subject', 'btree',
         CASE WHEN profile = 'cutover_0012'::public.authority_acl_profile
              THEN ARRAY['subject_digest','run_id']::text[]
              ELSE ARRAY['subject_tag']::text[] END,
         CASE WHEN profile = 'cutover_0012'::public.authority_acl_profile
              THEN ARRAY[0,0]::smallint[] ELSE ARRAY[0]::smallint[] END,
         CASE WHEN profile = 'cutover_0012'::public.authority_acl_profile
              THEN ARRAY[NULL::text,NULL::text] ELSE ARRAY[NULL::text] END,
         CASE WHEN profile = 'cutover_0012'::public.authority_acl_profile
              THEN ARRAY[true,true] ELSE ARRAY[true] END,
         NULL::text),
        ('memory_status_log', 'mem', 'btree', ARRAY['memory_id','changed_at']::text[], ARRAY[0,3]::smallint[], ARRAY[NULL::text,NULL::text], ARRAY[true,true], NULL::text),
        ('memory_q_update', 'scored', 'btree', ARRAY['project_id','memory_id','scored_at']::text[], ARRAY[0,0,0]::smallint[], ARRAY[NULL::text,NULL::text,NULL::text], ARRAY[true,true,true], NULL::text),
        ('trace_learning_job', 'ready', 'btree', ARRAY['pipeline','pipeline_version','available_at','scheduled_at','run_id']::text[], ARRAY[0,0,0,0,0]::smallint[], ARRAY[NULL::text,NULL::text,NULL::text,NULL::text,NULL::text], ARRAY[true,true,true,true,true], '(state = ANY (ARRAY[''pending''::text, ''retry''::text]))'::text),
        ('trace_learning_job', 'lease', 'btree', ARRAY['pipeline','pipeline_version','lease_expires_at','scheduled_at','run_id']::text[], ARRAY[0,0,0,0,0]::smallint[], ARRAY[NULL::text,NULL::text,NULL::text,NULL::text,NULL::text], ARRAY[true,true,true,true,true], '(state = ''running''::text)'::text),
        ('run_owner', 'owner', 'btree', ARRAY['principal_id','agent_type_id','run_id']::text[], ARRAY[0,0,0]::smallint[], ARRAY[NULL::text,NULL::text,NULL::text], ARRAY[true,true,true], NULL::text)
    UNION ALL
    SELECT *
      FROM (VALUES
          ('memory_item', 'subjects', 'gin', ARRAY['subject_digests']::text[], ARRAY[0]::smallint[], ARRAY[NULL::text], ARRAY[true], NULL::text),
          ('outcome_event', 'subjects', 'gin', ARRAY['subject_digests']::text[], ARRAY[0]::smallint[], ARRAY[NULL::text], ARRAY[true], NULL::text),
          ('invalidation_event', 'subjects', 'gin', ARRAY['subject_digests']::text[], ARRAY[0]::smallint[], ARRAY[NULL::text], ARRAY[true], NULL::text),
          ('trace_learning_job', 'subjects', 'gin', ARRAY['subject_digests']::text[], ARRAY[0]::smallint[], ARRAY[NULL::text], ARRAY[true], NULL::text),
          ('run_owner', 'subjects', 'gin', ARRAY['subject_digests']::text[], ARRAY[0]::smallint[], ARRAY[NULL::text], ARRAY[true], NULL::text),
          ('trace_index', 'subjects', 'gin', ARRAY['subject_digests']::text[], ARRAY[0]::smallint[], ARRAY[NULL::text], ARRAY[true], NULL::text),
          ('injection_log', 'subjects', 'gin', ARRAY['subject_digests']::text[], ARRAY[0]::smallint[], ARRAY[NULL::text], ARRAY[true], NULL::text),
          ('retrieval_event', 'subjects', 'gin', ARRAY['subject_digests']::text[], ARRAY[0]::smallint[], ARRAY[NULL::text], ARRAY[true], NULL::text),
          ('blackboard_entry', 'subjects', 'gin', ARRAY['subject_digests']::text[], ARRAY[0]::smallint[], ARRAY[NULL::text], ARRAY[true], NULL::text),
          ('memory_link', 'subjects', 'gin', ARRAY['subject_digests']::text[], ARRAY[0]::smallint[], ARRAY[NULL::text], ARRAY[true], NULL::text),
          ('derived_state', 'subjects', 'gin', ARRAY['subject_digests']::text[], ARRAY[0]::smallint[], ARRAY[NULL::text], ARRAY[true], NULL::text),
          ('spend_ledger', 'subjects', 'gin', ARRAY['subject_digests']::text[], ARRAY[0]::smallint[], ARRAY[NULL::text], ARRAY[true], NULL::text),
          ('review_queue', 'subjects', 'gin', ARRAY['subject_digests']::text[], ARRAY[0]::smallint[], ARRAY[NULL::text], ARRAY[true], NULL::text),
          ('memory_status_log', 'subjects', 'gin', ARRAY['subject_digests']::text[], ARRAY[0]::smallint[], ARRAY[NULL::text], ARRAY[true], NULL::text),
          ('memory_q_update', 'subjects', 'gin', ARRAY['subject_digests']::text[], ARRAY[0]::smallint[], ARRAY[NULL::text], ARRAY[true], NULL::text),
          -- These are attached children of partitioned partial-unique parent
          -- indexes. PostgreSQL assigns child names from a truncated physical
          -- leaf name, so bind their semantic parent-index attachment rather
          -- than accepting a spelling-dependent generated name.
          ('subject_key', '@subject_key_raw_tag_uq', 'btree', ARRAY['project_id','subject_tag']::text[], ARRAY[0,0]::smallint[], ARRAY[NULL::text,NULL::text], ARRAY[true,true], '(subject_tag IS NOT NULL)'::text),
          ('trace_subject', '@trace_subject_raw_tag_uq', 'btree', ARRAY['project_id','run_id','subject_tag']::text[], ARRAY[0,0,0]::smallint[], ARRAY[NULL::text,NULL::text,NULL::text], ARRAY[true,true,true], '(subject_tag IS NOT NULL)'::text),
          ('subject_fence', 'state', 'btree', ARRAY['state','subject_digest']::text[], ARRAY[0,0]::smallint[], ARRAY[NULL::text,NULL::text], ARRAY[true,true], NULL::text),
          ('run_fence', 'state', 'btree', ARRAY['state','run_id']::text[], ARRAY[0,0]::smallint[], ARRAY[NULL::text,NULL::text], ARRAY[true,true], NULL::text),
          ('run_memory_binding', 'run', 'btree', ARRAY['run_id','memory_id']::text[], ARRAY[0,0]::smallint[], ARRAY[NULL::text,NULL::text], ARRAY[true,true], NULL::text)
      ) AS erasure_spec(parent_name, suffix, access_method, key_names, key_options, opclasses, opclass_defaults, predicate)
     WHERE profile = 'cutover_0012'::public.authority_acl_profile
), partition_health AS (
    SELECT family.parent_name,
           COALESCE(
               bool_and(
                   leaf.oid IS NULL OR (
                       leaf_namespace.nspname = 'public'
                       AND leaf.relrowsecurity
                       AND leaf.relforcerowsecurity
                       AND leaf.relowner = parent.relowner
                       AND leaf.relpersistence = 'p'
                       AND leaf.relreplident = parent.relreplident
                       AND leaf.reloptions IS NULL
                       AND leaf.relpartbound IS NOT NULL
                       AND EXISTS (
                           SELECT 1
                             FROM public.project AS bound_project
                            WHERE pg_catalog.pg_get_expr(leaf.relpartbound, leaf.oid)
                                      = pg_catalog.format('FOR VALUES IN (%L)', bound_project.project_id)
                              AND (
                                  (
                                      bound_project.status IN ('active', 'suspended')
                                      AND bound_project.deleted_at IS NULL
                                  )
                                  OR (
                                      profile = 'cutover_0012'::public.authority_acl_profile
                                      AND family.parent_name = 'subject_key'
                                      AND parent.relnamespace = 'public'::regnamespace
                                      AND parent.relname = 'subject_key'
                                      AND bound_project.status = 'deleted'
                                      AND bound_project.deleted_at IS NOT NULL
                                      AND pg_catalog.isfinite(bound_project.deleted_at)
                                      AND bound_project.name = 'deleted-project'
                                      AND bound_project.retention_policy IS NULL
                                      AND bound_project.provisioning_key_hash IS NULL
                                      AND bound_project.provisioning_request_hash IS NULL
                                      AND NOT EXISTS (
                                          SELECT 1
                                            FROM public.subject_key AS key_row
                                            CROSS JOIN LATERAL (
                                                SELECT pg_catalog.to_jsonb(key_row) AS value
                                            ) AS key_json
                                           WHERE key_row.tableoid = leaf.oid
                                             AND key_row.project_id = bound_project.project_id
                                             AND (
                                                 NOT (key_json.value ? 'destroyed_at')
                                                 OR key_json.value ->> 'destroyed_at' IS NULL
                                                 OR NOT pg_catalog.isfinite(
                                                     (key_json.value ->> 'destroyed_at')::timestamp with time zone
                                                 )
                                                 OR NOT (key_json.value ? 'created_at')
                                                 OR key_json.value ->> 'created_at' IS NULL
                                                 OR NOT pg_catalog.isfinite(
                                                     (key_json.value ->> 'created_at')::timestamp with time zone
                                                 )
                                                 OR (key_json.value ->> 'destroyed_at')::timestamp with time zone
                                                     < (key_json.value ->> 'created_at')::timestamp with time zone
                                                 OR NOT (key_json.value ? 'wrapped_kek')
                                                 OR key_json.value ->> 'wrapped_kek' IS NULL
                                                 OR (key_json.value ->> 'wrapped_kek')::bytea <> ''::bytea
                                                 OR key_json.value ->> 'subject_tag' IS NOT NULL
                                                 OR NOT (key_json.value ? 'subject_digest')
                                                 OR key_json.value ->> 'subject_digest' IS NULL
                                                 OR octet_length((key_json.value ->> 'subject_digest')::bytea) <> 32
                                                 OR NOT (key_json.value ? 'wrap_version')
                                                 OR key_json.value ->> 'wrap_version' IS NULL
                                                 OR (key_json.value ->> 'wrap_version')::smallint NOT IN (1, 2)
                                             )
                                      )
                                  )
                              )
                       )
                       AND NOT EXISTS (
                           SELECT 1
                             FROM partition_index_spec AS expected_index
                            WHERE expected_index.parent_name = family.parent_name
                              AND NOT EXISTS (
                                  SELECT 1
                                    FROM pg_catalog.pg_index AS index_data
                                    JOIN pg_catalog.pg_class AS index_class
                                      ON index_class.oid = index_data.indexrelid
                                    JOIN pg_catalog.pg_namespace AS index_namespace
                                      ON index_namespace.oid = index_class.relnamespace
                                    JOIN pg_catalog.pg_am AS access_method
                                      ON access_method.oid = index_class.relam
                                   WHERE index_data.indrelid = leaf.oid
                                     AND index_namespace.nspname = 'public'
                                     AND (
                                         (left(expected_index.suffix, 1) <> '@'
                                          AND index_class.relname = leaf.relname || '_' || expected_index.suffix)
                                         OR (
                                             left(expected_index.suffix, 1) = '@'
                                             AND EXISTS (
                                                 SELECT 1
                                                   FROM pg_catalog.pg_inherits AS index_inheritance
                                                   JOIN pg_catalog.pg_class AS parent_index
                                                     ON parent_index.oid = index_inheritance.inhparent
                                                  WHERE index_inheritance.inhrelid = index_class.oid
                                                    AND parent_index.relname = substr(expected_index.suffix, 2)
                                                    AND parent_index.relnamespace = 'public'::regnamespace
                                             )
                                         )
                                     )
                                     AND access_method.amname = expected_index.access_method
                                     AND index_data.indisvalid
                                     AND index_data.indisready
                                     AND index_data.indislive
                                     AND NOT index_data.indcheckxmin
                                     AND (
                                         (left(expected_index.suffix, 1) = '@' AND index_data.indisunique)
                                         OR (left(expected_index.suffix, 1) <> '@' AND NOT index_data.indisunique)
                                     )
                                     AND NOT index_data.indisprimary
                                     AND NOT index_data.indisexclusion
                                     AND NOT index_data.indisclustered
                                     AND NOT index_data.indisreplident
                                     AND NOT index_data.indnullsnotdistinct
                                     AND index_data.indimmediate
                                     AND index_class.relkind = 'i'
                                     AND index_class.relpersistence = 'p'
                                     AND index_class.reloptions IS NULL
                                     AND index_data.indnkeyatts = cardinality(expected_index.key_names)
                                     AND index_data.indnatts = cardinality(expected_index.key_names)
                                     AND cardinality(index_data.indkey::smallint[]) = cardinality(expected_index.key_names)
                                     AND cardinality(index_data.indoption::smallint[]) = cardinality(expected_index.key_options)
                                     AND cardinality(index_data.indclass::oid[]) = cardinality(expected_index.opclasses)
                                     AND cardinality(index_data.indclass::oid[]) = cardinality(expected_index.opclass_defaults)
                                     AND (
                                         SELECT array_agg(attribute.attname::text ORDER BY key_position.ordinality)
                                           FROM unnest(index_data.indkey::smallint[]) WITH ORDINALITY
                                                AS key_position(attribute_number, ordinality)
                                           JOIN pg_catalog.pg_attribute AS attribute
                                             ON attribute.attrelid = leaf.oid
                                            AND attribute.attnum = key_position.attribute_number
                                     ) = expected_index.key_names
                                     AND (
                                         SELECT array_agg(key_option.option_value::smallint ORDER BY key_option.ordinality)
                                           FROM unnest(index_data.indoption::smallint[]) WITH ORDINALITY
                                                AS key_option(option_value, ordinality)
                                     ) = expected_index.key_options
                                     AND NOT EXISTS (
                                         SELECT 1
                                           FROM unnest(index_data.indkey::smallint[]) WITH ORDINALITY
                                                AS key_position(attribute_number, ordinality)
                                           JOIN unnest(index_data.indcollation::oid[]) WITH ORDINALITY
                                                AS key_collation(collation_oid, ordinality)
                                             USING (ordinality)
                                           JOIN pg_catalog.pg_attribute AS attribute
                                             ON attribute.attrelid = leaf.oid
                                            AND attribute.attnum = key_position.attribute_number
                                          WHERE key_collation.collation_oid IS DISTINCT FROM attribute.attcollation
                                     )
                                     AND NOT EXISTS (
                                         SELECT 1
                                           FROM unnest(index_data.indclass::oid[]) WITH ORDINALITY
                                                AS key_opclass(opclass_oid, ordinality)
                                           JOIN pg_catalog.pg_opclass AS opclass ON opclass.oid = key_opclass.opclass_oid
                                           JOIN pg_catalog.pg_namespace AS opclass_namespace
                                             ON opclass_namespace.oid = opclass.opcnamespace
                                          WHERE (
                                              expected_index.opclasses[key_opclass.ordinality] IS NULL
                                              AND NOT opclass.opcdefault
                                          ) OR (
                                              expected_index.opclasses[key_opclass.ordinality] IS NOT NULL
                                              AND opclass_namespace.nspname || '.' || opclass.opcname
                                                  IS DISTINCT FROM expected_index.opclasses[key_opclass.ordinality]
                                          ) OR (
                                              opclass.opcdefault IS DISTINCT FROM expected_index.opclass_defaults[key_opclass.ordinality]
                                          )
                                     )
                                     AND pg_catalog.pg_get_expr(index_data.indpred, leaf.oid)
                                         IS NOT DISTINCT FROM expected_index.predicate
                                     AND pg_catalog.pg_get_expr(index_data.indexprs, leaf.oid) IS NULL
                              )
                       )
                       AND NOT EXISTS (
                           SELECT 1
                             FROM pg_catalog.pg_index AS index_data
                             JOIN pg_catalog.pg_class AS index_class
                               ON index_class.oid = index_data.indexrelid
                            WHERE index_data.indrelid = leaf.oid
                              AND NOT index_data.indisprimary
                              AND NOT EXISTS (
                                  SELECT 1
                                    FROM partition_index_spec AS expected_index
                                   WHERE expected_index.parent_name = family.parent_name
                                     AND (
                                         (left(expected_index.suffix, 1) <> '@'
                                          AND index_class.relname = leaf.relname || '_' || expected_index.suffix)
                                         OR (
                                             left(expected_index.suffix, 1) = '@'
                                             AND EXISTS (
                                                 SELECT 1
                                                   FROM pg_catalog.pg_inherits AS index_inheritance
                                                   JOIN pg_catalog.pg_class AS parent_index
                                                     ON parent_index.oid = index_inheritance.inhparent
                                                  WHERE index_inheritance.inhrelid = index_class.oid
                                                    AND parent_index.relname = substr(expected_index.suffix, 2)
                                                    AND parent_index.relnamespace = 'public'::regnamespace
                                             )
                                         )
                                     )
                              )
                       )
                       -- A valid partition has one cloned, canonical
                       -- isolation policy.  Record this as a family health
                       -- bit so ordinary project provisioning remains epoch
                       -- stable while a leaf ``USING (true)`` drift fences
                       -- cutover and activation.
                       AND (
                           SELECT count(*)
                             FROM pg_catalog.pg_policy AS child_policy
                            WHERE child_policy.polrelid = leaf.oid
                       ) = 1
                       AND EXISTS (
                           SELECT 1
                             FROM pg_catalog.pg_policy AS child_policy
                             JOIN pg_catalog.pg_policy AS parent_policy
                               ON parent_policy.polrelid = parent.oid
                            WHERE child_policy.polrelid = leaf.oid
                              AND child_policy.polname = leaf.relname || '_isolation'
                              AND parent_policy.polname = parent.relname || '_isolation'
                              AND child_policy.polcmd = parent_policy.polcmd
                              AND child_policy.polpermissive = parent_policy.polpermissive
                              AND COALESCE((
                                  SELECT string_agg(COALESCE(policy_role.rolname, 'PUBLIC'), ','
                                      ORDER BY policy_member.ordinality)
                                    FROM unnest(child_policy.polroles) WITH ORDINALITY
                                         AS policy_member(role_oid, ordinality)
                                    LEFT JOIN pg_catalog.pg_roles AS policy_role
                                      ON policy_role.oid = policy_member.role_oid
                              ), '') IS NOT DISTINCT FROM COALESCE((
                                  SELECT string_agg(COALESCE(policy_role.rolname, 'PUBLIC'), ','
                                      ORDER BY policy_member.ordinality)
                                    FROM unnest(parent_policy.polroles) WITH ORDINALITY
                                         AS policy_member(role_oid, ordinality)
                                    LEFT JOIN pg_catalog.pg_roles AS policy_role
                                      ON policy_role.oid = policy_member.role_oid
                              ), '')
                              AND COALESCE(
                                  pg_catalog.pg_get_expr(child_policy.polqual, child_policy.polrelid), ''
                              ) = COALESCE(
                                  pg_catalog.pg_get_expr(parent_policy.polqual, parent_policy.polrelid), ''
                              )
                              AND COALESCE(
                                  pg_catalog.pg_get_expr(child_policy.polwithcheck, child_policy.polrelid), ''
                              ) = COALESCE(
                                  pg_catalog.pg_get_expr(parent_policy.polwithcheck, parent_policy.polrelid), ''
                              )
                       )
                       -- Exact non-internal parent trigger clones preserve
                       -- terminal and immutable-row enforcement on leaves.
                       AND NOT EXISTS (
                           SELECT 1
                             FROM pg_catalog.pg_trigger AS parent_trigger
                            WHERE parent_trigger.tgrelid = parent.oid
                              AND NOT parent_trigger.tgisinternal
                              AND NOT EXISTS (
                                  SELECT 1
                                    FROM pg_catalog.pg_trigger AS child_trigger
                                   WHERE child_trigger.tgrelid = leaf.oid
                                     AND NOT child_trigger.tgisinternal
                                     AND child_trigger.tgparentid = parent_trigger.oid
                                     AND child_trigger.tgfoid = parent_trigger.tgfoid
                                     AND child_trigger.tgtype = parent_trigger.tgtype
                                     AND child_trigger.tgenabled = parent_trigger.tgenabled
                                     AND child_trigger.tgargs = parent_trigger.tgargs
                                     AND child_trigger.tgname = parent_trigger.tgname
                                     AND child_trigger.tgqual::text IS NOT DISTINCT FROM parent_trigger.tgqual::text
                                     AND COALESCE((
                                         SELECT string_agg(attribute.attname, ',' ORDER BY member.ordinality)
                                           FROM unnest(child_trigger.tgattr::smallint[]) WITH ORDINALITY
                                                AS member(attnum, ordinality)
                                           JOIN pg_catalog.pg_attribute AS attribute
                                             ON attribute.attrelid = child_trigger.tgrelid
                                            AND attribute.attnum = member.attnum
                                     ), '') IS NOT DISTINCT FROM COALESCE((
                                         SELECT string_agg(attribute.attname, ',' ORDER BY member.ordinality)
                                           FROM unnest(parent_trigger.tgattr::smallint[]) WITH ORDINALITY
                                                AS member(attnum, ordinality)
                                           JOIN pg_catalog.pg_attribute AS attribute
                                             ON attribute.attrelid = parent_trigger.tgrelid
                                            AND attribute.attnum = member.attnum
                                     ), '')
                                     AND child_trigger.tgoldtable IS NOT DISTINCT FROM parent_trigger.tgoldtable
                                     AND child_trigger.tgnewtable IS NOT DISTINCT FROM parent_trigger.tgnewtable
                                     AND child_trigger.tgdeferrable IS NOT DISTINCT FROM parent_trigger.tgdeferrable
                                     AND child_trigger.tginitdeferred IS NOT DISTINCT FROM parent_trigger.tginitdeferred
                                     AND (
                                         (parent_trigger.tgconstraint = 0 AND child_trigger.tgconstraint = 0)
                                         OR EXISTS (
                                             SELECT 1
                                               FROM pg_catalog.pg_constraint AS parent_trigger_constraint
                                               JOIN pg_catalog.pg_constraint AS child_trigger_constraint
                                                 ON child_trigger_constraint.oid = child_trigger.tgconstraint
                                              WHERE parent_trigger_constraint.oid = parent_trigger.tgconstraint
                                                AND (
                                                    child_trigger_constraint.conparentid = parent_trigger_constraint.oid
                                                    OR (
                                                        child_trigger_constraint.conparentid = 0
                                                        AND child_trigger_constraint.conname = parent_trigger_constraint.conname
                                                        AND child_trigger_constraint.contype = parent_trigger_constraint.contype
                                                        AND child_trigger_constraint.condeferrable
                                                            IS NOT DISTINCT FROM parent_trigger_constraint.condeferrable
                                                        AND child_trigger_constraint.condeferred
                                                            IS NOT DISTINCT FROM parent_trigger_constraint.condeferred
                                                        AND pg_catalog.pg_get_constraintdef(child_trigger_constraint.oid, true)
                                                            IS NOT DISTINCT FROM pg_catalog.pg_get_constraintdef(parent_trigger_constraint.oid, true)
                                                    )
                                                )
                                         )
                                     )
                              )
                       )
                       AND NOT EXISTS (
                           SELECT 1
                             FROM pg_catalog.pg_trigger AS child_trigger
                            WHERE child_trigger.tgrelid = leaf.oid
                              AND NOT child_trigger.tgisinternal
                              AND NOT EXISTS (
                                  SELECT 1
                                    FROM pg_catalog.pg_trigger AS parent_trigger
                                   WHERE parent_trigger.tgrelid = parent.oid
                                     AND NOT parent_trigger.tgisinternal
                                     AND child_trigger.tgparentid = parent_trigger.oid
                                     AND child_trigger.tgfoid = parent_trigger.tgfoid
                                     AND child_trigger.tgtype = parent_trigger.tgtype
                                     AND child_trigger.tgenabled = parent_trigger.tgenabled
                                     AND child_trigger.tgargs = parent_trigger.tgargs
                                     AND child_trigger.tgname = parent_trigger.tgname
                                     AND child_trigger.tgqual::text IS NOT DISTINCT FROM parent_trigger.tgqual::text
                                     AND COALESCE((
                                         SELECT string_agg(attribute.attname, ',' ORDER BY member.ordinality)
                                           FROM unnest(child_trigger.tgattr::smallint[]) WITH ORDINALITY
                                                AS member(attnum, ordinality)
                                           JOIN pg_catalog.pg_attribute AS attribute
                                             ON attribute.attrelid = child_trigger.tgrelid
                                            AND attribute.attnum = member.attnum
                                     ), '') IS NOT DISTINCT FROM COALESCE((
                                         SELECT string_agg(attribute.attname, ',' ORDER BY member.ordinality)
                                           FROM unnest(parent_trigger.tgattr::smallint[]) WITH ORDINALITY
                                                AS member(attnum, ordinality)
                                           JOIN pg_catalog.pg_attribute AS attribute
                                             ON attribute.attrelid = parent_trigger.tgrelid
                                            AND attribute.attnum = member.attnum
                                     ), '')
                                     AND child_trigger.tgoldtable IS NOT DISTINCT FROM parent_trigger.tgoldtable
                                     AND child_trigger.tgnewtable IS NOT DISTINCT FROM parent_trigger.tgnewtable
                                     AND child_trigger.tgdeferrable IS NOT DISTINCT FROM parent_trigger.tgdeferrable
                                     AND child_trigger.tginitdeferred IS NOT DISTINCT FROM parent_trigger.tginitdeferred
                                     AND (
                                         (parent_trigger.tgconstraint = 0 AND child_trigger.tgconstraint = 0)
                                         OR EXISTS (
                                             SELECT 1
                                               FROM pg_catalog.pg_constraint AS parent_trigger_constraint
                                               JOIN pg_catalog.pg_constraint AS child_trigger_constraint
                                                 ON child_trigger_constraint.oid = child_trigger.tgconstraint
                                              WHERE parent_trigger_constraint.oid = parent_trigger.tgconstraint
                                                AND (
                                                    child_trigger_constraint.conparentid = parent_trigger_constraint.oid
                                                    OR (
                                                        child_trigger_constraint.conparentid = 0
                                                        AND child_trigger_constraint.conname = parent_trigger_constraint.conname
                                                        AND child_trigger_constraint.contype = parent_trigger_constraint.contype
                                                        AND child_trigger_constraint.condeferrable
                                                            IS NOT DISTINCT FROM parent_trigger_constraint.condeferrable
                                                        AND child_trigger_constraint.condeferred
                                                            IS NOT DISTINCT FROM parent_trigger_constraint.condeferred
                                                        AND pg_catalog.pg_get_constraintdef(child_trigger_constraint.oid, true)
                                                            IS NOT DISTINCT FROM pg_catalog.pg_get_constraintdef(parent_trigger_constraint.oid, true)
                                                    )
                                                )
                                         )
                                     )
                              )
                       )
                       AND NOT EXISTS (
                           SELECT 1
                             FROM pg_catalog.pg_constraint AS child_constraint
                            WHERE child_constraint.conrelid = leaf.oid
                              AND NOT EXISTS (
                                  SELECT 1
                                    FROM pg_catalog.pg_constraint AS parent_constraint
                                   WHERE parent_constraint.conrelid = parent.oid
                                     AND (
                                         child_constraint.conparentid = parent_constraint.oid
                                         OR (
                                             child_constraint.conparentid = 0
                                             AND child_constraint.conname = parent_constraint.conname
                                             AND child_constraint.contype = parent_constraint.contype
                                             AND child_constraint.condeferrable = parent_constraint.condeferrable
                                             AND child_constraint.condeferred = parent_constraint.condeferred
                                             AND pg_catalog.pg_get_constraintdef(child_constraint.oid, true)
                                                 = pg_catalog.pg_get_constraintdef(parent_constraint.oid, true)
                                         )
                                     )
                              )
                       )
                       AND NOT EXISTS (
                           SELECT 1
                             FROM pg_catalog.pg_constraint AS parent_constraint
                            WHERE parent_constraint.conrelid = parent.oid
                              AND NOT EXISTS (
                                  SELECT 1
                                    FROM pg_catalog.pg_constraint AS child_constraint
                                   WHERE child_constraint.conrelid = leaf.oid
                                     AND (
                                         child_constraint.conparentid = parent_constraint.oid
                                         OR (
                                             child_constraint.conparentid = 0
                                             AND child_constraint.conname = parent_constraint.conname
                                             AND child_constraint.contype = parent_constraint.contype
                                             AND child_constraint.condeferrable = parent_constraint.condeferrable
                                             AND child_constraint.condeferred = parent_constraint.condeferred
                                             AND pg_catalog.pg_get_constraintdef(child_constraint.oid, true)
                                                 = pg_catalog.pg_get_constraintdef(parent_constraint.oid, true)
                                         )
                                     )
                              )
                       )
                       -- Column identity is inherited by declarative
                       -- partitions, but an attached leaf can still be
                       -- constructed from a shape which merely happens to
                       -- accept the current rows.  Bind every physical
                       -- column (including typmod, collation, generated and
                       -- identity markers) in both directions before the
                       -- profile considers that leaf healthy.
                       AND NOT EXISTS (
                           SELECT 1
                             FROM pg_catalog.pg_attribute AS child_attribute
                             LEFT JOIN pg_catalog.pg_attribute AS parent_attribute
                               ON parent_attribute.attrelid = parent.oid
                              AND parent_attribute.attname = child_attribute.attname
                              AND parent_attribute.attnum > 0
                              AND NOT parent_attribute.attisdropped
                             LEFT JOIN pg_catalog.pg_attrdef AS child_default
                               ON child_default.adrelid = child_attribute.attrelid
                              AND child_default.adnum = child_attribute.attnum
                             LEFT JOIN pg_catalog.pg_attrdef AS parent_default
                               ON parent_default.adrelid = parent_attribute.attrelid
                              AND parent_default.adnum = parent_attribute.attnum
                            WHERE child_attribute.attrelid = leaf.oid
                              AND child_attribute.attnum > 0
                              AND NOT child_attribute.attisdropped
                              AND (
                                  parent_attribute.attnum IS NULL
                                  OR child_attribute.atttypid IS DISTINCT FROM parent_attribute.atttypid
                                  OR child_attribute.atttypmod IS DISTINCT FROM parent_attribute.atttypmod
                                  OR child_attribute.attcollation IS DISTINCT FROM parent_attribute.attcollation
                                  OR child_attribute.attnotnull IS DISTINCT FROM parent_attribute.attnotnull
                                  OR child_attribute.attgenerated IS DISTINCT FROM parent_attribute.attgenerated
                                  OR child_attribute.attidentity IS DISTINCT FROM parent_attribute.attidentity
                                  OR child_attribute.attstorage IS DISTINCT FROM parent_attribute.attstorage
                                  OR child_attribute.attcompression IS DISTINCT FROM parent_attribute.attcompression
                                  OR COALESCE(
                                      pg_catalog.pg_get_expr(child_default.adbin, child_default.adrelid), ''
                                  ) IS DISTINCT FROM COALESCE(
                                      pg_catalog.pg_get_expr(parent_default.adbin, parent_default.adrelid), ''
                                  )
                              )
                       )
                       AND NOT EXISTS (
                           SELECT 1
                             FROM pg_catalog.pg_attribute AS parent_attribute
                             LEFT JOIN pg_catalog.pg_attribute AS child_attribute
                               ON child_attribute.attrelid = leaf.oid
                              AND child_attribute.attname = parent_attribute.attname
                              AND child_attribute.attnum > 0
                              AND NOT child_attribute.attisdropped
                             LEFT JOIN pg_catalog.pg_attrdef AS child_default
                               ON child_default.adrelid = child_attribute.attrelid
                              AND child_default.adnum = child_attribute.attnum
                             LEFT JOIN pg_catalog.pg_attrdef AS parent_default
                               ON parent_default.adrelid = parent_attribute.attrelid
                              AND parent_default.adnum = parent_attribute.attnum
                            WHERE parent_attribute.attrelid = parent.oid
                              AND parent_attribute.attnum > 0
                              AND NOT parent_attribute.attisdropped
                              AND (
                                  child_attribute.attnum IS NULL
                                  OR child_attribute.attstorage IS DISTINCT FROM parent_attribute.attstorage
                                  OR child_attribute.attcompression IS DISTINCT FROM parent_attribute.attcompression
                                  OR COALESCE(
                                      pg_catalog.pg_get_expr(child_default.adbin, child_default.adrelid), ''
                                  ) IS DISTINCT FROM COALESCE(
                                      pg_catalog.pg_get_expr(parent_default.adbin, parent_default.adrelid), ''
                                  )
                              )
                       )
                   )
               ),
               true
           )
           AND NOT EXISTS (
               SELECT 1
                 FROM public.project AS required_project
                WHERE required_project.status IN ('active', 'suspended')
                  AND required_project.deleted_at IS NULL
                  AND NOT EXISTS (
                      SELECT 1
                        FROM pg_catalog.pg_inherits AS expected_inheritance
                        JOIN pg_catalog.pg_class AS expected_leaf
                          ON expected_leaf.oid = expected_inheritance.inhrelid
                        JOIN pg_catalog.pg_namespace AS expected_namespace
                          ON expected_namespace.oid = expected_leaf.relnamespace
                       WHERE expected_inheritance.inhparent = parent.oid
                         AND expected_namespace.nspname = 'public'
                         AND pg_catalog.pg_get_expr(expected_leaf.relpartbound, expected_leaf.oid)
                             = pg_catalog.format('FOR VALUES IN (%L)', required_project.project_id)
                  )
           ) AS healthy
      FROM partition_family AS family
      LEFT JOIN pg_catalog.pg_class AS parent
        ON parent.relname = family.parent_name
       AND parent.relnamespace = 'public'::regnamespace
      LEFT JOIN pg_catalog.pg_inherits AS inheritance ON inheritance.inhparent = parent.oid
      LEFT JOIN pg_catalog.pg_class AS leaf ON leaf.oid = inheritance.inhrelid
      LEFT JOIN pg_catalog.pg_namespace AS leaf_namespace ON leaf_namespace.oid = leaf.relnamespace
     GROUP BY family.parent_name, parent.oid
), raw_entry AS (
    SELECT 'profile:' || profile::text AS identity
    UNION ALL
    -- yoyo 9.0.0's lock relation is a real public control object, not a
    -- name-only exception.  Its relation/column/constraint/index entries are
    -- included through ``relation_set``; this sentinel makes an underscored
    -- homonym or a missing expected control relation profile-visible too.
    SELECT 'yoyo-topology:'
           || (pg_catalog.to_regclass('public.yoyo_lock') IS NOT NULL)::text
           || ':' || (pg_catalog.to_regclass('public._yoyo_lock') IS NOT NULL)::text
    UNION ALL
    SELECT 'partition-shape:' || parent_name || ':' || healthy::text
      FROM partition_health
    UNION ALL
    SELECT 'relation:' || stable_identity || ':' || relkind::text || ':'
           || owner_name || ':'
           || relrowsecurity::text || ':' || relforcerowsecurity::text || ':'
           || relpersistence::text || ':' || relispartition::text || ':' || relreplident::text || ':'
           || access_method_name || ':'
           || COALESCE(array_to_string(reloptions, ','), '') || ':'
           || CASE WHEN is_partition
                THEN 'partition:' || (nspname = 'public')::text || ':' || (partition_bound IS NOT NULL)::text
                ELSE '' END
      FROM relation_set
     WHERE NOT is_partition
    UNION ALL
    SELECT 'schema-owner:' || namespace.nspname || ':' || owner_role.rolname
      FROM profiled_namespace AS namespace
      JOIN pg_catalog.pg_roles AS owner_role ON owner_role.oid = namespace.nspowner
    UNION ALL
    -- Extension provenance is part of the durable schema profile.  Record
    -- both the pinned extension tuple and each catalog member by PostgreSQL's
    -- semantic identity (never an OID), so an extra extension or a member
    -- silently detached/replaced under the same schema cannot pass a receipt
    -- recheck.
    SELECT 'extension:' || extension.extname || ':' || extension.extversion || ':'
           || namespace.nspname || ':' || owner_role.rolname
      FROM pg_catalog.pg_extension AS extension
      JOIN pg_catalog.pg_namespace AS namespace ON namespace.oid = extension.extnamespace
      JOIN pg_catalog.pg_roles AS owner_role ON owner_role.oid = extension.extowner
    UNION ALL
    SELECT 'extension-member:' || extension.extname || ':' || object_identity.type || ':'
           || COALESCE(object_identity.schema, '') || ':' || COALESCE(object_identity.name, '')
           || ':' || object_identity.identity
      FROM pg_catalog.pg_extension AS extension
      JOIN pg_catalog.pg_depend AS dependency
        ON dependency.refclassid = 'pg_extension'::regclass
       AND dependency.refobjid = extension.oid
       AND dependency.deptype = 'e'
      CROSS JOIN LATERAL pg_catalog.pg_identify_object(
          dependency.classid, dependency.objid, dependency.objsubid
      ) AS object_identity
    UNION ALL
    SELECT 'object-owner:' || relation.stable_identity || ':'
           || relation.relkind::text || ':' || relation.owner_name
      FROM relation_set AS relation
     WHERE NOT relation.is_partition
    UNION ALL
    SELECT 'routine-owner:' || namespace.nspname || '.' || routine.proname || '('
           || pg_catalog.pg_get_function_identity_arguments(routine.oid) || '):' || owner_role.rolname
      FROM pg_catalog.pg_proc AS routine
      JOIN profiled_namespace AS namespace ON namespace.oid = routine.pronamespace
      JOIN pg_catalog.pg_roles AS owner_role ON owner_role.oid = routine.proowner
    UNION ALL
    SELECT 'type-owner:' || namespace.nspname || '.' || type.typname || ':' || owner_role.rolname
      FROM pg_catalog.pg_type AS type
      JOIN profiled_namespace AS namespace ON namespace.oid = type.typnamespace
      JOIN pg_catalog.pg_roles AS owner_role ON owner_role.oid = type.typowner
      LEFT JOIN pg_catalog.pg_class AS type_relation ON type_relation.oid = type.typrelid
      LEFT JOIN pg_catalog.pg_inherits AS type_inheritance
        ON type_inheritance.inhrelid = type_relation.oid
      LEFT JOIN pg_catalog.pg_class AS type_parent ON type_parent.oid = type_inheritance.inhparent
      LEFT JOIN pg_catalog.pg_type AS element_type ON element_type.oid = type.typelem
      LEFT JOIN pg_catalog.pg_class AS element_relation ON element_relation.oid = element_type.typrelid
      LEFT JOIN pg_catalog.pg_inherits AS element_inheritance
        ON element_inheritance.inhrelid = element_relation.oid
      LEFT JOIN pg_catalog.pg_class AS element_parent ON element_parent.oid = element_inheritance.inhparent
     WHERE (type.typrelid = 0 OR type_parent.oid IS NULL)
       AND (element_type.oid IS NULL OR element_type.typrelid = 0 OR element_parent.oid IS NULL)
    UNION ALL
    SELECT 'policy:' || relation.stable_identity || '.' || policy.polname || ':'
           || policy.polcmd::text || ':' || policy.polpermissive::text || ':'
           || COALESCE(policy_roles.names, '') || ':'
           || COALESCE(pg_catalog.pg_get_expr(policy.polqual, policy.polrelid), '') || ':'
           || COALESCE(pg_catalog.pg_get_expr(policy.polwithcheck, policy.polrelid), '')
      FROM pg_catalog.pg_policy AS policy JOIN relation_set AS relation ON relation.oid = policy.polrelid
      LEFT JOIN LATERAL (
          SELECT string_agg(role.rolname, ',' ORDER BY role.rolname) AS names
            FROM pg_catalog.pg_roles AS role
           WHERE role.oid = ANY(policy.polroles)
      ) AS policy_roles ON true
     WHERE NOT relation.is_partition
    UNION ALL
    SELECT 'constraint:' || relation.stable_identity || '.'
           || CASE
                WHEN relation.is_partition
                 AND constraint_row.conname LIKE relation.relname || '%' THEN '<generated>'
                ELSE constraint_row.conname
              END || ':' || constraint_row.contype::text || ':'
           || constraint_row.condeferrable::text || ':' || constraint_row.condeferred::text || ':'
           || pg_catalog.pg_get_constraintdef(constraint_row.oid, true)
      FROM pg_catalog.pg_constraint AS constraint_row
      JOIN relation_set AS relation ON relation.oid = constraint_row.conrelid
     WHERE NOT relation.is_partition
    UNION ALL
    SELECT 'trigger:' || relation.stable_identity || '.' || trigger.tgname || ':'
           || trigger.tgtype::text || ':' || trigger.tgenabled::text || ':'
           || trigger.tgfoid::regprocedure::text || ':' || encode(trigger.tgargs, 'hex') || ':'
           || COALESCE(pg_catalog.pg_get_expr(trigger.tgqual, trigger.tgrelid), '') || ':'
           || COALESCE(trigger_columns.names, '') || ':'
           || COALESCE(trigger.tgoldtable, '') || ':' || COALESCE(trigger.tgnewtable, '') || ':'
           -- ``tgconstraint`` is an allocation-specific OID for a constraint
           -- trigger.  Bind the semantic presence here; the matching
           -- constraint tuple above binds its stable name and definition.
           || CASE WHEN trigger.tgconstraint = 0 THEN '0' ELSE 'constraint' END || ':'
           || trigger.tgdeferrable::text || ':'
           || trigger.tginitdeferred::text || ':' || trigger.tgparentid::text
      FROM pg_catalog.pg_trigger AS trigger JOIN relation_set AS relation ON relation.oid = trigger.tgrelid
      LEFT JOIN LATERAL (
          SELECT string_agg(attribute.attname, ',' ORDER BY member.ordinality) AS names
            FROM unnest(trigger.tgattr::smallint[]) WITH ORDINALITY AS member(attnum, ordinality)
            JOIN pg_catalog.pg_attribute AS attribute
              ON attribute.attrelid = trigger.tgrelid
             AND attribute.attnum = member.attnum
      ) AS trigger_columns ON true
     WHERE NOT trigger.tgisinternal AND NOT relation.is_partition
    UNION ALL
    SELECT 'rule:' || relation.stable_identity || '.' || rule.rulename || ':'
           || pg_catalog.pg_get_ruledef(rule.oid, true)
      FROM pg_catalog.pg_rewrite AS rule
      JOIN relation_set AS relation ON relation.oid = rule.ev_class
     WHERE rule.rulename <> '_RETURN' AND NOT relation.is_partition
    UNION ALL
    SELECT 'index:' || relation.stable_identity || ':' || index_namespace.nspname || '.' || index_relation.relname || ':'
           || index_relation.relkind::text || ':' || index_data.indisvalid::text || ':'
           || index_data.indisready::text || ':' || index_data.indislive::text || ':'
           || index_data.indcheckxmin::text || ':'
           || index_data.indisunique::text || ':' || index_data.indisprimary::text || ':'
           || index_data.indisexclusion::text || ':' || index_data.indisclustered::text || ':'
           || index_data.indisreplident::text || ':' || index_data.indnullsnotdistinct::text || ':'
           || index_data.indimmediate::text || ':' || index_relation.relpersistence::text || ':'
           || COALESCE(array_to_string(index_relation.reloptions, ','), '') || ':'
           || index_data.indoption::text || ':' || index_data.indnkeyatts::text || ':'
           || index_data.indnatts::text || ':' || index_data.indcollation::text || ':'
           || COALESCE(pg_catalog.pg_get_expr(index_data.indpred, index_data.indrelid), '') || ':'
           || COALESCE(pg_catalog.pg_get_expr(index_data.indexprs, index_data.indrelid), '') || ':'
           || access_method.amname || ':' || COALESCE(opclasses.names, '')
      FROM pg_catalog.pg_index AS index_data
      JOIN relation_set AS relation ON relation.oid = index_data.indrelid
      JOIN pg_catalog.pg_class AS index_relation ON index_relation.oid = index_data.indexrelid
      JOIN pg_catalog.pg_namespace AS index_namespace ON index_namespace.oid = index_relation.relnamespace
      JOIN pg_catalog.pg_am AS access_method ON access_method.oid = index_relation.relam
      LEFT JOIN LATERAL (
          SELECT string_agg(op_namespace.nspname || '.' || opclass.opcname, ',' ORDER BY keys.ordinality) AS names
            FROM unnest(index_data.indclass) WITH ORDINALITY AS keys(opclass_oid, ordinality)
            JOIN pg_catalog.pg_opclass AS opclass ON opclass.oid = keys.opclass_oid
            JOIN pg_catalog.pg_namespace AS op_namespace ON op_namespace.oid = opclass.opcnamespace
      ) AS opclasses ON true
     WHERE NOT relation.is_partition
    UNION ALL
    SELECT 'column:' || relation.stable_identity || '.' || attribute.attname || ':'
           || attribute.atttypid::regtype::text || ':' || attribute.atttypmod::text || ':'
           || attribute.attcollation::regcollation::text || ':' || attribute.attnotnull::text || ':'
           || attribute.attgenerated::text || ':' || attribute.attidentity::text || ':'
           || attribute.attstorage::text || ':' || attribute.attcompression::text || ':'
           || COALESCE(pg_catalog.pg_get_expr(default_value.adbin, default_value.adrelid), '')
      FROM pg_catalog.pg_attribute AS attribute
      JOIN relation_set AS relation ON relation.oid = attribute.attrelid
      LEFT JOIN pg_catalog.pg_attrdef AS default_value ON default_value.adrelid = attribute.attrelid
        AND default_value.adnum = attribute.attnum
     WHERE attribute.attnum > 0 AND NOT attribute.attisdropped AND NOT relation.is_partition
    UNION ALL
    SELECT 'function:public.' || routine.proname || '('
           || pg_catalog.pg_get_function_identity_arguments(routine.oid) || '):'
           || owner_role.rolname || ':' || pg_catalog.pg_get_functiondef(routine.oid)
      FROM pg_catalog.pg_proc AS routine
      JOIN pg_catalog.pg_roles AS owner_role ON owner_role.oid = routine.proowner
     WHERE routine.pronamespace = 'public'::regnamespace
       AND routine.proname IN (
           'project_enforce_lifecycle', 'principal_enforce_immutability',
           'agent_type_enforce_immutability', 'agent_registration_enforce_immutability',
           'principal_grant_enforce_immutability', 'run_owner_enforce_immutability',
           'authority_acl_epoch_append_guard', 'trace_index_enforce_terminal_immutability',
           'trace_learning_job_enforce_transition', 'subject_digests_are_valid',
           'authority_acl_frame', 'authority_acl_set_digest', 'authority_acl_epoch_receipt',
           'authority_acl_profile_tuple_guard', 'authority_acl_profile_actual_tuples',
           'authority_acl_security_assert',
           'authority_schema_profile_actual_tuples', 'authority_schema_security_assert',
           'tracebed_mark_authority_activity', 'tracebed_mark_authority_activity_trigger',
           'tracebed_require_active_grant', 'dead_letter_require_authority_v1',
           'outcome_event_require_authority_v1', 'tracebed_runtime_readiness',
           'tracebed_runtime_prepublication_readiness', 'tracebed_lock_subject_bindings',
           'tracebed_subject_tag_is_valid', 'tracebed_subject_digest',
           'tracebed_envelope_versions_are_valid', 'tracebed_erasure_codes_are_valid',
           'tracebed_mark_erasure_activity', 'tracebed_mark_erasure_activity_trigger',
           'subject_key_enforce_lifecycle', 'erasure_request_enforce_transition',
           'erasure_step_receipt_append_only', 'tracebed_fence_enforce_transition',
           'tracebed_erasure_set_append_only', 'tracebed_run_memory_binding_append_only',
           'tracebed_erasure_project_is_quiesced',
           'tracebed_runtime_erasure_read_allowed',
           'tracebed_runtime_erasure_write_guard',
           'tracebed_run_subject_attribution_guard', 'tracebed_memory_subject_attribution_guard',
           'tracebed_memory_link_subject_attribution_guard',
           'tracebed_memory_item_subject_attribution_guard',
           'tracebed_project_subject_attribution_guard',
           'tracebed_request_erasure', 'tracebed_erasure_request_status',
           'tracebed_open_erasure_guarded_run', 'tracebed_bind_run_subject_tags',
           'tracebed_bind_run_memory', 'tracebed_lock_run_subject_snapshot',
           'tracebed_insert_subject_key_v2',
           'tracebed_assert_erasure_write_allowed',
           'tracebed_runtime_project_readable', 'tracebed_runtime_subjects_visible',
           'tracebed_runtime_run_visible', 'tracebed_runtime_memory_visible',
           'tracebed_enqueue_authorized', 'tracebed_insert_authorized_invalidation',
           'tracebed_worker_queue_claim',
           'tracebed_worker_queue_disposition', 'tracebed_worker_queue_metrics',
           -- E3's executor surface is source-profiled even though no login is
           -- provisioned in c12.  This makes a changed SECURITY DEFINER body,
           -- trigger helper, or hidden direct-write bypass catalog-visible.
           'tracebed_erasure_manifest_is_valid', 'tracebed_erasure_frame',
           'tracebed_erasure_closure_digest', 'tracebed_erasure_manifest_digest',
           'tracebed_erasure_assert_caller', 'tracebed_erasure_assert_lease',
           'tracebed_erasure_capable', 'tracebed_erasure_mint_capability',
           'tracebed_erasure_drop_capability', 'tracebed_erasure_receipt_digest',
           'tracebed_erasure_append_receipt', 'tracebed_erasure_receipt_insert_guard',
           'tracebed_e3_prepare_fenced_request', 'tracebed_e3_fence_receipt',
           'tracebed_erasure_work_transition_guard', 'tracebed_erasure_checkpoint_guard',
           'tracebed_erasure_verified_must_complete', 'tracebed_erasure_request_update_guard',
           'tracebed_erasure_mint_request_capability', 'tracebed_erasure_refresh_late_closure',
           'tracebed_erasure_lock_project', 'tracebed_erasure_drop_project_partitions',
           'tracebed_erasure_tombstone_project',
           'tracebed_erasure_claim_selected',
           'tracebed_erasure_claim_next', 'tracebed_erasure_claim_request',
           'tracebed_erasure_renew', 'tracebed_erasure_release',
           'tracebed_erasure_crypto_step', 'tracebed_erasure_trace_refs_batch',
           'tracebed_erasure_trace_manifest_digest_for_request',
           'tracebed_erasure_seal_trace_manifest', 'tracebed_erasure_prepare_primary',
           'tracebed_erasure_primary_remaining', 'tracebed_erasure_primary_batch',
           'tracebed_erasure_external_work_batch', 'tracebed_erasure_mark_external_work',
           'tracebed_erasure_close_external_step', 'tracebed_erasure_fail',
           'tracebed_erasure_resume_blocked', 'tracebed_erasure_verify_and_complete',
           'tracebed_erasure_inspect', 'tracebed_erasure_request_status_by_actor'
       )
    UNION ALL
    SELECT 'membership:' || granted.rolname || ':' || member.rolname || ':'
           || membership.admin_option::text || ':' || membership.inherit_option::text || ':'
           || membership.set_option::text
      FROM pg_catalog.pg_auth_members AS membership
      JOIN pg_catalog.pg_roles AS granted ON granted.oid = membership.roleid
      JOIN pg_catalog.pg_roles AS member ON member.oid = membership.member
     WHERE granted.rolname IN (
               'tracebed_app','tracebed_api','tracebed_worker',
               'tracebed_api_group','tracebed_worker_group','tracebed_erasure_group'
           )
        OR member.rolname IN (
               'tracebed_app','tracebed_api','tracebed_worker',
               'tracebed_api_group','tracebed_worker_group','tracebed_erasure_group'
           )
), entry AS (
    -- Project partitions are expected to appear and disappear over time.  The
    -- receipt records their canonical *shape* once, while every concrete leaf
    -- still participates in the raw validation above.  This keeps a valid
    -- project provisioning operation from invalidating an append-only epoch.
    SELECT DISTINCT identity FROM raw_entry
)
SELECT pg_catalog.sha256(pg_catalog.convert_to(
    'tracebed.authority-schema-tuple/v1' || chr(31) || identity, 'UTF8'
))
  FROM entry
 WHERE identity IS NOT NULL
$$;

CREATE FUNCTION public.authority_schema_security_assert(
    profile public.authority_acl_profile
) RETURNS bytea
LANGUAGE plpgsql VOLATILE STRICT SECURITY INVOKER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
    actual_digest bytea;
BEGIN
    -- Keep the catalog reader's lock order identical to partition creation;
    -- the c12-only parents do not exist in older authenticated profiles.
    LOCK TABLE ONLY public.memory_item IN ACCESS SHARE MODE;
    LOCK TABLE ONLY public.memory_link IN ACCESS SHARE MODE;
    LOCK TABLE ONLY public.derived_state IN ACCESS SHARE MODE;
    LOCK TABLE ONLY public.trace_index IN ACCESS SHARE MODE;
    LOCK TABLE ONLY public.trace_subject IN ACCESS SHARE MODE;
    LOCK TABLE ONLY public.subject_key IN ACCESS SHARE MODE;
    LOCK TABLE ONLY public.outcome_event IN ACCESS SHARE MODE;
    LOCK TABLE ONLY public.injection_log IN ACCESS SHARE MODE;
    LOCK TABLE ONLY public.retrieval_event IN ACCESS SHARE MODE;
    LOCK TABLE ONLY public.blackboard_entry IN ACCESS SHARE MODE;
    LOCK TABLE ONLY public.invalidation_event IN ACCESS SHARE MODE;
    LOCK TABLE ONLY public.spend_ledger IN ACCESS SHARE MODE;
    LOCK TABLE ONLY public.review_queue IN ACCESS SHARE MODE;
    LOCK TABLE ONLY public.memory_status_log IN ACCESS SHARE MODE;
    LOCK TABLE ONLY public.memory_q_update IN ACCESS SHARE MODE;
    LOCK TABLE ONLY public.trace_learning_job IN ACCESS SHARE MODE;
    LOCK TABLE ONLY public.run_owner IN ACCESS SHARE MODE;
    IF profile = 'cutover_0012'::public.authority_acl_profile THEN
        LOCK TABLE ONLY public.subject_fence IN ACCESS SHARE MODE;
        LOCK TABLE ONLY public.run_fence IN ACCESS SHARE MODE;
        LOCK TABLE ONLY public.erase_run_set IN ACCESS SHARE MODE;
        LOCK TABLE ONLY public.erase_mem_set IN ACCESS SHARE MODE;
        LOCK TABLE ONLY public.run_memory_binding IN ACCESS SHARE MODE;
    END IF;
    IF EXISTS (
        (SELECT tuple_digest FROM public.authority_schema_profile_actual_tuples(profile) AS actual(tuple_digest)
         EXCEPT
         SELECT tuple_digest FROM public.authority_acl_profile_tuple
          WHERE authority_acl_profile_tuple.profile = authority_schema_security_assert.profile
            AND tuple_class = 'schema')
        UNION ALL
        (SELECT tuple_digest FROM public.authority_acl_profile_tuple
          WHERE authority_acl_profile_tuple.profile = authority_schema_security_assert.profile
            AND tuple_class = 'schema'
         EXCEPT
         SELECT tuple_digest FROM public.authority_schema_profile_actual_tuples(profile) AS actual(tuple_digest))
    ) THEN
        RAISE EXCEPTION 'authority profile drift: schema does not match its canonical expected tuples'
            USING ERRCODE = '55000';
    END IF;
    SELECT public.authority_acl_set_digest(COALESCE(array_agg(tuple_digest ORDER BY tuple_digest), ARRAY[]::bytea[]))
      INTO actual_digest
      FROM public.authority_schema_profile_actual_tuples(profile) AS actual(tuple_digest);
    RETURN actual_digest;
END;
$$;

REVOKE ALL PRIVILEGES ON FUNCTION public.authority_acl_security_assert(public.authority_acl_profile)
    FROM PUBLIC, tracebed_app, tracebed_api_group, tracebed_worker_group, tracebed_erasure_group;
REVOKE ALL PRIVILEGES ON FUNCTION public.authority_schema_security_assert(public.authority_acl_profile)
    FROM PUBLIC, tracebed_app, tracebed_api_group, tracebed_worker_group, tracebed_erasure_group;

-- yoyo 9.0.0's public.yoyo_lock is part of the authenticated genuine-0010
-- surface.  Check its whole structural provenance before the manifest is
-- learned: a same-named table, extra rule/trigger/policy, invalid primary
-- index, or delegated ACL must not become epoch zero's "expected" state.
DO $$
DECLARE
    yoyo_oid oid := pg_catalog.to_regclass('public.yoyo_lock');
BEGIN
    IF yoyo_oid IS NULL
       OR pg_catalog.to_regclass('public._yoyo_lock') IS NOT NULL
       OR NOT (
           SELECT relation.relkind = 'r'
              AND relation.relpersistence = 'p'
              AND NOT relation.relispartition
              AND relation.relowner = (SELECT oid FROM pg_catalog.pg_roles WHERE rolname = current_user)
              AND NOT relation.relrowsecurity
              AND NOT relation.relforcerowsecurity
              AND relation.reloptions IS NULL
             FROM pg_catalog.pg_class AS relation WHERE relation.oid = yoyo_oid
       )
       OR EXISTS (
           SELECT 1 FROM pg_catalog.pg_inherits
            WHERE inhrelid = yoyo_oid OR inhparent = yoyo_oid
       )
       OR EXISTS (SELECT 1 FROM pg_catalog.pg_policy WHERE polrelid = yoyo_oid)
       OR EXISTS (SELECT 1 FROM pg_catalog.pg_trigger WHERE tgrelid = yoyo_oid AND NOT tgisinternal)
       OR EXISTS (SELECT 1 FROM pg_catalog.pg_rewrite WHERE ev_class = yoyo_oid AND rulename <> '_RETURN')
       OR (
           SELECT array_agg(
               attribute.attnum::text || '|' || attribute.attname || '|'
               || pg_catalog.format_type(attribute.atttypid, attribute.atttypmod) || '|'
               || attribute.attcollation::text || '|' || attribute.attnotnull::text || '|'
               || attribute.attgenerated::text || '|' || attribute.attidentity::text || '|'
               || attribute.attstorage::text || '|' || attribute.attcompression::text || '|'
               || COALESCE(pg_catalog.pg_get_expr(default_value.adbin, default_value.adrelid), '')
               ORDER BY attribute.attnum
           )
             FROM pg_catalog.pg_attribute AS attribute
             LEFT JOIN pg_catalog.pg_attrdef AS default_value
               ON default_value.adrelid = attribute.attrelid AND default_value.adnum = attribute.attnum
            WHERE attribute.attrelid = yoyo_oid
              AND attribute.attnum > 0 AND NOT attribute.attisdropped
       ) IS DISTINCT FROM ARRAY[
           '1|locked|integer|0|true|||p||1',
           '2|ctime|timestamp without time zone|0|false|||p||',
           '3|pid|integer|0|true|||p||'
       ]
       OR NOT (
           SELECT count(*) = 3
              AND bool_and(
                  constraint_row.convalidated
                  AND NOT constraint_row.condeferrable
                  AND NOT constraint_row.condeferred
                  AND CASE constraint_row.conname
                      WHEN 'yoyo_lock_locked_not_null' THEN constraint_row.contype = 'n'
                           AND constraint_row.conkey = ARRAY[1]::smallint[]
                      WHEN 'yoyo_lock_pid_not_null' THEN constraint_row.contype = 'n'
                           AND constraint_row.conkey = ARRAY[3]::smallint[]
                      WHEN 'yoyo_lock_pkey' THEN constraint_row.contype = 'p'
                           AND constraint_row.conkey = ARRAY[1]::smallint[]
                      ELSE false
                  END
              )
             FROM pg_catalog.pg_constraint AS constraint_row
            WHERE constraint_row.conrelid = yoyo_oid
       )
       OR NOT (
           SELECT count(*) = 1
              AND bool_and(index_data.indisprimary AND index_data.indisvalid AND index_data.indisready
                           AND index_data.indislive AND NOT index_data.indcheckxmin AND index_data.indisunique
                           AND NOT index_data.indisexclusion AND NOT index_data.indisclustered
                           AND NOT index_data.indisreplident AND NOT index_data.indnullsnotdistinct
                           AND index_data.indimmediate AND index_data.indnkeyatts = 1
                           AND index_data.indnatts = 1 AND index_data.indkey = '1'::int2vector
                           AND index_data.indoption = '0'::int2vector
                           AND index_class.relkind = 'i'
                           AND index_class.relpersistence = 'p'
                           AND index_class.reloptions IS NULL)
             FROM pg_catalog.pg_index AS index_data
             JOIN pg_catalog.pg_class AS index_class ON index_class.oid = index_data.indexrelid
             JOIN pg_catalog.pg_namespace AS index_namespace ON index_namespace.oid = index_class.relnamespace
             JOIN pg_catalog.pg_am AS access_method ON access_method.oid = index_class.relam
             JOIN pg_catalog.pg_opclass AS opclass ON opclass.oid = index_data.indclass[0]
             JOIN pg_catalog.pg_namespace AS opclass_namespace ON opclass_namespace.oid = opclass.opcnamespace
            WHERE index_data.indrelid = yoyo_oid
              AND index_namespace.nspname = 'public'
              AND index_class.relname = 'yoyo_lock_pkey'
              AND access_method.amname = 'btree'
              AND opclass_namespace.nspname = 'pg_catalog'
              AND opclass.opcname = 'int4_ops'
              AND index_data.indcollation = '0'::oidvector
       )
       OR EXISTS (
           SELECT 1
             FROM pg_catalog.aclexplode((SELECT relacl FROM pg_catalog.pg_class WHERE oid = yoyo_oid)) AS privilege
             LEFT JOIN pg_catalog.pg_roles AS grantee ON grantee.oid = privilege.grantee
             JOIN pg_catalog.pg_roles AS grantor ON grantor.oid = privilege.grantor
            WHERE grantee.rolname IS DISTINCT FROM current_user
              AND NOT (
                  grantee.rolname = 'tracebed_app'
                  AND privilege.privilege_type IN ('SELECT', 'INSERT', 'UPDATE', 'DELETE')
                  AND grantor.rolname = current_user
                  AND NOT privilege.is_grantable
              )
       )
       OR (
           SELECT array_agg(privilege.privilege_type ORDER BY privilege.privilege_type)
             FROM pg_catalog.aclexplode((SELECT relacl FROM pg_catalog.pg_class WHERE oid = yoyo_oid)) AS privilege
             JOIN pg_catalog.pg_roles AS grantee ON grantee.oid = privilege.grantee
             JOIN pg_catalog.pg_roles AS grantor ON grantor.oid = privilege.grantor
            WHERE grantee.rolname = 'tracebed_app'
              AND grantor.rolname = current_user
              AND NOT privilege.is_grantable
       ) IS DISTINCT FROM ARRAY['DELETE', 'INSERT', 'SELECT', 'UPDATE']
    THEN
        RAISE EXCEPTION 'authority foundation refuses a noncanonical yoyo lock topology'
            USING ERRCODE = '55000';
    END IF;
END
$$;

-- The expected tuple set was inserted above as immutable checked-in
-- canonical data.  The assertions below are intentionally the first
-- catalog-derived operation that can sign epoch zero.

    epoch, profile, profile_version, source_acl_digest, result_acl_digest,
    source_schema_digest, result_schema_digest, yoyo_lock_repair
) VALUES (
    0, 'genuine_0010', 2,
    public.authority_acl_security_assert('genuine_0010'),
    public.authority_acl_security_assert('genuine_0010'),
    public.authority_schema_security_assert('genuine_0010'),
    public.authority_schema_security_assert('genuine_0010'),
    'not_required'
);
